/* SECOND ECOUTEUR DE HAUTEUR — et il visait un cadre en dur.
   Depuis que l'etude d'enveloppe est un module a part, DEUX cadres servent le
   meme document : tous deux annoncent « pan-height ». Celui-ci redimensionnait
   le panorama avec la hauteur de l'enveloppe, et l'enveloppe restait bloquee a
   ses 1600 px de depart. On reconnait l'emetteur par sa fenetre, qui ne se
   confond pas — comme l'ecouteur principal plus haut. */
(function(){
  /* Un cadre de plus a chaque module qui sert ce document : l'empreinte du
     parc annonce elle aussi « pan-height ». Un identifiant oublie ici laisse
     le cadre bloque a ses 1600 px de depart, sans erreur. */
  var SUIVIS = ['pan-sia-iframe', 'enveloppe-iframe', 'empreinte-parc-iframe'];
  window.addEventListener('message', function(ev){
    var d = ev && ev.data;
    if(!d || d.type !== 'pan-height') return;
    var f = null;
    for(var i = 0; i < SUIVIS.length; i++){
      var c = document.getElementById(SUIVIS[i]);
      if(c && c.contentWindow === ev.source){ f = c; break; }
    }
    if(!f) return;
    var h = parseInt(d.height, 10);
    if(!(h > 400 && h < 20000)) return;
    f.style.height = (h + 24) + 'px';
  }, false);
})();


;/* ── bloc 3/59 ── */

/* L'observatoire annonce sa hauteur reelle (message 'obs-height') : on suit,
   pour que le module defile avec la page plutot que dans un cadre etroit.
   La hauteur de depart reste generreuse — si le message n'arrive jamais
   (script bloque, page servie autrement), l'essentiel est deja visible. */
(function(){
  /* Deux canaux, deux cadres. Le panorama n'annoncait pas sa hauteur : il n'en
     avait pas besoin, sa carte remplit ses 1600 px. Mais depuis que le module
     peut repondre « acces reserve », une page de 440 px flotterait au milieu
     d'un cadre douze fois trop grand, et la suite de Sentinel serait poussee
     hors de l'ecran. Chaque cadre suit donc son message. */
  var CADRES = { 'obs-height': 'obs-rd-iframe', 'pan-height': 'pan-sia-iframe' };
  /* TOUS LES CADRES SUIVIS, ET RECONNUS PAR LEUR FENETRE — pas par le type du
     message. Depuis que l'etude d'enveloppe est un module a part, DEUX cadres
     servent le meme document : ils annoncent donc tous deux « pan-height ».
     Router sur le type ferait redimensionner le panorama par la hauteur de
     l'enveloppe, et le second cadre resterait bloque a sa hauteur de depart.
     On identifie l'emetteur par son contentWindow, qui ne se confond pas. */
  var CADRES_TOUS = ['obs-rd-iframe', 'pan-sia-iframe', 'enveloppe-iframe',
                     'empreinte-parc-iframe'];
  function cadreDe(source){
    for(var i = 0; i < CADRES_TOUS.length; i++){
      var f = document.getElementById(CADRES_TOUS[i]);
      if(f && f.contentWindow === source) return f;
    }
    return null;
  }

  /* ── Dire au module ce que le lecteur voit de lui ──────────────────────
     Un cadre de 1600 px n'est jamais vu en entier. Une page embarquee ne peut
     pas connaitre le defilement de son hote — c'est une frontiere de securite
     du navigateur — et sans cette information elle ouvre ses fenetres au
     milieu de SES 1600 px, c'est-a-dire hors de l'ecran. C'est ainsi que les
     six parcours guides « ne s'affichaient pas » : ils s'affichaient, ailleurs.

     On annonce donc la bande visible, en coordonnees du module. Envoi limite
     a une image par rafraichissement : poster a chaque pixel de defilement
     ferait travailler le module pour rien. */
  (function(){
    var enVol = false;
    function annoncer(){
      enVol = false;
      CADRES_TOUS.forEach(function(id){
        var f = document.getElementById(id);
        if(!f || !f.contentWindow) return;
        var r = f.getBoundingClientRect();
        if(r.bottom < 0 || r.top > window.innerHeight) return;   // hors ecran
        try{
          f.contentWindow.postMessage({
            type: 'pan-vue',
            haut: Math.max(0, -r.top),
            bas: Math.max(0, Math.min(r.height, window.innerHeight - r.top))
          }, '*');
        }catch(e){}
      });
    }
    function planifier(){
      if(enVol) return;
      enVol = true;
      requestAnimationFrame(annoncer);
    }
    window.addEventListener('scroll', planifier, { passive: true });
    window.addEventListener('resize', planifier);
    /* Une premiere annonce des que le cadre a charge : sans elle, un lecteur
       qui ouvre un parcours sans avoir defile retombe sur le repli. */
    setTimeout(annoncer, 1200);
    setTimeout(annoncer, 3000);
  })();
  window.addEventListener('message', function(ev){
    var d = ev && ev.data;
    if(!d || !CADRES[d.type]) return;
    /* L'emetteur d'abord ; le type ne sert plus qu'a reconnaitre un message de
       hauteur. Le repli sur la table reste pour un cadre qu'on n'aurait pas
       inscrit dans CADRES_TOUS. */
    var f = cadreDe(ev.source) || document.getElementById(CADRES[d.type]);
    if(!f) return;
    var h = parseInt(d.height, 10);
    /* Bornes : sous 400 px on tient une mesure prise trop tot pour fiable ;
       au-dela de 12000 px on refuse de suivre une valeur aberrante. */
    if(!(h > 400 && h < 12000)) return;
    f.style.height = (h + 24) + 'px';
  }, false);
})();


