/* ── Navigation onglets ── */
window.regsTab = function(tab, el){
  document.querySelectorAll('.regs-tab').forEach(function(t){ t.classList.remove('on'); });
  document.querySelectorAll('.regs-tabpanel').forEach(function(p){ p.classList.remove('on'); });
  /* el peut etre null (appel programmatique) */
  if(el) el.classList.add('on');
  else {
    /* Activer le bon onglet visuellement */
    var tabBtns = document.querySelectorAll('.regs-tab');
    tabBtns.forEach(function(t){
      if((t.getAttribute('onclick')||'').indexOf("'"+tab+"'")!==-1) t.classList.add('on');
    });
  }
  var panel = document.getElementById('regs-panel-'+tab);
  if(panel) panel.classList.add('on');
  if(tab === 'articles') artInit();
};

/* Helper : naviguer vers Reglementations + ouvrir l'onglet Audit */
var _auditPageOrigGo = window.go;
window.go = function(id){
  var r = _auditPageOrigGo ? _auditPageOrigGo.apply(this, arguments) : undefined;
  if(id === "audit-ia-act") setTimeout(auditInit, 50);
  return r;
};

