/* ══ APERCU VEILLE DANS REGLEMENTATIONS — reutilise les vraies donnees RSS/IA ══ */
/* CETTE VARIABLE EST DÉCLARÉE PLUS BAS, DANS UN AUTRE BLOC <script>. Un `var`
   n'est hissé que dans SON bloc : la fonction ci-dessous, définie près de
   quatre mille lignes plus haut, lève donc « VEILLE_DATA_RAW is not defined »
   si elle s'exécute avant que le bloc tardif n'ait été évalué — ce qui arrive
   dès qu'on ouvre Réglementations tôt. L'exception interrompait la suite de
   l'initialisation, en silence. On la déclare ici, sans écraser la valeur si
   elle existe déjà. */
window.VEILLE_DATA_RAW = window.VEILLE_DATA_RAW || [];

function veilleRenderRegsPreview(){
  var b = document.getElementById('veille-list-regs');
  if(!b) return;

  /* CETTE FONCTION DÉPEND D'UN BLOC <script> SITUÉ PLUS BAS. Elle est appelée
     80 ms après l'ouverture de Réglementations ; si la page a été ouverte tôt,
     `veilleFetchRaw` n'existe pas encore et l'appel lève — ce qui interrompait
     le rendu sans rien afficher ni rien dire. On attend le bloc au lieu de
     lever : l'aperçu arrive un instant plus tard, ce qui est très exactement
     ce qu'on veut. */
  if(typeof veilleFetchRaw !== 'function'){
    b.innerHTML = '<div class="reg-loading">Chargement des actualités…</div>';
    setTimeout(veilleRenderRegsPreview, 120);
    return;
  }

  if(VEILLE_DATA_RAW.length === 0){
    b.innerHTML = '<div class="reg-loading">Chargement des actualités…</div>';
    veilleFetchRaw().then(function(){ return fetch('/api/veille/qualifiee'); }).then(function(r){ return r.json(); })
      .then(function(d){
        VEILLE_DATA_RAW = d.items || [];
        veilleRenderRegsPreview();
      })
      .catch(function(){ b.innerHTML = '<div class="reg-empty">Actualités indisponibles pour le moment.</div>'; });
    return;
  }

  var items = VEILLE_DATA_RAW.slice(0,4);
  if(items.length === 0){
    b.innerHTML = '<div class="reg-empty">Aucune actualité à afficher pour le moment.</div>';
    return;
  }

  b.innerHTML = items.map(function(it){
    var imp = IMPACT_LABELS[it.impact] || IMPACT_LABELS.moyen;
    return '<div class="veille-item" style="border-left:3px solid '+imp.color+';padding-left:10px">'
      + '<div class="veille-top"><a class="veille-h" href="'+(it.link||'#')+'" target="_blank" rel="noopener" style="color:inherit;text-decoration:none">'+(it.ico||'')+' '+it.title+'</a><div class="veille-date">'+(it.source||'')+'</div></div>'
      + '<div class="veille-p">'+(it.raison||'')+'</div>'
      + '</div>';
  }).join('');
}

var _veilleRegsOrigGo = window.go;
window.go = function(id){
  var r = _veilleRegsOrigGo ? _veilleRegsOrigGo.apply(this, arguments) : undefined;
  if(id === "regs") setTimeout(veilleRenderRegsPreview, 80);
  return r;
};


