/* ══ COMPARATEUR JURIDICTIONS JS ══ */
(function(){

var CJ_COLORS = ['#B83222','#1C5A8A','#2D7A47','#C47C1A'];

var CJ_DATA = {}; /* peuple dynamiquement depuis JURS via cjBuildDataFromJurs() */
window.CJ_DATA = CJ_DATA;

var CJ_DIMS = ['Sévérité','Transparence','Responsabilité','Souveraineté','Sanctions','Innovation'];
var cjSelected = ['DE','AU']; // défaut

function cjGetColor(i){ return CJ_COLORS[i % CJ_COLORS.length]; }

function cjBuildSelect(){
  var sel = document.getElementById('cj-add-select');
  if(!sel) return;
  sel.innerHTML = '<option value="">Choisir…</option>';
  Object.keys(CJ_DATA).forEach(function(code){
    if(cjSelected.indexOf(code) === -1){
      var opt = document.createElement('option');
      opt.value = code;
      opt.textContent = CJ_DATA[code].flag + ' ' + code + '  ' + CJ_DATA[code].name;
      sel.appendChild(opt);
    }
  });
}

function cjToggleAdd(){
  if(cjSelected.length >= 4){ alert('Maximum 4 pays'); return; }
  var sel = document.getElementById('cj-add-select');
  var btn = document.getElementById('cj-add-btn');
  if(!sel||!btn) return;
  var show = sel.style.display === 'none';
  sel.style.display = show ? 'inline-block' : 'none';
  btn.style.display = show ? 'none' : 'inline-flex';
  if(show) cjBuildSelect();
}

function cjAddCountry(code){
  if(!code) return;
  if(cjSelected.length >= 4){ alert('Maximum 4 pays'); return; }
  if(cjSelected.indexOf(code) === -1) cjSelected.push(code);
  document.getElementById('cj-add-select').style.display = 'none';
  document.getElementById('cj-add-btn').style.display = 'inline-flex';
  cjRender();
}

function cjRemove(code){
  cjSelected = cjSelected.filter(function(c){ return c !== code; });
  cjRender();
}

function cjRender(){
  cjRenderTags();
  cjRenderRadar();
  cjRenderTable();
}

function cjRenderTags(){
  var wrap = document.getElementById('cj-tags');
  if(!wrap) return;
  var html = '';
  cjSelected.forEach(function(code, i){
    var d = CJ_DATA[code];
    if(!d) return; /* garde defensive : ignore les codes sans donnees encore chargees */
    html += '<span class="cj-tag">'
      + '<span class="cj-tag-dot" style="background:'+cjGetColor(i)+'"></span>'
      + '<span style="font-size:10px">'+d.flag+'</span>'
      + ' <span>'+code+'</span>'
      + ' <span style="font-weight:400;color:var(--muted)">'+d.name+'</span>'
      + ' <span class="cj-tag-rm" onclick="cjRemove(\''+code+'\')">×</span>'
      + '</span>';
  });
  html += '<button class="cj-add" id="cj-add-btn" onclick="cjToggleAdd()" title="Ajouter un pays au comparateur (4 maximum)." style="'+(cjSelected.length>=4?'opacity:.4;pointer-events:none':'')+'">+ Ajouter un pays ▾</button>';
  html += '<select id="cj-add-select" class="cj-add-select" style="display:none" onchange="cjAddCountry(this.value)"></select>';
  wrap.innerHTML = html;
}

function cjRenderRadar(){
  var svg = document.getElementById('cj-radar-svg');
  var legend = document.getElementById('cj-radar-legend');
  if(!svg) return;

  var CX=260, CY=185, R=130, N=CJ_DIMS.length;
  function pt(val,i,r){
    var a=(Math.PI*2*i/N)-Math.PI/2;
    return [CX+Math.cos(a)*r*(val/10), CY+Math.sin(a)*r*(val/10)];
  }

  // Grilles
  var grid='';
  [2,4,6,8,10].forEach(function(v){
    var pts=CJ_DIMS.map(function(_,i){ return pt(v,i,R).join(','); });
    grid+='<polygon points="'+pts.join(' ')+'" fill="none" stroke="#E0DDD8" stroke-width="0.8"/>';
    // Label de la grille
    var lp=pt(v,0,R);
    grid+='<text x="'+(lp[0]+4)+'" y="'+(lp[1])+'" font-size="7" fill="#A8A8A8" font-family="monospace">'+v+'</text>';
  });

  // Axes
  var axes='';
  CJ_DIMS.forEach(function(d,i){
    var p=pt(10,i,R);
    axes+='<line x1="'+CX+'" y1="'+CY+'" x2="'+p[0]+'" y2="'+p[1]+'" stroke="#E0DDD8" stroke-width="0.8"/>';
    var lp=pt(10,i,R+24);
    axes+='<text x="'+lp[0]+'" y="'+lp[1]+'" text-anchor="middle" dominant-baseline="middle" font-size="10" font-family="Inter,sans-serif" fill="#767676">'+d+'</text>';
  });

  // Polygones pays
  var polys='';
  cjSelected.forEach(function(code,i){
    var d=CJ_DATA[code];
    var color=cjGetColor(i);
    var pts=CJ_DIMS.map(function(dim,j){ return pt(d.scores[dim]||0,j,R).join(','); });
    polys+='<polygon points="'+pts.join(' ')+'" fill="'+color+'" fill-opacity="0.12" stroke="'+color+'" stroke-width="2" stroke-linejoin="round"/>';
    // Points
    CJ_DIMS.forEach(function(dim,j){
      var p=pt(d.scores[dim]||0,j,R);
      polys+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3" fill="'+color+'" stroke="#fff" stroke-width="1"/>';
    });
  });

  svg.innerHTML = grid+axes+polys;

  // Légende
  if(legend){
    legend.innerHTML = cjSelected.map(function(code,i){
      var d=CJ_DATA[code];
      return '<span class="cj-legend-item"><span class="cj-legend-dot" style="background:'+cjGetColor(i)+'"></span>'+d.flag+' '+d.name+'</span>';
    }).join('');
  }
}

function cjRenderTable(){
  var empty = document.getElementById('cj-empty');
  var table = document.getElementById('cj-table');
  var thead = document.getElementById('cj-thead');
  var tbody = document.getElementById('cj-tbody');
  if(!table||!thead||!tbody) return;

  if(cjSelected.length < 2){
    if(empty) empty.style.display='block';
    table.style.display='none';
    return;
  }
  if(empty) empty.style.display='none';
  table.style.display='table';

  // Header
  var hCells='<th class="cj-th-country">INDICATEUR</th>';
  cjSelected.forEach(function(code,i){
    var d=CJ_DATA[code];
    var color=cjGetColor(i);
    hCells+='<th style="min-width:200px">'
      +'<div class="cj-country-head"><span style="font-size:10px">'+d.flag+'</span>'
      +'<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:'+color+'"></span>'
      +' '+code+'  '+d.name+'</div>'
      +'<div class="cj-country-sub">'+d.cadre+'</div>'
      +'</th>';
  });
  thead.innerHTML='<tr>'+hCells+'</tr>';

  // Rows: scores
  var rows='';
  CJ_DIMS.forEach(function(dim){
    var cells='<td style="font-size:12px;color:var(--ink2);font-weight:500">'+dim+'</td>';
    cjSelected.forEach(function(code,i){
      var d=CJ_DATA[code];
      var val=d.scores[dim]||0;
      var color=cjGetColor(i);
      var pct=Math.round(val*10);
      cells+='<td class="cj-bar-cell"><div class="cj-bar-wrap">'
        +'<span class="cj-bar-val">'+val+'/10</span>'
        +'<div class="cj-bar-track"><div class="cj-bar-fill" style="width:'+pct+'%;background:'+color+'"></div></div>'
        +'</div></td>';
    });
    rows+='<tr>'+cells+'</tr>';
  });

  // Row: badge risque géopolitique
  var badgeCells='<td style="font-size:12px;color:var(--ink2);font-weight:500">Risque géopolitique</td>';
  cjSelected.forEach(function(code){
    var d=CJ_DATA[code];
    badgeCells+='<td><span class="chip '+d.badgeCls+'" style="font-size:9px">● '+d.badge+'</span></td>';
  });
  rows+='<tr>'+badgeCells+'</tr>';

  tbody.innerHTML=rows;
}

// Exposer globalement AVANT le premier rendu (pour que les boutons fonctionnent meme si cjRender() echoue)
window.cjToggleAdd = cjToggleAdd;
window.cjAddCountry = cjAddCountry;
window.cjRemove = cjRemove;
window.cjRender = cjRender; /* indispensable pour que cj_dynamic.js puisse re-render apres synchronisation */

// Peupler CJ_DATA de facon synchrone depuis JURS (deja disponible) avant le premier rendu
if(typeof window.cjBuildDataFromJurs === "function"){ window.cjBuildDataFromJurs(); }

// Init. cjBuildDataFromJurs est declaree PLUS BAS dans le document : au premier
// passage ici elle n'existe pas encore, CJ_DATA est donc vide et cjRender leve
// forcement. On ne tente le rendu que si les donnees sont la ; sinon on attend
// cjRefreshFromJurs, appele a l'ouverture de l'onglet Comparateur. Tenter un
// rendu voue a l'echec ne produisait qu'une erreur rouge permanente en console,
// qui masque les vraies.
try {
  if (Object.keys(CJ_DATA).length) cjRender();
} catch(e){ console.error('cjRender init error:', e); }

})();



