/* Detection de la page active */
function cpcCurrentPageId(){
  /* Methode 1 : variable globale Sentinel */
  if(typeof curPage !== 'undefined' && curPage) return curPage;
  /* Methode 2 : page visible dans le DOM */
  var pages = document.querySelectorAll('.page');
  for(var i=0;i<pages.length;i++){
    var s = window.getComputedStyle(pages[i]);
    if(s.display !== 'none' && s.visibility !== 'hidden'){
      var id = pages[i].id.replace('p-','');
      return id;
    }
  }
  /* Methode 3 : item actif dans sidebar */
  var active = document.querySelector('.sb-item.on, .sb-item.active');
  if(active){
    var oc = active.getAttribute('onclick') || '';
    var m = oc.match(/'([^']+)'/);
    if(m) return m[1];
  }
  return 'default';
}

function cpcGetCtx(){
  var pid = cpcCurrentPageId();
  return PAGE_CTX[pid] || PAGE_CTX['default'];
}

/* Mise a jour de l'UI selon la page et l'API */
function cpcRefreshUI(){
  var ctx = cpcGetCtx();
  var labelEl = document.getElementById('cpcCtxLabel');
  var indEl   = document.getElementById('cpcApiIndicator');
  if(labelEl) labelEl.textContent = ctx.label;
  if(indEl)   indEl.textContent   = (ctx.apiLabel || {})[CUR_API] || CUR_API;

  var tagsEl = document.getElementById('cpcTags');
  if(tagsEl){
    tagsEl.innerHTML = (ctx.tags || []).map(function(tg){
      var safe = tg.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
      var display = tg.length > 30 ? tg.substring(0,29) + '...' : tg;
      return '<button class="cpc-tag" onclick="cpcSend(\'' + safe + '\')">' + display + '</button>';
    }).join('');
  }
}

/* Boutons sélecteur API */
window.cpcSetApi = function(api){
  CUR_API = api;
  document.getElementById('cpcApiMistral').classList.toggle('on', api==='mistral');
  document.getElementById('cpcApiClaude').classList.toggle('on', api==='claude');
  cpcRefreshUI();
};

/* Toggle ouverture panel */
window.cpcToggle = function(){
  OPEN = !OPEN;
  var p = document.getElementById('cpcPanel');
  var b = document.getElementById('cpcBtn');
  if(!p) return;
  if(OPEN){
    p.classList.add('open');
    if(b) b.classList.remove('has-notif');
    if(!READY){ cpcInit(); READY = true; }
    else { cpcRefreshUI(); }
    setTimeout(function(){ var i=document.getElementById('cpcInput'); if(i) i.focus(); }, 100);
  } else {
    p.classList.remove('open');
  }
};

