function srcCurrentPageId(){
  var pages = document.querySelectorAll(".page");
  for(var i=0;i<pages.length;i++){
    if(pages[i].classList.contains("on")){
      return pages[i].id.replace("p-","");
    }
  }
  return "default";
}

function srcResolveKey(id){
  if(SOURCES_DATA[id]) return id;
  if(id && id.indexOf("fiche-") === 0) return "carto";
  if(id === "regs" || id === "simulateur") return SOURCES_DATA[id] ? id : "regs";
  return "default";
}

window.cpcSrcAuth = function(){
  if(sessionStorage.getItem(SRC_AUTH_KEY) === "1"){
    cpcSrcOpenPanel();
    return;
  }
  var overlay = document.getElementById("cpcSrcGate");
  if(overlay) overlay.classList.add("on");
  setTimeout(function(){
    var inp = document.getElementById("cpcSrcPassInput");
    if(inp) inp.focus();
  }, 80);
};

window.cpcSrcCheckPass = function(){
  var inp = document.getElementById("cpcSrcPassInput");
  var err = document.getElementById("cpcSrcPassErr");
  if(!inp) return;
  if(inp.value === SRC_PASS){
    sessionStorage.setItem(SRC_AUTH_KEY, "1");
    document.getElementById("cpcSrcGate").classList.remove("on");
    inp.value = "";
    if(err) err.style.display = "none";
    cpcSrcOpenPanel();
  } else {
    if(err) err.style.display = "block";
    inp.value = "";
    inp.focus();
  }
};

window.cpcSrcCloseGate = function(){
  document.getElementById("cpcSrcGate").classList.remove("on");
};

function cpcSrcOpenPanel(){
  SRC_OPEN = true;
  var panel = document.getElementById("cpcSrcPanel");
  if(panel) panel.classList.add("open");
  cpcSrcRender();
}

window.cpcSrcTogglePanel = function(){
  SRC_OPEN = !SRC_OPEN;
  var panel = document.getElementById("cpcSrcPanel");
  if(!panel) return;
  if(SRC_OPEN){ panel.classList.add("open"); cpcSrcRender(); }
  else panel.classList.remove("open");
};

window.cpcSrcLogout = function(){
  sessionStorage.removeItem(SRC_AUTH_KEY);
  SRC_OPEN = false;
  var panel = document.getElementById("cpcSrcPanel");
  if(panel) panel.classList.remove("open");
};

function cpcSrcRender(){
  var pid = srcResolveKey(srcCurrentPageId());
  var data = SOURCES_DATA[pid] || SOURCES_DATA["default"];
  var titleEl = document.getElementById("cpcSrcTitle");
  var bodyEl  = document.getElementById("cpcSrcBody");
  if(titleEl) titleEl.textContent = data.title;
  if(bodyEl){
    bodyEl.innerHTML = data.items.map(function(it){
      var link = it.url ? '<a class="cpc-src-link" href="' + it.url + '" target="_blank" rel="noopener">Ouvrir la source &#8599;</a>' : "";
      var warnCls = it.warn ? " cpc-src-warn" : "";
      return '<div class="cpc-src-item' + warnCls + '">'
        + '<span class="cpc-src-type">' + it.type + '</span>'
        + '<div class="cpc-src-label">' + it.label + '</div>'
        + '<div class="cpc-src-detail">' + it.detail + '</div>'
        + link
        + '</div>';
    }).join("");
  }
}

