/* ══ AUDIT DE MATURITÉ IA v2 — Scoring AI Act + Livrables IA ══ */
(function(){
'use strict';

/* Mapping des 8 piliers vers les articles du Règlement (UE) 2024/1689 */
var PILLAR_ARTICLES = {
  explicabilite:    {arts:["Art. 13","Art. 86"], label:"Transparence & explication aux déployeurs et personnes concernées"},
  controlabilite:   {arts:["Art. 14"],            label:"Contrôle humain effectif"},
  transparence:     {arts:["Art. 13","Art. 50"],  label:"Transparence et fourniture d'informations"},
  surete:           {arts:["Art. 9","Art. 15"],   label:"Gestion des risques, exactitude et sécurité"},
  equite:           {arts:["Art. 10"],            label:"Gouvernance des données et prévention des biais"},
  gouvernance:      {arts:["Art. 17","Art. 16","Art. 26"], label:"Système de gestion de la qualité et obligations"},
  confidentialite:  {arts:["Art. 15","Art. 10"],  label:"Cybersécurité et protection des données"},
  robustesse:       {arts:["Art. 15","Art. 9"],   label:"Robustesse, exactitude et résilience"}
};

/* Questionnaire d'auto-évaluation — 2 questions par pilier (16 au total) */
/* Chaque réponse vaut 0 (non), 0.5 (partiel), 1 (oui) → score pilier sur 5 */
var MAT_QUESTIONS = {
  explicabilite: [
    {q:"Les décisions du système IA peuvent-elles être expliquées aux utilisateurs et personnes concernées ?", art:"Art. 13 / Art. 86"},
    {q:"Une notice d'utilisation documente-t-elle les capacités, limites et performances du système ?", art:"Art. 13(3)"}
  ],
  controlabilite: [
    {q:"Existe-t-il des mécanismes de supervision humaine permettant d'interrompre ou corriger le système ?", art:"Art. 14"},
    {q:"Les opérateurs sont-ils formés et habilités à superviser le système IA ?", art:"Art. 14(4)"}
  ],
  transparence: [
    {q:"Les utilisateurs sont-ils informés qu'ils interagissent avec un système d'IA ?", art:"Art. 50(1)"},
    {q:"Les contenus générés par IA sont-ils marqués (watermarking) de façon lisible par machine ?", art:"Art. 50(2)"}
  ],
  surete: [
    {q:"Un système de gestion des risques documenté est-il établi et tenu à jour ?", art:"Art. 9"},
    {q:"Des tests sont-ils réalisés avant déploiement pour identifier et atténuer les risques ?", art:"Art. 9(6)-(8)"}
  ],
  equite: [
    {q:"Les jeux de données d'entraînement sont-ils examinés pour détecter et corriger les biais ?", art:"Art. 10(2)(f)"},
    {q:"Les données sont-elles pertinentes, représentatives et de qualité pour la finalité visée ?", art:"Art. 10(3)"}
  ],
  gouvernance: [
    {q:"Un système de gestion de la qualité (SGQ) couvrant l'IA est-il en place ?", art:"Art. 17"},
    {q:"Les rôles et responsabilités (Responsable IA, DPO, Comité) sont-ils définis et documentés ?", art:"Art. 17 / Art. 26"}
  ],
  confidentialite: [
    {q:"Des mesures de cybersécurité protègent-elles le système contre les attaques adversariales ?", art:"Art. 15(5)"},
    {q:"Les données personnelles sont-elles protégées conformément au RGPD et minimisées ?", art:"Art. 10(5)"}
  ],
  robustesse: [
    {q:"Le système maintient-il un niveau d'exactitude approprié, mesuré et documenté ?", art:"Art. 15(1)-(3)"},
    {q:"Le système est-il résilient face aux erreurs, entrées erronées ou conditions dégradées ?", art:"Art. 15(4)"}
  ]
};

/* État des réponses : { secteur: { pilier: [v1, v2] } } */
var MAT_ANSWERS = {};

function matInitAnswers(sectorKey){
  if(!MAT_ANSWERS[sectorKey]){
    MAT_ANSWERS[sectorKey] = {};
    var ref = (window.MAT_SECTORS && window.MAT_SECTORS[sectorKey]) ? window.MAT_SECTORS[sectorKey].pillars : {};
    Object.keys(MAT_QUESTIONS).forEach(function(p){
      /* Pré-remplir selon le profil sectoriel de référence (score/5 → 2 réponses) */
      var refScore = ref[p] || 3;
      var perQ = refScore / 5; /* 0..1 */
      MAT_ANSWERS[sectorKey][p] = [
        perQ >= 0.6 ? 1 : perQ >= 0.3 ? 0.5 : 0,
        perQ >= 0.8 ? 1 : perQ >= 0.5 ? 0.5 : 0
      ];
    });
  }
  return MAT_ANSWERS[sectorKey];
}

/* Calcul du score d'un pilier sur 5 à partir des 2 réponses */
window.matPillarScore = function(sectorKey, pillar){
  var a = (MAT_ANSWERS[sectorKey] && MAT_ANSWERS[sectorKey][pillar]) || [0,0];
  var sum = a[0] + a[1]; /* 0..2 */
  return Math.round(sum / 2 * 5 * 10) / 10; /* 0..5 */
};

window.matGlobalScore = function(sectorKey){
  var keys = Object.keys(MAT_QUESTIONS);
  var sum = keys.reduce(function(acc,p){ return acc + matPillarScore(sectorKey,p); },0);
  return Math.round(sum / keys.length * 10) / 10;
};

/* Niveau de maturité textuel */
window.matMaturityLevel = function(score){
  if(score < 1.5) return {label:"Initial", color:"#B83222", desc:"Pratiques absentes ou ad hoc. Risque de non-conformité élevé."};
  if(score < 2.5) return {label:"Émergent", color:"#C47C1A", desc:"Premières mesures en place mais incomplètes et non systématiques."};
  if(score < 3.5) return {label:"Défini", color:"#C47C1A", desc:"Processus documentés mais déploiement partiel."};
  if(score < 4.5) return {label:"Maîtrisé", color:"#2D7A47", desc:"Conformité largement atteinte, processus mesurés."};
  return {label:"Optimisé", color:"#2D7A47", desc:"Excellence opérationnelle, amélioration continue."};
};

/* Réponse à une question */
window.matAnswer = function(pillar, idx, val){
  var s = MAT_CUR_SECTOR();
  matInitAnswers(s);
  MAT_ANSWERS[s][pillar][idx] = val;
  matRefreshScores();
};

function MAT_CUR_SECTOR(){
  return (typeof window.matGetCur === "function") ? window.matGetCur() : "telecom";
}

/* Rafraîchit l'affichage des scores après réponse (sans re-render complet) */
function matColorFor(sc){ return sc<=2?"#B83222":sc<3.5?"#C47C1A":"#2D7A47"; }

function matRefreshScores(){
  var s = MAT_CUR_SECTOR();
  /* Mettre a jour TOUS les scores (liste piliers + questionnaire) via classes */
  Object.keys(MAT_QUESTIONS).forEach(function(p){
    var sc = matPillarScore(s,p);
    var col = matColorFor(sc);
    document.querySelectorAll('.matq-score[data-pillar="'+p+'"]').forEach(function(el){
      el.textContent = sc.toFixed(1)+"/5"; el.style.color = col;
    });
    document.querySelectorAll('.matq-bar[data-pillar="'+p+'"]').forEach(function(bar){
      bar.style.width = (sc*20)+"%"; bar.style.background = col;
    });
  });
  /* Score global */
  var g = matGlobalScore(s);
  var lvl = matMaturityLevel(g);
  var gEl = document.getElementById("matq-global");
  if(gEl){ gEl.textContent = g.toFixed(1); gEl.style.color = lvl.color; }
  var lEl = document.getElementById("matq-level");
  if(lEl){ lEl.textContent = lvl.label; lEl.style.color = lvl.color; }
  var dEl = document.getElementById("matq-level-desc");
  if(dEl){ dEl.textContent = lvl.desc; }
  /* Score du hero (haut de page) */
  document.querySelectorAll('.mat-hero-score-val').forEach(function(el){
    el.textContent = g.toFixed(1); el.style.color = lvl.color;
  });
  /* Regenerer le radar SVG dynamiquement */
  var holder = document.getElementById("mat-radar-holder");
  if(holder && typeof window.matRadar === "function"){
    var dyn = {};
    (window.MAT_PILLARS||[]).forEach(function(pp){ dyn[pp.id] = matPillarScore(s, pp.id); });
    holder.innerHTML = window.matRadar(dyn);
  }
  /* Mise à jour des boutons radio visuels */
  Object.keys(MAT_QUESTIONS).forEach(function(p){
    MAT_QUESTIONS[p].forEach(function(_,i){
      [0,0.5,1].forEach(function(v){
        var btn = document.getElementById("matq-"+p+"-"+i+"-"+v);
        if(btn){ btn.classList.toggle("on", MAT_ANSWERS[s][p][i]===v); }
      });
    });
  });
}

window.matRefreshScores = matRefreshScores;
window.matInitAnswers = matInitAnswers;
window.MAT_QUESTIONS = MAT_QUESTIONS;
window.PILLAR_ARTICLES = PILLAR_ARTICLES;
window.MAT_ANSWERS = MAT_ANSWERS;

})();



