window.procSetApi = function(api){
  window.MAT_DELIV_API = api;
  var m = document.getElementById("proc-api-mistral"), c = document.getElementById("proc-api-claude");
  if(m) m.classList.toggle("on", api==="mistral");
  if(c) c.classList.toggle("on", api==="claude");
};

window.procFileLoad = function(input){
  var file = input.files && input.files[0];
  if(!file) return;
  var nameEl = document.getElementById("proc-file-name");
  if(file.size > 200000){
    if(nameEl){ nameEl.textContent = "Fichier trop volumineux (max 200 Ko)"; nameEl.style.color = "#B83222"; }
    return;
  }
  var reader = new FileReader();
  reader.onload = function(e){
    procClientData = String(e.target.result || "").substring(0, 12000);
    if(nameEl){ nameEl.textContent = file.name+" ("+Math.round(file.size/1024)+" Ko) ✓"; nameEl.style.color = "#2D7A47"; }
  };
  reader.readAsText(file);
};

window.procGenerate = function(){
  var cur = window.__procCur;
  if(!cur) return;
  var s = window.MAT_SECTORS[cur.sectorKey];
  var api = window.MAT_DELIV_API || "mistral";

  /* Données client : fichier OU textarea */
  var ta = document.getElementById("proc-data-text");
  var typed = ta ? ta.value.trim() : "";
  var clientData = procClientData || typed || "";

  var body = document.getElementById("proc-modal-body");
  if(body){
    body.innerHTML = '<div class="mat-modal-loading"><div class="mat-spinner"></div>'
      + 'Génération du <strong>'+cur.doc.docTitle+'</strong> par '+(api==="claude"?"Claude":"Mistral")+'…<br>'
      + '<span style="font-size:11px;color:var(--muted)">Analyse des scores d audit'+(clientData?", de vos données importées":"")+' et rédaction méthodologique sectorielle.</span></div>';
  }

  var prompt = procBuildPrompt(cur.doc, cur.sectorKey, clientData);

  matCallAIBridge(prompt, api, function(err, text, apiName){
    var b = document.getElementById("proc-modal-body");
    var foot = document.getElementById("proc-modal-foot");
    if(err || !text){
      if(b) b.innerHTML = '<div style="padding:24px;text-align:center;color:var(--accent)">Erreur de génération. Réessayez ou contactez christophe.cerf@outlook.com</div>';
      return;
    }
    cur.content = text; cur.apiName = apiName;
    if(b) b.innerHTML = '<div class="mat-deliv-content">'+window.matMdToHtmlBridge(text)+'</div>';
    if(foot) foot.style.display = "flex";
  }, "audit");
};

function procBuildPrompt(doc, sectorKey, clientData){
  var s = window.MAT_SECTORS[sectorKey];
  var global = window.matGlobalScore(sectorKey);
  var level = window.matMaturityLevel(global).label;
  var pillars = window.MAT_PILLARS.map(function(p){
    return p.label+" "+window.matPillarScore(sectorKey, p.id).toFixed(1)+"/5";
  }).join(", ");
  var specifics = s.specifics.map(function(sp){ return sp.t; }).join(", ");

  var prompt = doc.prompt
    .replace(/{SECTEUR}/g, s.label)
    .replace(/{SYSTEMS}/g, s.systems.join(", "))
    .replace(/{SPECIFICS}/g, specifics)
    .replace(/{GLOBAL}/g, global.toFixed(1))
    .replace(/{LEVEL}/g, level)
    .replace(/{PILLARS}/g, pillars);

  if(clientData){
    prompt += "\n\nDONNEES CLIENT A ANALYSER (fournies par l'utilisateur, integre leur analyse dans le document de maniere pertinente) :\n\"\"\"\n" + clientData + "\n\"\"\"";
  }
  return prompt;
}

window.procClose = function(){
  var m = document.getElementById("proc-modal");
  if(m) m.classList.remove("on");
};
window.procRegen = function(){
  if(window.__procCur) procOpenDoc(window.__procCur.stepNum);
};

