    + '</div>'
    + '<div class="mat-modal-body">' + budgetBodyHTML(b) + '</div>'
    + '<div class="mat-modal-foot">'
    + '<button class="mat-export-btn mat-export-pdf" onclick="matBudgetPDF()" title="Telecharger le budget previsionnel detaille au format PDF.">↓ PDF</button>'
    + '<button class="mat-export-btn mat-export-word" onclick="matBudgetWord()" title="Telecharger le budget previsionnel detaille au format Word.">↓ Word</button>'
    + '<button class="mat-export-btn" style="background:var(--blue);color:#fff" onclick="matBudgetMail()" title="Envoyer la synthese du budget par email a un collegue.">✉ Envoyer a un collegue</button>'
    + '</div></div>';
  modal.innerHTML = html;
  modal.classList.add("on");
