function ensureModal(id){
  var m = document.getElementById(id);
  if(!m){ m = document.createElement("div"); m.id = id; m.className = "mat-modal"; document.body.appendChild(m); }
  return m;
}
window.matCloseModal = function(id){ var m = document.getElementById(id); if(m) m.classList.remove("on"); };

