/* ══ MATRICE RISQUES/IMPACT — connectee au Registre IA reel ══ */
(function(){
'use strict';

/* Mapping classification AI Act -> indice impact (0=Negligeable .. 4=Critique) */
var IMPACT_MAP = { inacceptable:4, haut:3, limite:2, minimal:1, a_evaluer:0 };
/* Mapping statut de conformite -> indice probabilite de non-conformite (0=Tres faible .. 4=Tres elevee) */
var PROB_MAP = { non_conforme:4, a_evaluer:3, en_cours:2, conforme:0 };

var IMP_LABELS = ['Négligeable','Faible','Modéré','Élevé','Critique'];
var PROB_LABELS = ['Très faible','Faible','Moyenne','Élevée','Très élevée'];

var LEVELS = [
  ['mc-vl','mc-l','mc-m','mc-h','mc-h'],
  ['mc-vl','mc-l','mc-m','mc-h','mc-h'],
  ['mc-l','mc-m','mc-m','mc-h','mc-h'],
  ['mc-l','mc-m','mc-h','mc-h','mc-h'],
  ['mc-m','mc-h','mc-h','mc-h','mc-h']
];

var ICO_MAP = {
  telecom:'📶', energie:'⚡', sante:'🩺', finance:'🏦', industrie:'🏭',
  transport:'🚇', it:'💻', public:'🏛'
};
function matriceIco(secteur){
  var key = (secteur||"").toLowerCase();
  for(var k in ICO_MAP){ if(key.indexOf(k) !== -1) return ICO_MAP[k]; }
  return '🤖';
}

function matriceRender(systemes){
  var g = document.getElementById('matrix-grid');
  if(!g) return;

  var head = '<div class="matrix-cell mc-lbl"></div>' + IMP_LABELS.map(function(l){ return '<div class="matrix-cell mc-head">'+l+'</div>'; }).join('');

  /* Positionner chaque systeme dans sa cellule (probIdx, impIdx) */
  var cellSystems = {};
  systemes.forEach(function(s){
    var impIdx = IMPACT_MAP[s.classification] !== undefined ? IMPACT_MAP[s.classification] : 0;
    var probIdx = PROB_MAP[s.statut_conformite] !== undefined ? PROB_MAP[s.statut_conformite] : 2;
    var key = (4-probIdx) + '-' + impIdx; /* ligne 0 = Tres elevee (en haut) */
    if(!cellSystems[key]) cellSystems[key] = [];
    cellSystems[key].push(s);
  });

  var rows = PROB_LABELS.slice().reverse().map(function(p, pi){
    var rowLabel = '<div class="matrix-cell mc-lbl" style="writing-mode:vertical-lr;transform:rotate(180deg);font-size:8px;justify-content:center">'+p+'</div>';
    var cells = LEVELS[pi].map(function(cls, ci){
      var key = pi + '-' + ci;
      var inCell = cellSystems[key] || [];
      var dots = inCell.slice(0,3).map(function(s){
        return '<div class="matrix-dot" title="'+s.nom+' — '+(s.secteur||'')+'" onclick="matriceOpenSys('+s.id+')">'+matriceIco(s.secteur)+'</div>';
      }).join('');
      var more = inCell.length > 3 ? '<div class="matrix-dot-more">+'+(inCell.length-3)+'</div>' : '';
      return '<div class="matrix-cell '+cls+'">'+dots+more+'</div>';
    }).join('');
    return rowLabel + cells;
  }).join('');

  g.innerHTML = head + rows;

  /* Liste des systemes en zone critique (impact eleve/critique OU probabilite elevee/tres elevee) */
  var c = document.getElementById('matrice-critical');
  if(!c) return;
  var critiques = systemes.filter(function(s){
    var impIdx = IMPACT_MAP[s.classification] !== undefined ? IMPACT_MAP[s.classification] : 0;
    var probIdx = PROB_MAP[s.statut_conformite] !== undefined ? PROB_MAP[s.statut_conformite] : 2;
    return impIdx >= 3 || probIdx >= 3;
  }).sort(function(a,b){
    var sa = (IMPACT_MAP[a.classification]||0) + (PROB_MAP[a.statut_conformite]||0);
    var sb = (IMPACT_MAP[b.classification]||0) + (PROB_MAP[b.statut_conformite]||0);
    return sb - sa;
  });

  var CLASSIF_LABELS = {inacceptable:"Inacceptable", haut:"Haut risque", limite:"Risque limité", minimal:"Risque minimal", a_evaluer:"À évaluer"};
  var STATUT_LABELS = {conforme:"Conforme", en_cours:"En cours", non_conforme:"Non conforme", a_evaluer:"À évaluer"};

  if(critiques.length === 0){
    c.innerHTML = '<div class="reg-empty">Aucun système en zone critique pour le moment.</div>';
    return;
  }
  c.innerHTML = critiques.map(function(s){
    return '<div class="eval-row" style="cursor:pointer" onclick="matriceOpenSys('+s.id+')">'
      + '<div class="eval-ico">'+matriceIco(s.secteur)+'</div>'
      + '<div class="eval-body"><div class="eval-n">'+s.nom+'</div><div class="eval-d">'+(CLASSIF_LABELS[s.classification]||s.classification)+' · '+(STATUT_LABELS[s.statut_conformite]||s.statut_conformite)+' · '+(s.secteur||"")+'</div></div>'
      + '<div class="eval-sc">'+(s.score_risque||0)+'/10</div>'
      + '</div>';
  }).join('');
}

window.matriceOpenSys = function(id){
  go('registre', null, 'REGISTRE', 'Systèmes IA');
  setTimeout(function(){ if(typeof regOpenModal === 'function') regOpenModal(id); }, 150);
};

function matriceFetch(){
  var g = document.getElementById('matrix-grid');
  if(g) g.innerHTML = '<div class="reg-loading" style="grid-column:1/-1">Chargement du registre…</div>';
  window.sentRegistre().then(function(d){
    matriceRender(d.systemes || []);
  }).catch(function(){
    if(g) g.innerHTML = '<div class="reg-loading" style="grid-column:1/-1;color:var(--accent)">Erreur de chargement du registre.</div>';
  });
}

window.matriceFetch = matriceFetch;

var _matriceOrigGo = window.go;
window.go = function(id){
  var r = _matriceOrigGo ? _matriceOrigGo.apply(this, arguments) : undefined;
  if(id === "matrice") setTimeout(matriceFetch, 50);
  return r;
};

})();



