  document.querySelectorAll('.radar-axis').forEach(function(el){ el.setAttribute('stroke','#C4C0B8'); el.setAttribute('stroke-width','0.9'); });
  document.querySelectorAll('.radar-label').forEach(function(el){ el.style.fontWeight = ''; el.setAttribute('fill','#3D3D3D'); });
