/* ══ AUDIT IA ACT — pertinence sectorielle (fusionne depuis Controles par obligation) ══ */
(function(){
'use strict';

var AUDIT_REL_SECTOR = "telecom";
var AUDIT_REL_REG_CACHE = [];

function auditRelApplicableSections(classification){
  if(classification === "inacceptable") return ["art5"];
  if(classification === "haut") return ["art5","art6","art9_10","art11_12","art13_14","art15_17","art43_49"];
  if(classification === "limite") return ["art5","art6","art13_14"];
  return ["art5","art6"];
}
function auditRelSectorLabel(){
  return (window.MAT_SECTORS && window.MAT_SECTORS[AUDIT_REL_SECTOR]) ? window.MAT_SECTORS[AUDIT_REL_SECTOR].label : AUDIT_REL_SECTOR;
}
function auditRelMatchSector(sysSecteur){
  if(!sysSecteur) return false;
  var lbl = auditRelSectorLabel().toLowerCase();
  var s = sysSecteur.toLowerCase();
  return s.indexOf(lbl.split(' ')[0].split('/')[0]) !== -1 || lbl.indexOf(s) !== -1;
}

window.auditInitSectorBar = function(){
  var holder = document.getElementById("audit-sector-bar-holder");
  if(!holder || !window.MAT_SECTORS || holder.dataset.init) return;
  holder.dataset.init = "1";
  var options = Object.keys(window.MAT_SECTORS).map(function(k){
    var s = window.MAT_SECTORS[k];
    return '<option value="'+k+'"'+(k===AUDIT_REL_SECTOR?' selected':'')+'>'+s.icon+' '+s.label+'</option>';
  }).join("");
  holder.innerHTML = '<span class="radar-sector-lbl">Pertinence sectorielle :</span>'
    + '<select id="audit-sector-select" class="radar-sector-select" onchange="auditSelectRelSector(this.value)">'+options+'</select>'
    + '<span style="font-size:10px;color:var(--muted);flex:1;min-width:200px">Indique pour chaque section, a partir des systemes reels du Registre IA, si elle est applicable au secteur selectionne.</span>';
};

window.auditSelectRelSector = function(sectorKey){
  AUDIT_REL_SECTOR = sectorKey;
  auditRenderSectorRelevance();
};

window.auditRenderSectorRelevance = function(){
  window.sentRegistre().then(function(d){
    AUDIT_REL_REG_CACHE = d.systemes || [];
    auditApplySectorRelevance();
  }).catch(function(){ AUDIT_REL_REG_CACHE = []; auditApplySectorRelevance(); });
};

function auditApplySectorRelevance(){
  if(!window.AUDIT_SECTIONS) return;
  var sysSecteur = AUDIT_REL_REG_CACHE.filter(function(s){ return auditRelMatchSector(s.secteur); });
  var applicableSections = {};
  sysSecteur.forEach(function(s){
    auditRelApplicableSections(s.classification).forEach(function(secId){
      if(!applicableSections[secId]) applicableSections[secId] = [];
      applicableSections[secId].push(s);
    });
  });

  window.AUDIT_SECTIONS.forEach(function(sec){
    var el = document.getElementById("sec-relevance-"+sec.id);
    var rowEl = el ? el.closest(".audit-section") : null;
    var secSystems = applicableSections[sec.id] || [];
    if(el){
      if(secSystems.length > 0){
        el.innerHTML = '<span class="audit-rel-tag audit-rel-ok">'+secSystems.length+' système(s) concerné(s)</span>';
      } else if(sysSecteur.length > 0){
        el.innerHTML = '<span class="audit-rel-tag audit-rel-na">Non applicable au secteur</span>';
      } else {
        el.innerHTML = '';
      }
    }
    if(rowEl) rowEl.classList.toggle("audit-section-dim", sysSecteur.length > 0 && secSystems.length === 0);
  });

  var info = document.getElementById("audit-registre-info");
  if(info){
    if(sysSecteur.length > 0){
      info.innerHTML = '📊 <strong>'+sysSecteur.length+' système(s)</strong> du Registre IA pour '+auditRelSectorLabel()+' déterminent les sections ci-dessous comme applicables ou non.';
      info.className = "radar-registre-info radar-registre-ok";
    } else {
      info.innerHTML = '⚠️ Aucun système du secteur '+auditRelSectorLabel()+' dans le Registre IA — les 34 points restent affichés sans filtrage de pertinence.';
      info.className = "radar-registre-info radar-registre-warn";
    }
  }
}

})();



