/* ══ FRIA — Fundamental Rights Impact Assessment (Art. 27 EU AI Act) ══ */
/* Source : Art. 27 Reglement (UE) 2024/1689, applicable a partir du 2 aout 2026 (Art. 113).
   Obligation du DEPLOYEUR (pas du fournisseur), distincte d une DPIA RGPD.
   3 categories de deployeurs concernes (Art. 27(1)) :
   1) Organismes publics deployant un systeme Annexe III (hors infrastructures critiques, point 2)
   2) Entites privees fournissant des services publics deployant un systeme Annexe III
   3) Tout deployeur utilisant un systeme pour evaluation de solvabilite/scoring credit (Annexe III 5b)
      ou evaluation des risques et tarification en assurance vie/sante (Annexe III 5c) */
(function(){
'use strict';

var FRIA_SECTOR = "telecom"; /* sera synchronisee avec window.matGetCur() au chargement de la page */
var FRIA_REG_CACHE = [];
var FRIA_ANSWERS = {}; /* { systemeId: { droitId: niveau (0-3) } } */

/* 8 droits fondamentaux de la Charte UE les plus frequemment impliques (Art. 27(1)(a)) */
var FRIA_RIGHTS = [
  {id:"dignite", label:"Dignité humaine", art:"Art. 1 Charte UE", desc:"Le système traite-t-il les personnes de manière déshumanisante ou instrumentale (ex. notation, profilage intrusif) ?"},
  {id:"non_discrimination", label:"Non-discrimination", art:"Art. 21 Charte UE", desc:"Le système peut-il produire des résultats différenciés selon origine, genre, âge, handicap, situation économique ?"},
  {id:"vie_privee", label:"Respect de la vie privée", art:"Art. 7 Charte UE", desc:"Le système traite-t-il des données personnelles ou comportementales sensibles au-delà du strict nécessaire ?"},
  {id:"protection_donnees", label:"Protection des données", art:"Art. 8 Charte UE", desc:"Existe-t-il un risque de traitement disproportionné ou insuffisamment sécurisé des données ?"},
  {id:"liberte_expression", label:"Liberté d'expression et d'information", art:"Art. 11 Charte UE", desc:"Le système modère, classe ou influence-t-il l'accès à l'information ou l'expression des personnes ?"},
  {id:"bonne_administration", label:"Droit à une bonne administration", art:"Art. 41 Charte UE", desc:"Les personnes concernées peuvent-elles comprendre, contester et obtenir réexamen humain d'une décision automatisée ?"},
  {id:"voie_recours", label:"Droit à un recours effectif", art:"Art. 47 Charte UE", desc:"Existe-t-il une voie de recours claire en cas de décision défavorable issue du système IA ?"},
  {id:"droits_enfant", label:"Droits de l'enfant", art:"Art. 24 Charte UE", desc:"Le système peut-il affecter directement ou indirectement des mineurs ?"}
];

/* Niveaux de reponse : 0=Aucun impact, 1=Impact faible, 2=Impact modere, 3=Impact eleve */
var FRIA_LEVELS = [
  {v:0, label:"Aucun impact identifié", color:"#2D7A47"},
  {v:1, label:"Impact faible", color:"#2D7A47"},
  {v:2, label:"Impact modéré", color:"#C47C1A"},
  {v:3, label:"Impact élevé", color:"#B83222"}
];

/* ── Determination de l applicabilite Art. 27 selon secteur + classification du systeme ── */
function friaApplicable(systeme, secteurLabel){
  var sec = (secteurLabel || "").toLowerCase();
  var classif = systeme.classification;
  if(classif !== "haut" && classif !== "inacceptable") return {applicable:false, reason:"Système non classé haut risque — FRIA non requise (Art. 27 ne vise que les systèmes Annexe III à haut risque)."};

  /* Categorie 3 : scoring credit / assurance (Annexe III 5b, 5c) — independant du secteur */
  var typeOrFin = ((systeme.type_systeme||"") + " " + (systeme.finalite||"")).toLowerCase();
  if(/credit|scoring|solvabilit|assurance|tarif/.test(typeOrFin)){
    return {applicable:true, category:3, reason:"Catégorie 3 (Art. 27(1)(c)/(d)) — évaluation de solvabilité ou tarification assurance vie/santé."};
  }

  /* Categorie 1/2 : secteur public ou prestataire de service public */
  if(sec.indexOf("public") !== -1 || sec.indexOf("administration") !== -1){
    return {applicable:true, category:1, reason:"Catégorie 1 (Art. 27(1)(a)) — organisme public déployant un système Annexe III."};
  }
  if(sec.indexOf("énergie") !== -1 || sec.indexOf("energie") !== -1 || sec.indexOf("transport") !== -1 || sec.indexOf("télécom") !== -1 || sec.indexOf("telecom") !== -1){
    return {applicable:false, reason:"Infrastructures critiques (Annexe III point 2) — exemptées de FRIA par l'Art. 27(1)(a), sauf si le déployeur est un organisme public assurant un service public au sens large."};
  }
  if(sec.indexOf("santé") !== -1 || sec.indexOf("sante") !== -1){
    return {applicable:true, category:2, reason:"Catégorie 2 (Art. 27(1)(b)) — entité privée fournissant un service public (santé) déployant un système Annexe III."};
  }

  return {applicable:false, reason:"Le déployeur ne semble pas relever des 3 catégories de l'Art. 27(1) (organisme public, prestataire de service public, ou scoring crédit/assurance). FRIA recommandée à titre préventif mais non obligatoire en l'état."};
}

function friaSectorLabel(){
  return (window.MAT_SECTORS && window.MAT_SECTORS[FRIA_SECTOR]) ? window.MAT_SECTORS[FRIA_SECTOR].label : FRIA_SECTOR;
}
function friaMatchSector(sysSecteur){
  if(!sysSecteur) return false;
  var lbl = friaSectorLabel().toLowerCase();
  var s = sysSecteur.toLowerCase();
  return s.indexOf(lbl.split(' ')[0].split('/')[0]) !== -1 || lbl.indexOf(s) !== -1;
}

/* ── Persistance des reponses (localStorage) ── */
function friaLoadAnswers(){
  try {
    var saved = localStorage.getItem("cpFriaAnswers");
    if(saved) FRIA_ANSWERS = JSON.parse(saved);
  } catch(e){}
}
function friaSaveAnswers(){
  try { localStorage.setItem("cpFriaAnswers", JSON.stringify(FRIA_ANSWERS)); } catch(e){}
}
friaLoadAnswers();

function friaGetAnswer(sysId, droitId){
  return (FRIA_ANSWERS[sysId] && FRIA_ANSWERS[sysId][droitId] !== undefined) ? FRIA_ANSWERS[sysId][droitId] : null;
}

window.friaAnswer = function(sysId, droitId, val){
  if(!FRIA_ANSWERS[sysId]) FRIA_ANSWERS[sysId] = {};
  FRIA_ANSWERS[sysId][droitId] = val;
  friaSaveAnswers();
  friaRefreshSystemScore(sysId);
  if(typeof window.cpLogActivity === "function"){
    var sys = FRIA_REG_CACHE.find(function(s){ return String(s.id) === String(sysId); });
    window.cpLogActivity("Évaluation FRIA mise à jour"+(sys?" — "+sys.nom:""), "action");
  }
};

function friaComputeScore(sysId){
  var answers = FRIA_ANSWERS[sysId] || {};
  var vals = FRIA_RIGHTS.map(function(r){ return answers[r.id] !== undefined ? answers[r.id] : null; });
  var answered = vals.filter(function(v){ return v !== null; });
  if(answered.length === 0) return null;
  var sum = answered.reduce(function(a,b){ return a+b; }, 0);
  var maxPossible = answered.length * 3;
  var riskPct = sum / maxPossible; /* 0 = aucun risque, 1 = risque maximal */
  var score10 = Math.round((1 - riskPct) * 100) / 10; /* score de conformité /10, inverse du risque */
  return {score: score10, riskPct: riskPct, answeredCount: answered.length, totalCount: FRIA_RIGHTS.length};
}

function friaRefreshSystemScore(sysId){
  var result = friaComputeScore(sysId);
  var ring = document.getElementById("fria-score-"+sysId);
  if(ring && result){
    var color = result.score>=7?"var(--green)":result.score>=4?"var(--orange)":"var(--accent)";
    ring.querySelector(".fria-ring-val").textContent = result.score.toFixed(1);
    ring.style.borderColor = color;
  }
  FRIA_RIGHTS.forEach(function(r){
    var val = friaGetAnswer(sysId, r.id);
    [0,1,2,3].forEach(function(v){
      var btn = document.getElementById("fria-opt-"+sysId+"-"+r.id+"-"+v);
      if(btn) btn.classList.toggle("on", val === v);
    });
  });
  var saveBtn = document.getElementById("fria-save-btn-"+sysId);
  if(saveBtn){
    var complete = result && result.answeredCount === result.totalCount;
    var sys = FRIA_REG_CACHE.find(function(s){ return String(s.id) === String(sysId); });
    saveBtn.disabled = !complete;
    saveBtn.style.background = complete ? "#1C5A8A" : "var(--rule2)";
    saveBtn.style.color = complete ? "#fff" : "var(--muted)";
    saveBtn.style.cursor = complete ? "pointer" : "not-allowed";
    saveBtn.title = complete ? "Enregistrer cette evaluation FRIA dans l historique persistant et tracable (RGPD)." : "Répondez aux "+FRIA_RIGHTS.length+" questions de ce système pour activer l enregistrement.";
    saveBtn.textContent = complete ? "💾 Enregistrer dans l historique" : "💾 "+(result?result.answeredCount:0)+"/"+(result?result.totalCount:FRIA_RIGHTS.length)+" questions répondues";
    if(complete && sys) saveBtn.setAttribute("onclick", "histoSaveFria("+sysId+",'"+sys.nom.replace(/'/g,"")+"')");
    else saveBtn.removeAttribute("onclick");
  }
}

/* ── Rendu d un systeme (carte avec applicabilite + questionnaire si applicable) ── */
function friaRenderSysCard(systeme){
  var app = friaApplicable(systeme, systeme.secteur);
  var result = friaComputeScore(systeme.id);

  var CYCLE_LABELS = {
    conception: {label:"① Conception", color:"var(--blue)"},
    developpement: {label:"② Développement", color:"var(--blue)"},
    pre_production: {label:"③ Pré-production", color:"var(--orange)"},
    production: {label:"④ Production", color:"var(--green)"},
    revue: {label:"⑤ Revue en cours", color:"var(--accent)"}
  };
  var cy = CYCLE_LABELS[systeme.cycle_vie] || CYCLE_LABELS.production;

  /* Bandeau Privacy by Design (Art. 25 RGPD) : adapte le message selon l etape
     du cycle de vie projet. Pour la Production, signale si aucune revue n a
     jamais ete effectuee, ou si la derniere revue date de plus de 12 mois. */
  var pbdMsg = '';
  var pbdColor = cy.color;
  if(systeme.cycle_vie === 'conception' || systeme.cycle_vie === 'developpement'){
    pbdMsg = 'Privacy by Design (Art. 25 RGPD) : determinez les exigences privacy applicables avant la mise en production' + (systeme.product_owner ? ' — Product Owner : ' + systeme.product_owner : '') + '.';
  } else if(systeme.cycle_vie === 'pre_production'){
    pbdMsg = 'Dernière étape avant production : validez la conformité privacy complète' + (systeme.product_owner ? ' avec ' + systeme.product_owner : '') + '.';
  } else if(systeme.cycle_vie === 'production' || systeme.cycle_vie === 'revue'){
    if(!systeme.derniere_revue){
      pbdMsg = 'Système en production sans revue de conformité privacy enregistrée — une revue périodique est recommandée.';
      pbdColor = 'var(--accent)';
    } else {
      var moisDepuis = Math.floor((Date.now() - new Date(systeme.derniere_revue).getTime()) / (1000*60*60*24*30));
      if(moisDepuis >= 12){
        pbdMsg = 'Dernière revue de conformité privacy il y a ' + moisDepuis + ' mois — une nouvelle revue périodique est recommandée.';
        pbdColor = 'var(--accent)';
      } else {
        pbdMsg = 'Dernière revue de conformité privacy : ' + new Date(systeme.derniere_revue).toLocaleDateString('fr-FR') + '.';
      }
    }
  }

  var head = '<div class="fria-sys-card'+(app.applicable?'':' fria-sys-na')+'">'
    + '<div class="fria-sys-head">'
    + '<div><div class="fria-sys-name">'+systeme.nom+'</div><div class="fria-sys-meta">'+(systeme.secteur||'')+' · '+(systeme.type_systeme||'')+' · <span style="color:'+cy.color+'">'+cy.label+'</span></div></div>'
    + (app.applicable
        ? '<div class="fria-score-ring" id="fria-score-'+systeme.id+'"><div class="fria-ring-val">'+(result?result.score.toFixed(1):'—')+'</div><div class="fria-ring-lbl">/ 10</div></div>'
        : '<span class="fria-na-badge">FRIA non requise</span>')
    + '</div>'
    + (pbdMsg ? '<div class="fria-app-reason" style="border-left:3px solid '+pbdColor+';padding-left:10px;margin-bottom:8px">'+pbdMsg+'</div>' : '')
    + '<div class="fria-app-reason">'+app.reason+'</div>';

  if(app.applicable){
    head += '<div class="fria-rights-grid">' + FRIA_RIGHTS.map(function(r){
      var val = friaGetAnswer(systeme.id, r.id);
      return '<div class="fria-right-item">'
        + '<div class="fria-right-q"><strong>'+r.label+'</strong> <span class="fria-right-art">'+r.art+'</span><br>'+r.desc+'</div>'
        + '<div class="fria-opts">' + FRIA_LEVELS.map(function(lvl){
            return '<button class="fria-opt'+(val===lvl.v?' on':'')+'" id="fria-opt-'+systeme.id+'-'+r.id+'-'+lvl.v+'" onclick="friaAnswer('+systeme.id+',\''+r.id+'\','+lvl.v+')" title="'+lvl.label+'">'+lvl.v+'</button>';
          }).join('') + '</div></div>';
    }).join('') + '</div>';

    if(result && result.score < 5){
      head += '<div class="fria-actions-box"><div class="fria-actions-title">Mesures d attenuation recommandees</div>'
        + '<div class="act-item"><div class="act-dot"></div><div class="act-t">Réviser la politique de supervision humaine (Art. 14)</div></div>'
        + '<div class="act-item"><div class="act-dot"></div><div class="act-t">Documenter les biais identifiés et leur traitement (Art. 10)</div></div>'
        + '<div class="act-item"><div class="act-dot"></div><div class="act-t">Verifier l enregistrement dans la base UE (Art. 49, 71)</div></div></div>';
    }

    /* Connexion croisee : score Audit IA Act du secteur + positionnement Matrice (probabilite x impact) deja calcules ailleurs */
    var auditPct = 0, auditTotal = 0, auditDone = 0;
    if(window.AUDIT_SECTIONS){
      window.AUDIT_SECTIONS.forEach(function(sec){
        sec.items.forEach(function(item){
          auditTotal++;
          var st = (window.AUDIT_STATE && window.AUDIT_STATE[item.id]) || "none";
          if(st === "done") auditDone++;
        });
      });
      auditPct = auditTotal>0 ? Math.round(auditDone/auditTotal*100) : 0;
    }
    var probLabel = systeme.statut_conformite === "non_conforme" ? "Très élevée" : systeme.statut_conformite === "en_cours" ? "Élevée" : systeme.statut_conformite === "conforme" ? "Très faible" : "Moyenne";
    head += '<div class="fria-cross-links">'
      + '<a href="#" onclick="openAuditTab();return false;" class="fria-cross-link">📋 Audit IA Act : <strong>'+auditPct+'%</strong> conforme →</a>'
      + '<a href="#" onclick="go(\'matrice\',null,\'RISQUES\',\'Matrice risques\');return false;" class="fria-cross-link">📊 Matrice : probabilité <strong>'+probLabel+'</strong> →</a>'
      + '</div>';
    var friaComplete = result && result.answeredCount === result.totalCount;
    var friaBtnLabel = friaComplete ? '💾 Enregistrer dans l historique' : '💾 '+(result?result.answeredCount:0)+'/'+(result?result.totalCount:FRIA_RIGHTS.length)+' questions répondues';
    head += '<button class="mat-export-btn" id="fria-save-btn-'+systeme.id+'" style="background:'+(friaComplete?'#1C5A8A':'var(--rule2)')+';color:'+(friaComplete?'#fff':'var(--muted)')+';margin-top:10px;width:100%;cursor:'+(friaComplete?'pointer':'not-allowed')+'" '
      + (friaComplete ? 'onclick="histoSaveFria('+systeme.id+',\''+systeme.nom.replace(/'/g,"")+'\')"' : 'disabled')
      + ' title="'+(friaComplete?'Enregistrer cette evaluation FRIA dans l historique persistant et tracable (RGPD).':'Répondez aux '+FRIA_RIGHTS.length+' questions de ce système pour activer l enregistrement.')+'">'+friaBtnLabel+'</button>'
      + '<button class="mat-export-btn" style="background:var(--bg);color:var(--ink);border:1px solid var(--rule2);margin-top:8px;width:100%" onclick="ragShowRelevantDocs(\'droits fondamentaux evaluation impact\',\'fria\',\'Documents pertinents\')">📚 Documents pertinents</button>';
  }

  head += '</div>';
  return head;
}

function friaInitSectorBar(){
  var holder = document.getElementById("fria-sector-bar-holder");
  if(!holder || !window.MAT_SECTORS) return;
  var options = Object.keys(window.MAT_SECTORS).map(function(k){
    var s = window.MAT_SECTORS[k];
    return '<option value="'+k+'"'+(k===FRIA_SECTOR?' selected':'')+'>'+s.icon+' '+s.label+'</option>';
  }).join("");
  holder.innerHTML = '<span class="radar-sector-lbl">Secteur d activite :</span>'
    + '<select id="fria-sector-select" class="radar-sector-select" onchange="friaSelectSector(this.value)">'+options+'</select>'
    + '<span style="font-size:10px;color:var(--muted);flex:1;min-width:200px">Détermine, pour chaque système du Registre IA, si une FRIA est obligatoire au titre de l Art. 27.</span>';
}

window.friaSelectSector = function(sectorKey){
  FRIA_SECTOR = sectorKey;
  friaRenderAll();
};

function friaFetch(){
  var holder = document.getElementById("fria-list");
  if(holder) holder.innerHTML = '<div class="reg-loading">Chargement de vos systèmes IA…</div>';
  var info = document.getElementById("fria-registre-info");
  if(info){ info.innerHTML = 'Vérification de l applicabilité Art. 27 en cours…'; info.className = "radar-registre-info"; }
  window.sentRegistre()
    .then(function(d){
      if(d._statut === 401 || d._statut === 403){
        var msg = d._statut === 401
          ? '🔒 Session expirée — <a href="/login" style="color:var(--blue)">reconnectez-vous</a> pour accéder à FRIA.'
          : '🔒 '+(d.error || 'Accès réservé aux plans Pro/Entreprise.');
        if(holder) holder.innerHTML = '<div class="reg-loading" style="color:var(--accent)">'+msg+'</div>';
        if(info){ info.innerHTML = msg; info.className = "radar-registre-info radar-registre-warn"; }
        return;
      }
      if(d._statut >= 400){ throw new Error('HTTP '+d._statut); }
      FRIA_REG_CACHE = d.systemes || [];
      friaRenderAll();
    })
    .catch(function(e){
      FRIA_REG_CACHE = [];
      if(holder) holder.innerHTML = '<div class="reg-loading" style="color:var(--accent)">Erreur de chargement ('+e.message+'). Rechargez la page ou réessayez dans quelques secondes.</div>';
    });
}

function friaRenderAll(){
  var holder = document.getElementById("fria-list");
  if(!holder) return;
  var sysSecteur = FRIA_REG_CACHE.filter(function(s){ return friaMatchSector(s.secteur); });

  var info = document.getElementById("fria-registre-info");
  if(info){
    if(sysSecteur.length === 0){
      info.innerHTML = '⚠️ Aucun système du secteur '+friaSectorLabel()+' dans le Registre IA. Ajoutez vos systèmes pour une évaluation FRIA réelle.';
      info.className = "radar-registre-info radar-registre-warn";
    } else {
      var nbApplicable = sysSecteur.filter(function(s){ return friaApplicable(s, s.secteur).applicable; }).length;
      info.innerHTML = '📊 <strong>'+sysSecteur.length+' système(s)</strong> du secteur '+friaSectorLabel()+' — <strong>'+nbApplicable+' soumis à FRIA</strong> au titre de l Art. 27 EU AI Act.';
      info.className = "radar-registre-info radar-registre-ok";
    }
  }

  if(sysSecteur.length === 0){
    holder.innerHTML = '<div class="reg-empty">Aucun système à évaluer pour ce secteur. <a href="#" onclick="go(\'registre\',null,\'REGISTRE\',\'Systemes IA\');return false;">Ajouter un système →</a></div>';
    return;
  }

  holder.innerHTML = sysSecteur.map(friaRenderSysCard).join("");
}

var _friaOrigGo = window.go;
window.go = function(id){
  var r = _friaOrigGo ? _friaOrigGo.apply(this, arguments) : undefined;
  if(id === "fria"){
    setTimeout(function(){
      /* Synchroniser avec le secteur actif global (Maturite/RACI/Radar) au lieu de rester sur "telecom" par defaut */
      if(typeof window.matGetCur === "function") FRIA_SECTOR = window.matGetCur();
      friaInitSectorBar(); friaFetch();
    }, 50);
  }
  return r;
};

})();



