/* ══ ESPACE — Noyau commun : logger d activite + agregation de donnees reelles ══ */
(function(){
'use strict';

/* ── Logger d activite leger (persistant) ── */
function cpLogActivity(text, type){
  try{
    var log = JSON.parse(localStorage.getItem("cpActivityLog") || "[]");
    log.unshift({text: text, type: type || "info", date: new Date().toISOString()});
    if(log.length > 30) log = log.slice(0,30);
    localStorage.setItem("cpActivityLog", JSON.stringify(log));
  } catch(e){}
}
window.cpLogActivity = cpLogActivity;

function cpGetActivityLog(){
  try{ return JSON.parse(localStorage.getItem("cpActivityLog") || "[]"); } catch(e){ return []; }
}
window.cpGetActivityLog = cpGetActivityLog;

/* ── Hooks discrets sur les actions cles deja existantes (sans alterer leur comportement) ── */
function cpHook(fnName, makeMsg){
  if(typeof window[fnName] !== "function") return;
  var orig = window[fnName];
  window[fnName] = function(){
    var res = orig.apply(this, arguments);
    try{ cpLogActivity(makeMsg(arguments), "action"); } catch(e){}
    return res;
  };
}
/* Ces hooks s'attachent une fois que les fonctions cibles existent (apres chargement complet) */
function cpInstallHooks(){
  cpHook("cpEvalSaveAudit", function(){ return "Audit IA Act enregistré dans Mes évaluations"; });
  cpHook("regSave", function(){ return "Système IA ajouté/modifié dans le Registre"; });
  cpHook("matGenerateDeliverable", function(args){ return "Livrable IA généré (Audit de maturité)"; });
  cpHook("raciGenerateDoc", function(){ return "Cartographie des parties prenantes générée par IA"; });
  cpHook("simAddToRegistre", function(){ return "Système simulé ajouté au Registre IA"; });
}
setTimeout(cpInstallHooks, 500);

/* ── Agregation des donnees reelles pour Mon Espace / Reporting ── */
window.cpGetDashboardData = function(callback){
  var data = {
    registre: [],
    auditPct: 0, auditDone: 0, auditPartial: 0, auditTodo: 0, auditTotal: 0,
    evaluations: [],
    registreNonConforme: 0,
    registreHautRisque: 0
  };
  window.sentRegistre().then(function(d){
    data.registre = d.systemes || [];
    data.registreNonConforme = data.registre.filter(function(s){ return s.statut_conformite==='non_conforme' || s.statut_conformite==='a_evaluer'; }).length;
    data.registreHautRisque = data.registre.filter(function(s){ return s.classification==='haut' || s.classification==='inacceptable'; }).length;

    if(window.AUDIT_SECTIONS){
      window.AUDIT_SECTIONS.forEach(function(sec){
        sec.items.forEach(function(item){
          data.auditTotal++;
          var st = (window.AUDIT_STATE && window.AUDIT_STATE[item.id]) || "none";
          if(st === "done") data.auditDone++;
          else if(st === "partial") data.auditPartial++;
        });
      });
      data.auditTodo = data.auditTotal - data.auditDone - data.auditPartial;
      data.auditPct = data.auditTotal>0 ? Math.round((data.auditDone + data.auditPartial*0.5)/data.auditTotal*100) : 0;
    }

    try{ data.evaluations = JSON.parse(localStorage.getItem("cpEvaluations") || "[]"); } catch(e){}

    callback(data);
  }).catch(function(){ callback(data); });
};

})();



