/* ══ MON ESPACE — Tableau de bord personnel reel ══ */
(function(){
'use strict';

function espaceRenderActivity(){
  var holder = document.getElementById("act-list");
  if(!holder) return;
  var log = cpGetActivityLog();
  if(log.length === 0){
    holder.innerHTML = '<div class="reg-empty">Aucune activité récente. Vos actions (audits, évaluations, livrables générés) apparaîtront ici.</div>';
    return;
  }
  function timeAgo(iso){
    var diff = Date.now() - new Date(iso).getTime();
    var h = Math.floor(diff/3600000), d = Math.floor(h/24);
    if(d > 0) return "Il y a "+d+"j";
    if(h > 0) return "Il y a "+h+"h";
    return "À l'instant";
  }
  holder.innerHTML = log.slice(0,8).map(function(a){
    return '<div class="act-item"><div class="act-dot"></div><div class="act-t">'+a.text+'</div><div class="act-d">'+timeAgo(a.date)+'</div></div>';
  }).join('');
}

function espaceRenderActions(){
  var holder = document.getElementById("espace-actions");
  if(!holder) return;
  cpGetDashboardData(function(d){
    var actions = [];
    if(d.registreNonConforme > 0) actions.push({txt: d.registreNonConforme+" système(s) à évaluer ou non conformes", go:"registre", lbl:"Voir le Registre →"});
    if(d.auditTodo > 0) actions.push({txt: d.auditTodo+" point(s) de l audit IA Act à compléter", go:"audit", lbl:"Ouvrir l audit →"});
    if(d.registreHautRisque > 0) actions.push({txt: d.registreHautRisque+" système(s) à haut risque — vérifier FRIA applicable", go:"fria", lbl:"Vérifier FRIA →"});
    if(actions.length === 0) actions.push({txt:"Aucune action urgente identifiée. Tout est à jour.", go:null});

    holder.innerHTML = actions.map(function(a){
      return '<div class="act-item" style="'+(a.go?'cursor:pointer':'')+'" '+(a.go?'onclick="'+(a.go==='audit'?'openAuditTab()':"go('"+a.go+"',null,'',\\'\\')")+'"':'')+'>'
        + '<div class="act-dot"></div><div class="act-t">'+a.txt+(a.lbl?' <span style="color:var(--accent);font-size:10px;font-family:var(--mono)">'+a.lbl+'</span>':'')+'</div></div>';
    }).join('');
  });
}

function espaceRenderKpis(){
  var holder = document.getElementById("espace-kpis");
  if(!holder) return;
  cpGetDashboardData(function(d){
    holder.innerHTML =
      '<div class="kpi" style="flex:1"><div class="kpi-lbl">Systèmes au Registre</div><div class="kpi-val">'+d.registre.length+'</div></div>'
      + '<div class="kpi" style="flex:1"><div class="kpi-lbl">Conformité Audit IA Act</div><div class="kpi-val" style="color:'+(d.auditPct>=70?'var(--green)':d.auditPct>=40?'var(--orange)':'var(--accent)')+'">'+d.auditPct+'%</div></div>'
      + '<div class="kpi" style="flex:1"><div class="kpi-lbl">Évaluations enregistrées</div><div class="kpi-val">'+d.evaluations.length+'</div></div>';
  });
}

window.espaceRenderPage = function(){
  espaceRenderActivity();
  espaceRenderActions();
  espaceRenderKpis();
};

var _espaceOrigGo = window.go;
window.go = function(id){
  var r = _espaceOrigGo ? _espaceOrigGo.apply(this, arguments) : undefined;
  if(id === "espace") setTimeout(window.espaceRenderPage, 80);
  return r;
};

})();



