/* ══ ROADMAP — connectee aux phases reelles de l Audit de maturite + progres Audit IA Act ══ */
(function(){
'use strict';

window.roadmapRenderPage = function(){
  var holder = document.getElementById("roadmap-content");
  if(!holder) return;

  cpGetDashboardData(function(d){
    var phases = window.MAT_PHASES || [];
    var html = phases.map(function(p, i){
      /* Progression estimee : phase 1 (diagnostic) suit le % de remplissage Registre+Audit,
         les phases suivantes restent planifiees tant que la phase precedente n est pas avancee */
      var prog = 0;
      if(i === 0) prog = Math.min(100, Math.round((d.registre.length>0?50:0) + d.auditPct*0.5));
      else if(i === 1) prog = Math.round(d.auditPct);
      else if(i === 2) prog = Math.round(d.auditPct * 0.6);
      else prog = d.auditPct >= 80 ? 20 : 0;

      return '<div class="ctrl-section ctrl-section-clickable" onclick="roadmapOpenPhaseModal('+i+')" title="Cliquer pour générer le livrable détaillé de cette phase via IA"><div class="ctrl-section-head"><span class="ctrl-section-title">Phase '+p.n+' — '+p.title+' <span style="font-family:var(--mono);font-size:9px;color:var(--blue)">'+p.duree+'</span></span>'
        + '<span class="audit-rel-tag '+(prog>=70?'audit-rel-ok':'')+'" style="background:'+(prog>=70?'rgba(45,122,71,.1)':'var(--bg)')+';color:'+(prog>=70?'var(--green)':'var(--muted2)')+'">'+prog+'%</span></div>'
        + '<div style="padding:14px 16px"><div style="font-size:11px;color:var(--muted);line-height:1.6;margin-bottom:8px">'+p.desc+'</div>'
        + '<div style="height:4px;background:var(--bg2);border-radius:2px;overflow:hidden"><div style="height:100%;width:'+prog+'%;background:'+(prog>=70?'var(--green)':prog>=30?'var(--orange)':'var(--accent)')+';border-radius:2px"></div></div>'
        + '<div style="font-size:10px;font-family:var(--mono);color:var(--green);margin-top:8px">▸ '+p.deliv+'</div>'
        + '<div class="card-cta">🤖 Générer le livrable détaillé →</div></div></div>';
    }).join('');

    holder.innerHTML = html || '<div class="reg-empty">Données de phases indisponibles.</div>';

    /* Résumé avancement */
    var sum = document.getElementById("road-summary");
    if(sum){
      sum.innerHTML =
        '<div class="act-item"><div class="act-dot"></div><div class="act-t">'+d.registre.length+' système(s) inventoriés</div></div>'
        + '<div class="act-item"><div class="act-dot"></div><div class="act-t">'+d.auditDone+'/'+d.auditTotal+' contrôles conformes</div></div>'
        + '<div class="act-item"><div class="act-dot"></div><div class="act-t">'+d.registreHautRisque+' système(s) à haut risque identifiés</div></div>';
    }

    /* Prochaine echeance critique : utilise la progression Audit reelle */
    var eta = document.getElementById("road-next-deadline-bar");
    if(eta){
      eta.style.width = d.auditPct + "%";
      var lbl = document.getElementById("road-next-deadline-lbl");
      if(lbl) lbl.textContent = d.auditPct + "% — échéance 2 août 2026 (Art. 113, systèmes haut risque)";
    }
  });
};

var _roadOrigGo = window.go;
window.go = function(id){
  var r = _roadOrigGo ? _roadOrigGo.apply(this, arguments) : undefined;
  if(id === "roadmap") setTimeout(window.roadmapRenderPage, 80);
  return r;
};

})();



