/* ══ REPORTING — Dashboard executif agregeant toutes les pages reelles ══ */
(function(){
'use strict';

window.reportRenderPage = function(){
  var holder = document.getElementById("report-kpi-row");
  if(!holder) return;

  cpGetDashboardData(function(d){
    holder.innerHTML =
      '<div class="kpi"><div class="kpi-lbl">Systèmes au Registre IA</div><div class="kpi-val">'+d.registre.length+'</div></div>'
      + '<div class="kpi"><div class="kpi-lbl">Conformité Audit IA Act</div><div class="kpi-val" style="color:'+(d.auditPct>=70?'var(--green)':d.auditPct>=40?'var(--orange)':'var(--accent)')+'">'+d.auditPct+'%</div></div>'
      + '<div class="kpi"><div class="kpi-lbl">Systèmes à haut risque</div><div class="kpi-val" style="color:'+(d.registreHautRisque>0?'var(--accent)':'var(--green)')+'">'+d.registreHautRisque+'</div></div>'
      + '<div class="kpi"><div class="kpi-lbl">Actions en attente</div><div class="kpi-val" style="color:var(--orange)">'+(d.auditTodo+d.registreNonConforme)+'</div></div>';

    var detail = document.getElementById("report-detail");
    if(detail){
      var byClassif = {};
      d.registre.forEach(function(s){ byClassif[s.classification] = (byClassif[s.classification]||0)+1; });
      var CLASSIF_LABELS = {inacceptable:"Inacceptable", haut:"Haut risque", limite:"Risque limité", minimal:"Risque minimal", a_evaluer:"À évaluer"};
      detail.innerHTML = '<div class="tbl-wrap" style="margin-bottom:16px"><div class="tbl-head"><span class="tbl-title">Répartition du Registre IA par classification</span></div><div style="padding:16px 20px">'
        + Object.keys(CLASSIF_LABELS).map(function(k){
            var n = byClassif[k] || 0;
            var pct = d.registre.length>0 ? Math.round(n/d.registre.length*100) : 0;
            return '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px"><div style="width:120px;font-size:11px;color:var(--ink2)">'+CLASSIF_LABELS[k]+'</div><div class="reg-bar" style="flex:1"><div class="reg-fill" style="width:'+pct+'%"></div></div><div style="width:40px;text-align:right;font-family:var(--mono);font-size:11px">'+n+'</div></div>';
          }).join('')
        + '</div></div>'
        + '<div class="tbl-wrap"><div class="tbl-head"><span class="tbl-title">Dernières évaluations ('+Math.min(6,d.evaluations.length)+' sur '+d.evaluations.length+')</span><span class="tbl-link" onclick="go(\'evals\',null,\'CONFORMITÉ\',\'Mes évaluations\')">Voir tout →</span></div><div style="padding:0 20px" id="report-evals-list"></div></div>';

      var evalsList = document.getElementById("report-evals-list");
      if(evalsList){
        if(d.evaluations.length === 0){
          evalsList.innerHTML = '<div class="reg-empty">Aucune évaluation enregistrée.</div>';
        } else {
          evalsList.innerHTML = d.evaluations.slice(0,6).map(function(e){
            return '<div class="eval-row"><div class="eval-ico">'+(e.icon||'📋')+'</div><div class="eval-body"><div class="eval-n">'+e.title+'</div><div class="eval-d">'+e.subtitle+'</div></div><div class="eval-sc">'+e.score+(e.scoreMax===100?'%':'/10')+'</div></div>';
          }).join('');
        }
      }
    }
  });
};

var _reportOrigGo = window.go;
window.go = function(id){
  var r = _reportOrigGo ? _reportOrigGo.apply(this, arguments) : undefined;
  if(id === "report") setTimeout(window.reportRenderPage, 80);
  return r;
};

})();



