/* ══ CALCULATEUR SANCTIONS — connecte au Registre IA / Simulateur ══ */
(function(){
'use strict';

window.sanctionsPrefillFromRegistry = function(){
  window.sentRegistre().then(function(d){
    var systemes = d.systemes || [];
    var hautRisque = systemes.filter(function(s){ return s.classification==='haut' || s.classification==='inacceptable'; });
    if(hautRisque.length === 0){
      alert("Aucun systeme a haut risque ou inacceptable dans le Registre IA pour pre-remplir le calculateur.");
      return;
    }
    var pire = hautRisque.sort(function(a,b){ return (b.score_risque||0)-(a.score_risque||0); })[0];
    var typeSel = document.getElementById("s-type");
    if(typeSel) typeSel.value = pire.classification === "inacceptable" ? "interdit" : "haut";
    var info = document.getElementById("sanc-prefill-info");
    if(info) info.textContent = "Pré-rempli depuis : " + pire.nom + " (" + (pire.secteur||"") + ")";
  });
};

window.sanctionsInitPage = function(){
  var holder = document.getElementById("sanc-prefill-holder");
  if(!holder) return;
  holder.innerHTML = '<button class="mat-export-btn" style="background:var(--blue);color:#fff;margin-bottom:14px" onclick="sanctionsPrefillFromRegistry()" title="Pré-remplit le calculateur avec le système le plus exposé de votre Registre IA.">📊 Pré-remplir depuis le Registre IA</button>'
    + '<div id="sanc-prefill-info" style="font-size:10px;color:var(--muted);margin-bottom:14px"></div>';
};

var _sancOrigGo = window.go;
window.go = function(id){
  var r = _sancOrigGo ? _sancOrigGo.apply(this, arguments) : undefined;
  if(id === "sanctions") setTimeout(window.sanctionsInitPage, 50);
  return r;
};

})();



