/* ══ BENCHMARK SECTORIEL — scores reels par secteur (Registre IA + Audit) ══ */
(function(){
'use strict';

window.benchmarkRenderPage = function(){
  var holder = document.getElementById("bench-list");
  if(!holder || !window.MAT_SECTORS) return;
  holder.innerHTML = '<div class="reg-loading">Calcul des scores sectoriels…</div>';

  window.sentRegistre().then(function(d){
    var systemes = d.systemes || [];

    function scoreFor(sectorLabel){
      var lbl = sectorLabel.toLowerCase().split(' ')[0].split('/')[0];
      var sys = systemes.filter(function(s){ return (s.secteur||"").toLowerCase().indexOf(lbl) !== -1; });
      if(sys.length === 0) return null;
      var avgRisk = sys.reduce(function(a,s){ return a+(s.score_risque||0); },0) / sys.length;
      var conformes = sys.filter(function(s){ return s.statut_conformite==='conforme'; }).length;
      var conformPct = Math.round(conformes/sys.length*100);
      return {avgRisk: avgRisk, conformPct: conformPct, count: sys.length};
    }

    var rows = Object.keys(window.MAT_SECTORS).map(function(k){
      var sec = window.MAT_SECTORS[k];
      var data = scoreFor(sec.label);
      var maturityAvg = (Object.keys(sec.pillars).reduce(function(a,p){ return a+sec.pillars[p]; },0) / 8) * 20; /* /5 -> % */
      return {label: sec.icon+" "+sec.label, you: data ? data.conformPct : null, avg: Math.round(maturityAvg), count: data?data.count:0};
    });

    holder.innerHTML = rows.map(function(r){
      var diff = r.you !== null ? (r.you - r.avg) : null;
      var diffTxt = diff !== null ? (diff>=0?'+':'')+diff+' pts' : '—';
      var diffColor = diff !== null ? (diff>=0?'var(--green)':'var(--accent)') : 'var(--muted2)';
      return '<div class="bench-row"><div class="bench-sector">'+r.label+(r.you!==null?' <span style="font-size:9px;font-family:var(--mono);color:var(--accent)">● VOUS ('+r.count+' syst.)</span>':'')+'</div>'
        + '<div class="bench-score">'+r.avg+'%</div>'
        + '<div class="bench-bar-wrap">'+(r.you!==null?'<div class="bench-track"><div class="bench-fill bench-fill-you" style="width:'+r.you+'%"></div></div><span class="bench-you">vous '+r.you+'%</span>':'<span style="font-size:10px;color:var(--muted2)">Aucun système enregistré</span>')
        + '<div class="bench-track"><div class="bench-fill bench-fill-avg" style="width:'+r.avg+'%"></div></div></div>'
        + '<div><span style="font-family:var(--mono);font-size:10px;color:'+diffColor+'">'+diffTxt+'</span></div></div>';
    }).join('');

    /* KPIs de synthese en haut de page - calcules a partir des memes "rows" (evite toute incoherence) */
    var withData = rows.filter(function(r){ return r.you !== null; });
    var youEl = document.getElementById("bench-top-you");
    var youTrEl = document.getElementById("bench-top-you-tr");
    var avgEl = document.getElementById("bench-top-avg");
    var avgTrEl = document.getElementById("bench-top-avg-tr");
    var lblEl = document.getElementById("bench-top-sector-lbl");
    if(withData.length > 0){
      var youAvg = Math.round(withData.reduce(function(a,r){return a+r.you;},0) / withData.length);
      var best = withData.slice().sort(function(a,b){return b.you-a.you;})[0];
      var topSector = withData.slice().sort(function(a,b){return b.avg-a.avg;})[0];
      if(youEl) youEl.textContent = youAvg + "%";
      if(youTrEl){ var vsTop = youAvg - best.avg; youTrEl.innerHTML = (vsTop>=0?'↑ +':'↓ ')+vsTop+' pts vs. meilleur secteur ('+best.label.replace(/^\S+\s/,'')+')'; youTrEl.className = "kpi-tr " + (vsTop>=0?"up":"dn"); }
      if(lblEl && topSector) lblEl.textContent = "Moyenne " + topSector.label.replace(/^\S+\s/,'');
      if(avgEl && topSector) avgEl.textContent = topSector.avg + "%";
      if(avgTrEl) avgTrEl.innerHTML = withData.length + " secteur(s) avec données réelles";
    } else {
      if(youEl) youEl.textContent = "—";
      if(youTrEl) youTrEl.innerHTML = "Aucun système au Registre IA";
      if(avgEl) avgEl.textContent = "—";
    }
  }).catch(function(){
    holder.innerHTML = '<div class="reg-empty">Erreur de chargement du Registre IA.</div>';
  });
};

var _benchOrigGo = window.go;
window.go = function(id){
  var r = _benchOrigGo ? _benchOrigGo.apply(this, arguments) : undefined;
  if(id === "benchmark") setTimeout(window.benchmarkRenderPage, 80);
  return r;
};

})();



