function renderCard(d){
  var artBadges = (d.arts||[]).map(function(a){
    var tip = ART_TIPS[a]||'';
    return '<span class="tmpl-art-badge" data-art="'+a+'">'
      +a.replace('art','Art.\u00a0')
      +'<span class="tmpl-tip">'+tip+'</span>'
      +'</span>';
  }).join('');
  var dlBadge = d.dl ? '<span class="tmpl-dl-badge">\u2b07 T\u00e9l\u00e9chargeable</span>' : '';
  return '<div class="doc-card type-'+d.type+'" data-cat="'+d.cat
    +'" data-arts="'+(d.arts||[]).join(' ')+'" data-format="'+(d.format||'')+'" onclick="'+d.action+'">'
    +'<div class="doc-icon">'+d.ico+'</div>'
    +'<div style="flex:1;min-width:0">'
    +'<div class="doc-name">'+d.name+'</div>'
    +'<div class="doc-desc">'+d.desc+'</div>'
    +'<div class="tmpl-arts">'+artBadges+dlBadge+'</div>'
    +'<div class="doc-meta">'+d.meta+'</div>'
    +'</div></div>';
}

function renderSection(cat, items){
  var el = document.getElementById('tmpl-grid-'+cat);
  if(!el) return;
  el.innerHTML = items.map(renderCard).join('');
  var c = document.getElementById('tmpl-count-'+cat);
  if(c) c.textContent = items.length+' document'+(items.length>1?'s':'');
}

window.tmplFilter = function(){
  var catV = (document.getElementById('tmpl-cat-select')||{}).value||'all';
  var artV = (document.getElementById('tmpl-art-select')||{}).value||'all';
  var fmtV = (document.getElementById('tmpl-format-select')||{}).value||'all';
  var cards = document.querySelectorAll('#p-templates .doc-card');
  var vis = 0;
  cards.forEach(function(c){
    var ok = (catV==='all'||c.dataset.cat===catV)
           &&(artV==='all'||(' '+(c.dataset.arts||'')+' ').indexOf(' '+artV+' ')>=0)
           &&(fmtV==='all'||(c.dataset.format||'').indexOf(fmtV)>=0);
    c.classList.toggle('tmpl-hidden',!ok);
    if(ok) vis++;
  });
  ['template','fiche','guide','doc','process'].forEach(function(cat){
    var sec = document.getElementById('tmpl-sec-'+cat);
    if(!sec) return;
    var n = sec.querySelectorAll('.doc-card:not(.tmpl-hidden)').length;
    sec.style.display = n ? '' : 'none';
    var c = document.getElementById('tmpl-count-'+cat);
    if(c) c.textContent = n+' document'+(n>1?'s':'');
  });
  var lbl = document.getElementById('tmpl-count-lbl');
  if(lbl) lbl.textContent = vis+' r\u00e9sultat'+(vis>1?'s':'');
};

window.templatesRenderPage = function(){
  ['template','fiche','guide','doc','process'].forEach(function(cat){
    renderSection(cat, TMPL_DATA.filter(function(d){ return d.cat===cat; }));
  });
  var lbl = document.getElementById('tmpl-count-lbl');
  if(lbl) lbl.textContent = TMPL_DATA.length+' documents';
  ['tmpl-cat-select','tmpl-art-select','tmpl-format-select'].forEach(function(id){
    var el = document.getElementById(id); if(el) el.value='all';
  });
};

