/* ══ ESPACE EQUIPE — Annuaire base sur les roles RACI reels (remplace les membres fictifs) ══ */
(function(){
'use strict';

window.equipeRenderPage = function(){
  var holder = document.getElementById("team-rows");
  if(!holder) return;

  var sector = (typeof window.matGetCur === "function") ? window.matGetCur() : "telecom";
  var baseRoles = (window.RACI_ROLES_BASE) ? window.RACI_ROLES_BASE : [];
  var sectorRoles = (window.RACI_SECTOR_ROLES && window.RACI_SECTOR_ROLES[sector]) ? window.RACI_SECTOR_ROLES[sector] : [];
  var allRoles = baseRoles.concat(sectorRoles);

  if(allRoles.length === 0){
    holder.innerHTML = '<div class="reg-empty">Definissez vos roles dans <a href="#" onclick="go(\'parties\',null,\'GOUVERNANCE\',\'Parties prenantes\');return false;">Parties prenantes -&gt;</a></div>';
    return;
  }

  /* Un role est "actif" si la matrice RACI lui a assigne au moins un processus */
  function roleHasAssignment(roleId){
    if(!window.RACI_STATE) return false;
    return Object.keys(window.RACI_STATE).some(function(procId){
      return window.RACI_STATE[procId] && window.RACI_STATE[procId][roleId];
    });
  }

  holder.innerHTML = allRoles.map(function(r){
    var initials = r.label.split(" ").map(function(w){ return w[0]; }).slice(0,2).join("").toUpperCase();
    var active = roleHasAssignment(r.id);
    return '<div class="eval-row" style="cursor:pointer" onclick="go(\'parties\',null,\'GOUVERNANCE\',\'Parties prenantes\')">'
      + '<div class="sb-avatar" style="background:'+(active?'var(--ink)':'var(--muted2)')+'">'+initials+'</div>'
      + '<div class="eval-body"><div class="eval-n">'+r.label+'</div><div class="eval-d">Rôle de gouvernance IA — secteur '+(window.MAT_SECTORS&&window.MAT_SECTORS[sector]?window.MAT_SECTORS[sector].label:sector)+'</div></div>'
      + '<div style="font-size:9px;font-family:var(--mono);color:'+(active?'var(--green)':'var(--muted2)')+'">'+(active?'● ASSIGNÉ':'○ À DÉFINIR')+'</div>'
      + '</div>';
  }).join('');
};

var _equipeOrigGo = window.go;
window.go = function(id){
  var r = _equipeOrigGo ? _equipeOrigGo.apply(this, arguments) : undefined;
  if(id === "equipe") setTimeout(window.equipeRenderPage, 80);
  return r;
};

})();



