window.__formCatRef = '';
window.formCatRender = function(){
  var grid = document.getElementById('form-cat-grid');
  var bar = document.getElementById('form-cat-filters');
  if(!grid) return;
  /* LA FAMILLE « ADOPTION » A SA COULEUR, et un bleu — aucune des cinq
     autres n'en porte. Un vert l'aurait rapprochée du sarcelle du RGPD, et
     deux familles qui se ressemblent à l'œil se confondent dans un filtre.
     Elle n'est pas une sixième famille réglementaire : les cinq premières
     apprennent à se METTRE EN RÈGLE, celle-ci apprend à SE SERVIR de ce
     qu'on déploie — public différent, promesse différente. */
  var COL = { 'IA Act':'#c9a227', 'RGPD':'#0E7C7B', 'ISO 42001':'#6B46C1', 'Transverse':'#c98a00', 'Programme':'#B03A2E', 'Adoption':'#1F5E8C' };
  var refs = ['', 'IA Act', 'RGPD', 'ISO 42001', 'Transverse', 'Programme', 'Adoption'];
  if(bar){
    bar.innerHTML = refs.map(function(r){
      var n = r ? window.FORMATIONS_CAT.filter(function(f){ return f.ref === r; }).length : window.FORMATIONS_CAT.length;
      var on = (window.__formCatRef === r);
      return '<button onclick="formCatFilter(\'' + r + '\')" style="font-size:11.5px;font-weight:600;padding:5px 12px;border-radius:999px;border:1px solid ' + (on ? 'var(--ink,#111827)' : 'var(--rule2)') + ';background:' + (on ? 'var(--ink,#111827)' : 'transparent') + ';color:' + (on ? '#fff' : 'var(--ink)') + ';cursor:pointer">' + (r || 'Toutes') + ' (' + n + ')</button>';
    }).join('');
  }
  var liste = window.FORMATIONS_CAT.filter(function(f){ return !window.__formCatRef || f.ref === window.__formCatRef; });
  grid.innerHTML = liste.map(function(f){
    var c = COL[f.ref] || '#c9a227';
    var prog = f.g.map(function(x){ return '<li>' + String(x).replace(/</g,'&lt;') + '</li>'; }).join('');
    return '<div class="t-card" onclick="formOpen(' + f.n + ')" style="cursor:pointer;border-left:3px solid ' + c + '">'
      + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">'
      + '<span style="font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:' + c + '">' + f.ref + '</span>'
      + '<span style="font-size:10px;color:var(--muted2,#999)">FORMATION ' + (f.n < 10 ? '0' : '') + f.n + '</span></div>'
      + '<div style="font-weight:700;font-size:13.5px;color:var(--ink);line-height:1.35;margin-bottom:6px">' + f.t + '</div>'
      + '<div style="font-size:11px;color:var(--muted);margin-bottom:8px">' + f.d + ' \u00b7 ' + f.p + '</div>'
      + '<div style="font-size:12px;color:var(--ink2,#444);line-height:1.6;margin-bottom:8px"><strong>Objectif.</strong> ' + f.o + '</div>'
      + '<details onclick="event.stopPropagation()"><summary style="cursor:pointer;font-size:11.5px;font-weight:600;color:var(--ink)">Programme d\u00e9taill\u00e9</summary>'
      + '<ul style="margin:6px 0 0 16px;padding:0;font-size:11.5px;line-height:1.7;color:var(--muted)">' + prog + '</ul></details>'
      + '<button onclick="event.stopPropagation();formOpen(' + f.n + ')" class="mat-export-btn" style="margin-top:10px;background:linear-gradient(135deg,#c9a227,#e6c65a);color:#14181f;border:none;font-weight:700">S\u2019inscrire \u00b7 dates et tarif</button>'
      + '</div>';
  }).join('');
};
