window.formMaj = function(){
  var sel = document.getElementById('fm-session');
  var nb = parseInt((document.getElementById('fm-nb') || {}).value || '1', 10) || 1;
  var tot = document.getElementById('fm-total');
  if(!sel || !tot) return;
  var opt = sel.options[sel.selectedIndex];
  var prix = opt ? parseInt(opt.getAttribute('data-prix') || '0', 10) : 0;
  if(!prix){ tot.textContent = 'Aucune session s\u00e9lectionnable \u2014 contactez CONSEILPREV.'; return; }
  var total = prix * nb / 100;
  var sessObj = (window.__formSessions || []).filter(function(x){ return String(x.id) === String(sel.value); })[0] || {};
  var pct = (sessObj.tva_pct != null) ? sessObj.tva_pct : 20;
  var ttc = total * (1 + pct / 100);
  tot.innerHTML = '<strong>Total : ' + ttc.toLocaleString('fr-FR', {maximumFractionDigits:2}) + '\u202f\u20ac TTC</strong>'
    + '<div style="font-size:11px;color:var(--muted);margin-top:3px">' + nb + ' participant(s) \u00d7 ' + (prix/100).toLocaleString('fr-FR') + '\u202f\u20ac HT = ' + total.toLocaleString('fr-FR') + '\u202f\u20ac HT'
    + (pct > 0 ? ' \u00b7 TVA ' + pct + '\u202f% : ' + (ttc - total).toLocaleString('fr-FR', {maximumFractionDigits:2}) + '\u202f\u20ac' : ' \u00b7 TVA non applicable') + '</div>';
};
window.formSubmit = function(){
  function v(id){ var e = document.getElementById(id); return e ? e.value.trim() : ''; }
  var out = document.getElementById('fm-msg-out');
  var btn = document.getElementById('fm-pay');
  var sid = v('fm-session');
  if(!sid){ if(out) out.textContent = 'Veuillez choisir une session.'; return; }
  if(!v('fm-prenom') || !v('fm-nom') || !v('fm-email')){ if(out) out.textContent = 'Pr\u00e9nom, nom et adresse \u00e9lectronique sont requis.'; return; }
  if(btn){ btn.disabled = true; btn.textContent = 'Traitement\u2026'; }
  if(out){ out.style.color = 'var(--muted)'; out.textContent = 'Enregistrement de la demande\u2026'; }
  fetch('/api/formations/inscription', { method:'POST', credentials:'same-origin', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ session_id: parseInt(sid, 10), participants: parseInt(v('fm-nb') || '1', 10),
      prenom: v('fm-prenom'), nom: v('fm-nom'), email: v('fm-email'), telephone: v('fm-tel'),
      entreprise: v('fm-ent'), fonction: v('fm-fct'), message: v('fm-msg') }) })
    .then(function(r){ return r.json(); })
    .then(function(d){
      if(!d || !d.ok){ if(out){ out.style.color = 'var(--accent)'; out.textContent = (d && d.error) || 'Erreur.'; } if(btn){ btn.disabled = false; btn.textContent = 'R\u00e9server et payer'; } return; }
      if(d.paiement && d.url){ window.location.href = d.url; return; }
      if(out){ out.style.color = 'var(--green,#0E7C7B)'; out.textContent = d.message || 'Demande enregistr\u00e9e. CONSEILPREV vous recontacte.'; }
      if(btn){ btn.disabled = true; btn.textContent = 'Demande envoy\u00e9e'; }
    })
    .catch(function(){ if(out){ out.style.color = 'var(--accent)'; out.textContent = 'Erreur r\u00e9seau.'; } if(btn){ btn.disabled = false; btn.textContent = 'R\u00e9server et payer'; } });
};
