(function(){
'use strict';

window.trainingRenderPage = function(){
  var holder = document.getElementById("training-grid");
  if(!holder || typeof window.matPillarScore !== "function") return;

  var sector = (typeof window.matGetCur === "function") ? window.matGetCur() : "telecom";

  function pct(pillarIds){
    var scores = pillarIds.map(function(p){ return window.matPillarScore(sector, p) || 0; });
    var avg = scores.reduce(function(a,b){ return a+b; },0) / scores.length;
    return Math.round(avg/5*100);
  }

  var MODULES = [
    {key:"euaiact", badge:"t-req", title:"EU AI Act — Fondamentaux", desc:"Classification des risques, obligations par catégorie, calendrier de conformité.", dur:"3h", pillars:["gouvernance","transparence","explicabilite"]},
    {key:"cyber", badge:"t-req", title:"Cybersécurité IA (NIS2 / Sûreté)", desc:"Obligations de sécurité pour les systèmes IA dans les entités essentielles.", dur:"2h", pillars:["confidentialite","robustesse"]},
    {key:"rgpd", badge:"t-opt", title:"RGPD & Données d'entraînement", desc:"Base légale, minimisation, droits des personnes dans les systèmes IA.", dur:"2h30", pillars:["confidentialite","equite"]},
    {key:"iso42001", badge:"t-opt", title:"Gouvernance IA — ISO 42001", desc:"Mise en place d'un système de management IA conforme au standard international.", dur:"4h", pillars:["gouvernance","controlabilite"]}
  ];

  holder.innerHTML = MODULES.map(function(t){
    var p = pct(t.pillars);
    var done = p >= 80;
    return '<div class="t-card t-card-clickable" onclick="trainingOpenFiche(\'' + t.key + '\')"><div class="t-badge '+t.badge+'">'+(t.badge==='t-req'?'REQUIS':'OPTIONNEL')+'</div>'
      + '<div class="t-title">'+t.title+'</div><div class="t-desc">'+t.desc+'</div>'
      + '<div class="t-foot"><div class="t-dur">'+t.dur+'</div>'
      + '<div class="t-prog-track"><div class="t-prog-fill" style="width:'+p+'%"></div></div>'
      + '<div class="t-pct" style="color:'+(done?'var(--green)':p>=40?'var(--orange)':'var(--accent)')+'">'+p+'%'+(done?' ✓':'')+'</div></div>'
      + '<div style="font-size:9px;color:var(--muted2);margin-top:6px">Basé sur vos scores réels (Audit de maturité, secteur '+(window.MAT_SECTORS&&window.MAT_SECTORS[sector]?window.MAT_SECTORS[sector].label:sector)+')</div>'
      + '<div class="card-cta">Voir la fiche de formation →</div>'
      + '</div>';
  }).join('');
};

var _trainOrigGo = window.go;
window.go = function(id){
  var r = _trainOrigGo ? _trainOrigGo.apply(this, arguments) : undefined;
  if(id === "training") setTimeout(window.trainingRenderPage, 80);
  return r;
};

})();



