/* ══ COMPARATEUR — CJ_DATA genere dynamiquement depuis JURS (synchronise) ══ */
(function(){
'use strict';

function cjBuildDataFromJurs(){
  if(!window.JURS) return;
  var data = {};
  window.JURS.forEach(function(j){
    var detail = (window.JURS_DETAIL && window.JURS_DETAIL[j.c]) || null;
    var s = j.s;
    var transparence, responsabilite, souverainete, sanctions;
    if(detail){
      transparence = detail.transparence;
      responsabilite = Math.round(((detail.supervision_humaine||0) + (detail.droits_fondamentaux||0)) / 2 * 10) / 10;
      souverainete = Math.round(((detail.extraterritorialite||0) + (detail.contraignant||0)) / 2 * 10) / 10;
      sanctions = detail.sanctions;
    } else {
      /* Variation cohérente derivee du score global si pas de detail disponible */
      transparence = Math.max(0, Math.min(10, Math.round((s*0.92)*10)/10));
      responsabilite = Math.max(0, Math.min(10, Math.round((s*0.95)*10)/10));
      souverainete = Math.max(0, Math.min(10, Math.round((s*0.88)*10)/10));
      sanctions = Math.max(0, Math.min(10, Math.round((s*0.85)*10)/10));
    }
    /* Innovation : dimension independante (pas dans JURS), estimee inversement correlee a la severite */
    var innovation = Math.max(2, Math.min(9.5, Math.round((10 - s*0.55)*10)/10));

    var badge = s>=7 ? 'RISQUE ÉLEVÉ' : s>=4.5 ? 'RISQUE MODÉRÉ' : 'RISQUE FAIBLE';
    var badgeCls = s>=7 ? 'chip-r' : s>=4.5 ? 'chip-o' : 'chip-g';

    data[j.c] = {
      name: j.name, flag: j.f, cadre: j.reg,
      scores: { 'Sévérité': s, 'Transparence': transparence, 'Responsabilité': responsabilite, 'Souveraineté': souverainete, 'Sanctions': sanctions, 'Innovation': innovation },
      badge: badge, badgeCls: badgeCls
    };
  });
  /* Muter l objet CJ_DATA existant en place (au lieu de le remplacer) pour que
     la variable locale CJ_DATA de l IIFE du comparateur voie aussi les changements */
  if(window.CJ_DATA){
    Object.keys(window.CJ_DATA).forEach(function(k){ delete window.CJ_DATA[k]; });
    Object.keys(data).forEach(function(k){ window.CJ_DATA[k] = data[k]; });
  } else {
    window.CJ_DATA = data;
  }
  return data;
}

window.cjBuildDataFromJurs = cjBuildDataFromJurs;
window.cjRefreshFromJurs = function(){
  cjBuildDataFromJurs();
  if(typeof window.cjRender === "function") window.cjRender();
};

var _cjOrigGo = window.go;
window.go = function(id){
  var r = _cjOrigGo ? _cjOrigGo.apply(this, arguments) : undefined;
  if(id === "comp") setTimeout(window.cjRefreshFromJurs, 50);
  return r;
};

})();



