/* ══ SIMULATEUR — Comparaison internationale (connectee a JURS) ══ */
(function(){
'use strict';

window.simBuildIntlComparison = function(classif){
  if(!window.JURS || window.JURS.length === 0) return "";

  /* Selectionner 5 juridictions representatives : UE (reference) + 4 contrastees par score */
  var sorted = window.JURS.slice().sort(function(a,b){ return b.s - a.s; });
  var eu = sorted.find(function(j){ return j.c === "EU"; });
  var others = sorted.filter(function(j){ return j.c !== "EU"; });
  var picks = [eu].filter(Boolean);
  /* Prendre des juridictions a intervalles reguliers pour varier les niveaux de contrainte */
  var step = Math.max(1, Math.floor(others.length / 4));
  for(var i=0; i<others.length && picks.length<5; i+=step){ picks.push(others[i]); }

  var euScore = eu ? eu.s : 9.2;

  var rows = picks.map(function(j){
    var diff = j.s - euScore;
    var diffTxt = j.c === "EU" ? "Référence" : (diff>=0?'+':'') + diff.toFixed(1) + " pts";
    var diffColor = j.c === "EU" ? "var(--muted2)" : diff >= 0 ? "var(--accent)" : "var(--green)";
    var niveau = j.s>=8?"Très strict":j.s>=5?"Modéré":"Souple";
    return '<div class="intl-row"><div class="intl-flag">'+j.f+'</div>'
      + '<div class="intl-name">'+j.name+'<div class="intl-reg">'+j.reg.substring(0,60)+(j.reg.length>60?'…':'')+'</div></div>'
      + '<div class="intl-score" style="color:'+(j.s>=8?'var(--accent)':j.s>=5?'var(--orange)':'var(--green)')+'">'+j.s+'/10</div>'
      + '<div class="intl-niveau">'+niveau+'</div>'
      + '<div class="intl-diff" style="color:'+diffColor+'">'+diffTxt+'</div></div>';
  }).join('');

  return '<div class="sim-obl-title" style="margin-top:20px">Comparaison internationale — où ce système serait-il moins contraint ?</div>'
    + '<div class="intl-compare-box">'
    + '<div class="intl-row intl-head"><div></div><div>Juridiction</div><div>Score</div><div>Niveau</div><div>vs. UE</div></div>'
    + rows
    + '<div style="font-size:10px;color:var(--muted2);margin-top:10px;font-style:italic">Comparaison à titre indicatif sur la sévérité réglementaire générale (cadre IA global), ne reflète pas une classification formelle de ce système dans chaque juridiction. Voir <a href="#" onclick="go(\'comp\',null,\'ANALYSE\',\'Comparateur\');return false;" style="color:var(--accent)">le Comparateur complet →</a></div>'
    + '</div>';
};

})();



