window.milestonesRender = function(){
  var tb=document.getElementById('ms-tbody');
  var sm=document.getElementById('ms-summary');
  if(!tb || !sm) return;
  var sched=window.__milestoneSchedule;
  if(!sched){ return; }
  var roleSel=document.getElementById('ms-role-select');
  var role=(roleSel&&roleSel.value)||'deployeur';
  var roleJalons=window.RAAS_ROLE_MILESTONES[role]||null;
  /* Le profil metier (parcours guide Sentinel) determine egalement les jalons :
     seuls les jalons couverts par les modules du profil ET applicables au role
     sont retenus (intersection). */
  var profSel=document.getElementById('ms-profile-select');
  var profId=(profSel&&profSel.value)||'directeur_programme';
  var profJalons=window.RAAS_PROFILE_MILESTONES[profId]||null;
  var applicable=null;
  if(roleJalons && profJalons){
    applicable=roleJalons.filter(function(id){ return profJalons.indexOf(id)!==-1; });
  } else {
    applicable=roleJalons || profJalons;
  }
  if(window.milestonesRenderRoleNote) window.milestonesRenderRoleNote(role);
  if(window.milestonesRenderProfile) window.milestonesRenderProfile();
  var shownMs = applicable ? sched.milestones.filter(function(m){ return applicable.indexOf(m.id)!==-1; }) : sched.milestones;
  var envShown = shownMs.reduce(function(a,m){ return a+m.amount; }, 0);
  var totalShown = sched.socle*12 + envShown;
  var saasM=(function(){
    var nb=parseInt((document.getElementById('pricing-nb-systemes')||{value:'10'}).value||'10',10);
    var sec=(document.getElementById('pricing-secteur')&&document.getElementById('pricing-secteur').value)||'it';
    var seg=(document.getElementById('pricing-segment')&&document.getElementById('pricing-segment').value)||'pme';
    var bi=window.__pricingBilling||'monthly';
    return pricingComputeSaaS(nb,sec,bi,seg);
  })();
  var saasAnnual=saasM*12;
  var pctShown = saasAnnual>0 ? Math.round(totalShown / saasAnnual * 100) : sched.pctOfSaas;
  function eur(n){return n.toLocaleString('fr-FR')+'\u202f\u20ac';}
  /* Cartes de synthese (adaptees au role selectionne) */
  sm.innerHTML=
    '<div class="ms-sum-card"><div class="ms-sum-lbl">Socle mensuel garanti</div>'
    +'<div class="ms-sum-val">'+eur(sched.socle)+'</div>'
    +'<div class="ms-sum-sub">\u223535\u00a0% du SaaS \u2014 seul co\u00fbt fixe</div></div>'
    +'<div class="ms-sum-card"><div class="ms-sum-lbl">Enveloppe r\u00e9sultats ('+shownMs.length+' jalons)</div>'
    +'<div class="ms-sum-val">'+eur(envShown)+'</div>'
    +'<div class="ms-sum-sub">jalons applicables \u00e0 votre r\u00f4le \u2014 pay\u00e9s si v\u00e9rifi\u00e9s</div></div>'
    +'<div class="ms-sum-card"><div class="ms-sum-lbl">Total maximal annuel</div>'
    +'<div class="ms-sum-val" style="color:var(--green)">'+eur(totalShown)+'</div>'
    +'<div class="ms-sum-sub">'+pctShown+'\u00a0% du SaaS ('+eur(saasAnnual)+') \u2014 toujours inf\u00e9rieur</div></div>';
  /* Rangees jalons applicables au role */
  var rows='';
  shownMs.forEach(function(ms){
    rows+='<tr>'
      +'<td>'+ms.label+'</td>'
      +'<td><span class="ms-badge-art">'+ms.art+'</span></td>'
      +'<td><span class="ms-badge-seuil">score \u2265 '+ms.threshold+'</span></td>'
      +'<td>'+Math.round(ms.w*100)+'\u00a0%</td>'
      +'<td class="ms-amount">'+eur(ms.amount)+'</td>'
      +'<td>'+(ms.monthTriggered
        ? '<span class="ms-badge-mois">M'+ms.monthTriggered+'\u2013M'+(ms.monthTriggered+sched.payMonths-1)+'</span>'
        : '<span class="ms-badge-na">au-del\u00e0 de l\u2019horizon</span>')+'</td>'
      +'</tr>';
  });
  rows+='<tr class="ms-total-row">'
    +'<td colspan="4">Total des jalons applicables \u00e0 votre r\u00f4le (socle 12 mois inclus)</td>'
    +'<td class="ms-amount">'+eur(totalShown)+'</td>'
    +'<td><span class="ms-badge-mois">'+pctShown+'\u00a0% du SaaS</span></td>'
    +'</tr>';
  tb.innerHTML=rows;
};

