  var sec=(document.getElementById('pricing-secteur')&&document.getElementById('pricing-secteur').value)||'it';
  var nb=parseInt((document.getElementById('pricing-nb-systemes')||{value:'10'}).value||'10',10);
  var bi=window.__pricingBilling||'monthly';
  var saasM=pricingComputeSaaS(nb,sec,bi,seg);
  /* Role AI Act + profil metier : filtrer les jalons comme a l'ecran (intersection) */
  var roleSel=document.getElementById('ms-role-select');
  var role=(roleSel&&roleSel.value)||'deployeur';
  var profSel=document.getElementById('ms-profile-select');
  var profId=(profSel&&profSel.value)||'directeur_programme';
  var roleJ=(window.RAAS_ROLE_MILESTONES&&window.RAAS_ROLE_MILESTONES[role])||null;
  var profJ=(window.RAAS_PROFILE_MILESTONES&&window.RAAS_PROFILE_MILESTONES[profId])||null;
  var applicable=(roleJ&&profJ)?roleJ.filter(function(id){return profJ.indexOf(id)!==-1;}):(roleJ||profJ);
  var shownMs=applicable?sched.milestones.filter(function(m){return applicable.indexOf(m.id)!==-1;}):sched.milestones;
  var envShown=shownMs.reduce(function(a,m){return a+m.amount;},0);
  var totalShown=sched.socle*12+envShown;
  var pctShown=Math.round(totalShown/(saasM*12)*100);
  var roleLbl={fournisseur:'Fournisseur',deployeur:'D\u00e9ployeur',importateur:'Importateur',distributeur:'Distributeur'}[role]||role;
  var profLbl=(window.RAAS_PROFILES&&window.RAAS_PROFILES[profId])?window.RAAS_PROFILES[profId].role:profId;
  var segLbl={pme:'PME (< 250 salari\u00e9s)',eti:'ETI',ge:'Grands comptes'}[seg]||seg;
