  var biLbl=bi==='annual'?'Annuel (12 mois)':'Mensuel (sans engagement)';
  var today=new Date().toLocaleDateString('fr-FR');
  function eur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
