    +'.guar{background:rgba(45,122,71,.05);border:1px solid rgba(45,122,71,.25);border-radius:6px;padding:12px 16px;font-size:11.5px;line-height:1.7;margin-top:14px}'
    +'.pagebreak{page-break-before:always;break-before:page}'
    +'.clauses{background:#faf9f7;border:1px solid #e5e2dd;border-radius:6px;padding:12px 16px;font-size:11.5px;line-height:1.7;margin-top:14px}'
    +'.sign{display:flex;gap:40px;margin-top:44px;font-size:12px;font-family:Arial}'
    +'.sign div{flex:1;border-top:1px solid #999;padding-top:8px}'
