/* ══ BASE DE CONNAISSANCE — RAG (upload, liste, download, recherche) ══ */
(function(){
'use strict';

window.ragFormatSize = function(bytes){
  if(bytes < 1024) return bytes + ' o';
  if(bytes < 1024*1024) return (bytes/1024).toFixed(1) + ' Ko';
  return (bytes/(1024*1024)).toFixed(1) + ' Mo';
};

window.ragHandleDrop = function(evt){
  evt.preventDefault();
  document.getElementById('rag-drop-zone').classList.remove('rag-drop-active');
  var files = evt.dataTransfer.files;
  if(files.length > 0) window.ragHandleFileSelect(files);
};

window.ragGetAccessKey = function(){
  var key = sessionStorage.getItem('ragAccessKey');
  if(!key){
    key = prompt('Accès réservé à CONSEILPREV — entrez la clé d accès à la base de connaissance :');
    if(key) sessionStorage.setItem('ragAccessKey', key);
  }
  return key || '';
};

window.ragHeaders = function(){
  return { 'X-RAG-Key': window.ragGetAccessKey() };
};

window.ragHandleAuthError = function(status){
  /* 503 et 403 n appellent pas le meme geste : dans un cas la cle est mauvaise
     et il faut la ressaisir, dans l autre le SERVEUR n en a aucune et ressaisir
     ne servira a rien. Effacer la cle sur un 503 ferait chercher pendant des
     heures une cle qui etait la bonne. */
  if(status === 503){
    alert('La base de connaissance n’est pas configurée sur ce serveur : la variable '
        + 'RAG_ACCESS_KEY est absente. Définissez-la dans les variables d’environnement '
        + 'de l’hébergement, puis rechargez la page. Votre clé n’est pas en cause.');
    return true;
  }
  if(status === 403){
    sessionStorage.removeItem('ragAccessKey');
    alert('Clé d accès incorrecte ou absente. Réessayez.');
    return true;
  }
  return false;
};

/* Lire la reponse en TEXTE d'abord, puis tenter le JSON.

   Une passerelle qui rend une page d'erreur HTML — 502 pendant un
   redemarrage, 504 sur un traitement trop long, 413 sur un corps trop gros —
   fait echouer r.json(). Cet echec tombait dans le .catch et etait rapporte
   comme une « erreur reseau », alors qu'une reponse etait bien arrivee, avec
   son code. On confondait « rien n'est arrive » et « le serveur a repondu ce
   qu'on n'attendait pas » : deux pannes differentes, deux gestes differents. */
window.ragLireReponse = function (r) {
  return r.text().then(function (txt) {
    var d = null;
    try { d = JSON.parse(txt); } catch (e) { d = null; }
    return { status: r.status, data: d || {}, json: d !== null, brut: txt };
  });
};

/* Ce que dit un code HTTP quand le corps n'est pas exploitable. */
window.ragCauseHttp = function (res) {
  var s = res.status;
  var brut = String(res.brut || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  var quoi;
  if (s === 413) {
    quoi = 'Le fichier a été refusé AVANT d atteindre Sentinel : il dépasse la taille '
         + 'acceptée par la passerelle, qui ne consulte pas la limite du site.';
  } else if (s === 502 || s === 503) {
    quoi = 'Le service s est arrêté pendant l import puis a redémarré — le plus souvent '
         + 'faute de mémoire sur un document volumineux.';
  } else if (s === 504) {
    quoi = 'La passerelle a coupé avant la fin du traitement : l extraction a duré plus '
         + 'longtemps qu elle ne l autorise.';
  } else if (s >= 500) {
    quoi = 'Le serveur a échoué (' + s + ') sans message exploitable.';
  } else {
    quoi = 'Le serveur a répondu ' + s + ' sans message exploitable.';
  }
  return quoi + (brut ? ' Réponse reçue : « ' + brut.slice(0, 160) + ' »' : '');
};

/* Une sauvegarde conseilprevcyber deposee dans « Ajouter un document » serait
   enregistree comme UN document de base64 illisible — quand elle n est pas
   refusee d emblee pour sa taille, apres avoir ete televersee pour rien. On la
   reconnait a ses premiers octets, avant d envoyer quoi que ce soit, et on la
   confie au bloc qui sait en extraire les documents un par un. */
function ragEstSauvegarde(tete){
  var t = String(tete || '');
  if(!/^[\uFEFF\s]*\{/.test(t)) return false;     /* une sauvegarde est un objet JSON */
  return /"app"\s*:\s*"conseilprevcyber-rag"/.test(t)
      || (t.indexOf('"documents"') >= 0 && t.indexOf('content_b64') >= 0);
}

var RAG_FORCE = null;

window.ragForcerDocument = function(){
  var f = RAG_FORCE;
  if(!f) return;
  RAG_FORCE = null;
  document.getElementById('imp-etat').innerHTML = '';
  ragEnvoyerDocument(f);
};

function ragRediriger(file){
  RAG_FORCE = file;
  IMP.fichier = file;
  var inv = document.getElementById('imp-inv');
  if(file.size > window.IMP_SEUIL_FLUX) impProposerFlux(file, inv);
  else window.impChoisir([file]);
  document.getElementById('imp-etat').innerHTML =
    '<div style="border:1px solid var(--rule2);border-left:3px solid var(--accent);'
    + 'border-radius:8px;padding:12px 14px;background:var(--bg);font-size:11.5px;'
    + 'color:var(--ink2);line-height:1.6">'
    + '<b>Ce fichier est une sauvegarde conseilprevcyber</b> (' + impPoids(file.size) + '), '
    + 'pas un document. Déposé dans « Ajouter un document », il serait enregistré comme un '
    + 'seul fichier de base64 illisible. Il a donc été confié au transfert ci-dessus, qui sait '
    + 'en extraire les documents un par un.'
    + '<br><button class="mat-export-btn" style="margin-top:8px" '
    + 'onclick="ragForcerDocument()">L’enregistrer quand même comme un document</button></div>';
  inv.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

window.ragHandleFileSelect = function(files){
  if(!files || files.length === 0) return;
  var file = files[0];
  var allowedExt = ['.pdf','.docx','.xlsx','.xlsm','.txt','.md','.csv','.log','.json','.yaml','.yml'];
  var ext = '.' + file.name.split('.').pop().toLowerCase();
  if(allowedExt.indexOf(ext) === -1){
    alert('Format non accepté. Formats acceptés : PDF, Word (.docx), Excel (.xlsx, .xlsm), texte, Markdown, CSV, journal, JSON, YAML.');
    return;
  }
  document.getElementById('rag-file-input').value = '';

  var tete = new FileReader();
  tete.onerror = function(){ ragEnvoyerDocument(file); };
  tete.onload = function(){
    var debut = '';
    try { debut = new TextDecoder('utf-8').decode(new Uint8Array(tete.result)); }
    catch(e){ debut = ''; }
    if(ragEstSauvegarde(debut)){ ragRediriger(file); return; }
    /* Le plafond du serveur est connu depuis le diagnostic : refuser ICI evite
       de televerser six cent cinquante mégaoctets pour s entendre dire non. */
    if(RAG_TAILLE_MAX && file.size > RAG_TAILLE_MAX){
      alert('Ce fichier fait ' + impPoids(file.size) + ' ; la limite est de '
          + Math.round(RAG_TAILLE_MAX / 1048576) + ' Mo. Découpez le document, ou relevez '
          + 'RAG_MAX_FILE_SIZE_MO dans les variables d environnement.'
          + '\n\nRien n’a été envoyé : le contrôle a lieu avant le transfert, pour ne pas '
          + 'téléverser ' + impPoids(file.size) + ' en pure perte.');
      return;
    }
    ragEnvoyerDocument(file);
  };
  tete.readAsArrayBuffer(file.slice(0, 4096));
};

function ragEnvoyerDocument(file){
  var checkedPages = Array.from(document.querySelectorAll('.rag-pages-checks input:checked')).map(function(cb){ return cb.value; });
  if(checkedPages.length === 0) checkedPages = ['general'];

  var progressEl = document.getElementById('rag-upload-progress');
  var labelEl = document.getElementById('rag-progress-label');
  var pctEl = document.getElementById('rag-progress-pct');
  var fillEl = document.getElementById('rag-progress-fill');
  if(progressEl) progressEl.style.display = 'block';
  if(labelEl) labelEl.textContent = 'Envoi et extraction du texte…';
  if(pctEl) pctEl.textContent = '';
  if(fillEl) fillEl.style.width = '15%';

  var formData = new FormData();
  formData.append('file', file);
  formData.append('pages_liees', checkedPages.join(','));

  /* Le plafond est passe de 8 a 30 Mo : le transfert lui-meme peut demander
     plusieurs dizaines de secondes sur une liaison ordinaire. Abandonner a 60 s
     ferait echouer un envoi qui allait aboutir. */
  var controller = new AbortController();
  var timeoutId = setTimeout(function(){ controller.abort(); }, 180000);

  fetch('/api/rag/upload', { method: 'POST', headers: window.ragHeaders(), body: formData, signal: controller.signal })
    .then(function(r){ clearTimeout(timeoutId); return window.ragLireReponse(r); })
    .then(function(res){
      document.getElementById('rag-file-input').value = '';
      if(window.ragHandleAuthError(res.status)){ if(progressEl) progressEl.style.display = 'none'; return; }
      if(!res.json){
        if(progressEl) progressEl.style.display = 'none';
        alert('L import a échoué. ' + window.ragCauseHttp(res)
            + '\n\nFichier : ' + file.name + ' (' + impPoids(file.size) + ').'
            + '\n\nVérifiez la liste dans un instant : si le document y figure, l import a '
            + 'malgré tout abouti.');
        setTimeout(window.ragRenderList, 3000);
        return;
      }
      if(res.status === 201){
        if(fillEl) fillEl.style.width = '40%';
        /* Le serveur peut accepter un document SANS conserver son original :
           le taire ferait découvrir la chose des mois plus tard, au moment
           d'un téléchargement qui échoue. */
        if(res.data.warning) alert(res.data.warning);
        if(res.data.statut_indexation === 'en_cours'){
          window.ragPollIndexation(res.data.document.id, res.data.document.nom_fichier, res.data.document.nb_chunks);
        } else {
          if(progressEl) progressEl.style.display = 'none';
          window.ragRenderList();
        }
      } else {
        if(progressEl) progressEl.style.display = 'none';
        alert('Erreur : ' + (res.data.error || 'échec de l import'));
      }
    })
    .catch(function(err){
      clearTimeout(timeoutId);
      if(progressEl) progressEl.style.display = 'none';
      if(err.name === 'AbortError'){
        alert('L import prend plus de temps que prévu. Le document est peut-être volumineux — vérifiez la liste dans quelques instants, il devrait apparaître une fois traité.');
        setTimeout(window.ragRenderList, 3000);
      } else {
        /* Aucune reponse n'est arrivee : ce n'est pas la meme panne qu'un
           serveur qui repond mal, et le geste utile n'est pas le meme non
           plus. L'envoi peut d'ailleurs avoir abouti cote serveur, seule la
           reponse s'etant perdue — d'ou le rafraichissement de la liste. */
        alert('La connexion s est interrompue pendant l import : aucune réponse n est '
            + 'arrivée. Soit le réseau a coupé, soit le service s est arrêté en cours de '
            + 'traitement — un document volumineux peut épuiser sa mémoire.'
            + '\n\nFichier : ' + file.name + ' (' + impPoids(file.size) + ').'
            + (err && err.message ? '\nDétail : ' + err.message : '')
            + '\n\nVérifiez la liste dans un instant : si le document y figure, l import a '
            + 'malgré tout abouti.');
        setTimeout(window.ragRenderList, 3000);
      }
    });
};

window.ragPollIndexation = function(docId, nomFichier, totalChunks){
  var progressEl = document.getElementById('rag-upload-progress');
  var labelEl = document.getElementById('rag-progress-label');
  var pctEl = document.getElementById('rag-progress-pct');
  var fillEl = document.getElementById('rag-progress-fill');
  var attempts = 0;
  var maxAttempts = 60; /* chaque appel traite ~10 chunks ; 60 appels couvrent de gros documents */

  function processBatch(){
    attempts++;
    fetch('/api/rag/documents/' + docId + '/index-next-batch', { method: 'POST', headers: window.ragHeaders() })
      .then(function(r){ return r.json(); })
      .then(function(d){
        var indexes = d.chunks_indexes || 0;
        var total = d.nb_chunks || totalChunks || 1;
        var pct = Math.min(100, Math.round(40 + (indexes/total)*60)); /* 40% deja acquis a l upload + 60% pour l indexation */
        if(fillEl) fillEl.style.width = pct + '%';
        if(pctEl) pctEl.textContent = pct + '%';
        if(labelEl) labelEl.textContent = 'Indexation sémantique… (' + indexes + '/' + total + ' segments)';

        if(d.statut === 'termine'){
          if(labelEl) labelEl.textContent = '✅ "' + nomFichier + '" indexé avec succès';
          if(fillEl) fillEl.style.width = '100%';
          if(pctEl) pctEl.textContent = '100%';
          setTimeout(function(){ if(progressEl) progressEl.style.display = 'none'; window.ragRenderList(); }, 800);
        } else if(attempts < maxAttempts){
          processBatch(); /* lot suivant immediatement, pas d attente : chaque appel est deja borne et rapide */
        } else {
          if(labelEl) labelEl.textContent = 'Indexation partielle — le document reste utilisable, réessayez plus tard pour terminer.';
          setTimeout(function(){ if(progressEl) progressEl.style.display = 'none'; window.ragRenderList(); }, 1500);
        }
      })
      .catch(function(){
        if(attempts < maxAttempts) setTimeout(processBatch, 2000);
        else { if(progressEl) progressEl.style.display = 'none'; window.ragRenderList(); }
      });
  }
  processBatch();
};




window.ragDeleteDoc = function(id, nom){
  if(!confirm('Supprimer définitivement "'+nom+'" et tous ses segments indexés ?')) return;
  fetch('/api/rag/documents/' + id, { method: 'DELETE', headers: window.ragHeaders() }).then(function(r){
    if(window.ragHandleAuthError(r.status)) return;
    window.ragRenderList();
  });
};

var RAG_PAGE_LABELS = { audit:"Audit IA Act", registre:"Registre IA", fria:"FRIA", maturite:"Audit de maturité", veille:"Veille qualifiée", raci:"RACI", general:"Général" };

window.explorerAsk = function(){
  var q = document.getElementById('expl-q');
  var out = document.getElementById('expl-out');
  var meta = document.getElementById('expl-meta');
  if(!q || !out || !q.value.trim()) return;
  var sources = [];
  ['document','veille','analyse'].forEach(function(s){
    var el = document.getElementById('expl-src-' + s);
    if(el && el.checked) sources.push(s);
  });
  if(!sources.length){ sources = ['document','veille','analyse']; }
  if(meta) meta.textContent = 'Exploration en cours\u2026';
  out.innerHTML = '<div class="reg-loading">Consultation de la base de connaissance\u2026</div>';
  fetch('/api/sentinel/explorer', {
    method:'POST', credentials:'same-origin',
    headers: Object.assign({'Content-Type':'application/json'}, window.ragHeaders ? window.ragHeaders() : {}),
    body: JSON.stringify({ question: q.value.trim(), sources: sources, top_k: 8 })
  })
  .then(function(r){
    if(window.ragHandleAuthError && window.ragHandleAuthError(r.status)) return null;
    return r.json();
  })
  .then(function(d){
    if(!d){ out.innerHTML = ''; return; }
    if(!d.ok){ out.innerHTML = '<div class="reg-empty" style="color:var(--accent)">' + (d.error || 'Erreur') + '</div>'; if(meta) meta.textContent=''; return; }
    var SRC = { document:'Base documentaire', veille:'Veille r\u00e9glementaire', analyse:'Analyses de la plateforme' };
    var COL = { document:'#6B46C1', veille:'#0E7C7B', analyse:'#c98a00' };
    if(meta){
      var cadres = (d.cadres && d.cadres.length) ? (' \u00b7 Cadres d\u00e9tect\u00e9s : ' + d.cadres.join(', ')) : '';
      meta.textContent = d.total + ' r\u00e9sultat(s) \u00b7 moteur ' + d.moteur + cadres;
    }
    var synth = '';
    if(d.synthese){
      synth = '<div style="border:1px solid var(--rule2);border-left:3px solid #6B46C1;border-radius:10px;padding:14px 16px;background:var(--white);margin-bottom:14px">'
        + '<div style="font-weight:700;font-size:12px;color:var(--ink);margin-bottom:6px">R\u00e9ponse de synth\u00e8se <span style="display:inline-block;padding:1px 6px;background:#14181f;color:#fff;font-size:9px;font-weight:800;letter-spacing:.06em;border-radius:3px;margin-left:4px">AI GENERATED</span></div>'
        + '<div style="font-size:12.5px;color:var(--ink);line-height:1.65;white-space:pre-wrap">' + String(d.synthese).replace(/</g,'&lt;') + '</div>'
        + '<div style="font-size:10.5px;color:var(--muted);margin-top:8px">Synth\u00e8se fond\u00e9e uniquement sur les sources ci-dessous. Ne constitue pas un conseil juridique.</div></div>';
    }
    if(!d.resultats || !d.resultats.length){
      out.innerHTML = '<div class="reg-empty">Aucun \u00e9l\u00e9ment pertinent trouv\u00e9. Reformulez la question ou importez des documents.</div>';
      return;
    }
    out.innerHTML = synth + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:6px 0 6px 0">Sources</div>' + d.resultats.map(function(r){
      var pct = Math.round((r.score_final || 0) * 100);
      var lien = (r.type === 'veille' && r.ref) ? '<a href="'+r.ref+'" target="_blank" rel="noopener" style="font-size:10px;color:var(--ink)">Ouvrir la source</a>' : '';
      if(r.type === 'document' && r.ref){ lien = '<button class="histo-btn-sm" onclick="ragDownload('+r.ref+')">\u2b07 T\u00e9l\u00e9charger</button>'; }
      return '<div class="histo-row">'
        + '<div class="histo-row-top"><span class="histo-page-chip" style="background:'+(COL[r.type]||'#666')+';color:#fff">'+(SRC[r.type]||r.type)+'</span>'
        + '<span class="histo-date">pertinence '+pct+' %</span></div>'
        + '<div class="histo-label">'+String(r.titre||'').replace(/</g,'&lt;')+'</div>'
        + '<div style="font-size:11.5px;color:var(--muted);margin-top:3px;line-height:1.5">'+String(r.extrait||'').replace(/</g,'&lt;')+'</div>'
        + (lien ? '<div class="histo-actions">'+lien+'</div>' : '')
        + '</div>';
    }).join('');
  })
  .catch(function(){ out.innerHTML = '<div class="reg-empty" style="color:var(--accent)">Erreur d\u2019exploration.</div>'; if(meta) meta.textContent=''; });
};

window.ragDownload = function(id, nom){
  fetch('/api/rag/download/' + id, { headers: window.ragHeaders(), credentials: 'same-origin' })
    .then(function(r){
      if(window.ragHandleAuthError(r.status)) return null;
      if(!r.ok){
        return r.json().catch(function(){ return {}; }).then(function(e){
          alert((e && e.error) ? e.error : ('\u00c9chec du t\u00e9l\u00e9chargement (erreur ' + r.status + ').'));
          return null;
        });
      }
      return r.blob().then(function(b){ return { blob: b, nom: nom || ('document-' + id) }; });
    })
    .then(function(res){
      if(!res) return;
      var url = URL.createObjectURL(res.blob);
      var a = document.createElement('a');
      a.href = url; a.download = res.nom;
      document.body.appendChild(a); a.click();
      setTimeout(function(){ URL.revokeObjectURL(url); a.remove(); }, 1500);
    })
    .catch(function(){ alert('T\u00e9l\u00e9chargement impossible : v\u00e9rifiez votre connexion.'); });
};

window.ragDocRow = function(doc){
  var pagesChips = (doc.pages_liees || []).map(function(p){ return '<span class="rag-page-chip">'+(RAG_PAGE_LABELS[p]||p)+'</span>'; }).join('');
  var d1 = new Date(doc.date_upload).toLocaleDateString('fr-FR', {day:'2-digit',month:'2-digit',year:'numeric'});
  var nomJs = JSON.stringify(doc.nom_fichier || '').replace(/"/g, '&quot;');
  return '<div class="histo-row">'
    + '<div class="histo-row-top"><span class="histo-page-chip">'+String(doc.extension||'').replace('.','').toUpperCase()+'</span>'+pagesChips+'<span class="histo-date">'+d1+'</span></div>'
    + '<div class="histo-label">'+String(doc.nom_fichier||'').replace(/</g,'&lt;')+'</div>'
    + '<div style="font-size:10px;color:var(--muted2);margin-top:2px">'+window.ragFormatSize(doc.taille_octets)+' \u00b7 '+doc.nb_chunks+' segment(s) index\u00e9(s)'
    /* Le classement d'origine, quand le document vient d'une autre plateforme :
       c'est sous CE nom que son proprietaire le cherchera, pas sous le notre. */
    + (doc.theme ? ' \u00b7 <span style="color:var(--blue)">'+String(doc.theme).replace(/</g,'&lt;')+'</span>' : '')
    + (doc.entreprise ? ' \u00b7 <b>'+String(doc.entreprise).replace(/</g,'&lt;')+'</b>' : '')
    + (doc.origine ? ' \u00b7 repris de '+String(doc.origine).replace(/</g,'&lt;') : '')
    + '</div>'
    + '<div class="histo-actions">'
    + '<button class="histo-btn-sm" onclick="ragDownload('+doc.id+', '+nomJs+')" title="T\u00e9l\u00e9charger le fichier original">\u2b07 T\u00e9l\u00e9charger</button>'
    + '<button class="histo-btn-sm histo-btn-danger" onclick="ragDeleteDoc('+doc.id+','+nomJs+')" title="Retirer ce document de la base de connaissance, action irr\u00e9versible">Supprimer</button>'
    + '</div></div>';
};

window.ragGroupBySujet = function(docs){
  var ORDRE = ['IA Act','RGPD','ISO 42001','ISO 27001','NIS2','DORA','Cybersecurite','Contrats','Audit','Autre'];
  var LIB = { 'Cybersecurite': 'Cybers\u00e9curit\u00e9' };
  var sel = document.getElementById('rag-sujet-select');
  var filtre = sel ? sel.value : '';
  var groupes = {};
  docs.forEach(function(doc){
    var s = doc.sujet || 'Autre';
    if(!groupes[s]) groupes[s] = [];
    groupes[s].push(doc);
  });
  var sujets = ORDRE.filter(function(s){ return groupes[s] && groupes[s].length; });
  Object.keys(groupes).forEach(function(s){ if(sujets.indexOf(s) === -1) sujets.push(s); });
  var opts = '<option value="">Tous les sujets (' + docs.length + ')</option>' + sujets.map(function(s){
    return '<option value="'+s+'"'+(filtre === s ? ' selected' : '')+'>'+(LIB[s]||s)+' ('+groupes[s].length+')</option>';
  }).join('');
  var barre = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">'
    + '<span style="font-size:11px;color:var(--muted)">Trier par sujet</span>'
    + '<select id="rag-sujet-select" onchange="window.ragApplyTri()" style="font-size:12px;padding:5px 8px;border:1px solid var(--rule2);border-radius:5px">'+opts+'</select></div>';
  var corps = sujets.filter(function(s){ return !filtre || s === filtre; }).map(function(s){
    return '<div style="margin:12px 0 4px 0;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--ink);border-bottom:1px solid var(--rule2);padding-bottom:3px">'
      + (LIB[s]||s) + ' <span style="color:var(--muted);font-weight:400">(' + groupes[s].length + ')</span></div>'
      + groupes[s].map(window.ragDocRow).join('');
  }).join('');
  return barre + corps;
};

window.ragApplyTri = function(){
  var holder = document.getElementById('rag-doc-list');
  if(holder) holder.innerHTML = window.ragGroupBySujet(window.__ragDocs || []);
};

/* Etat de la base : ce que la recherche sait faire, et si elle ne sait pas
   tout faire, POURQUOI. Sans cela, une base muette est indistinguable d une
   base en panne, et l on cherche du cote du serveur ce qui tient a un simple
   defaut d indexation. */
/* ══ REPRISE DE LA BASE DOCUMENTAIRE DE CONSEILPREVCYBER ══
   Le fichier de sauvegarde est lu DANS LE NAVIGATEUR, puis envoyé par lots.
   Une base de trois cents documents pèse plusieurs centaines de mégaoctets une
   fois encodée : une requête unique de cette taille échoue sans rien avoir
   fait, et sans dire où elle s'est arrêtée.

   Trois exigences que l'envoi par lots seul permet :
     — une progression réelle, document par document, et non une barre qui
       attend ;
     — l'interruption : on peut arrêter et reprendre, puisque le serveur saute
       ce qu'il a déjà reçu ;
     — un compte rendu par document — ce qui est passé, ce qui a été sauté, ce
       qui a été refusé et POURQUOI. Un transfert muet sur ses rejets ferait
       croire à une reprise complète. */
var IMP = { sauvegarde: null, arret: false, encours: false };

/* ══ DÉPÔT EN MASSE — un dossier entier, sous-dossiers compris ══
   Quand il n'y a pas de sauvegarde à reprendre — base d'origine perdue,
   documents qui n'ont jamais transité par une plateforme — on dépose les
   fichiers directement.

   Trois décisions qui font la différence à l'usage :
     — le TRI est fait ici, pas par l'utilisateur : le navigateur remet tout le
       contenu du dossier, y compris des .DS_Store et des fichiers verrouillés
       Office ; lui demander de faire le ménage avant serait lui faire faire le
       travail de la machine ;
     — le NOM DU SOUS-DOSSIER devient le thème. Un dossier « EDF » ou
       « IEC 62443 » porte déjà le classement : le ressaisir document par
       document serait absurde ;
     — les fichiers partent UN PAR UN, en série. En parallèle, dix fichiers de
       50 Mo arriveraient ensemble sur un serveur qui n'a pas la mémoire de les
       traiter ensemble — c'est exactement la panne qu'on vient de corriger. */
var DOS = { fichiers: [], arret: false, encours: false };

var DOS_EXT = ['pdf', 'docx', 'xlsx', 'xlsm', 'txt', 'md', 'csv', 'log', 'json', 'yaml', 'yml'];
/* Valeur de départ, remplacée par celle que le SERVEUR annonce dès que l'état
   de la base est chargé : deux limites écrites à deux endroits finissent
   toujours par diverger, et c'est l'utilisateur qui découvre l'écart. */
var DOS_MAX = 500 * 1024 * 1024;
/* Renseignée par le diagnostic : tant qu’elle vaut 0, on laisse le serveur
   trancher plutôt que de recopier une limite qui aurait divergé. */
var RAG_TAILLE_MAX = 0;

function dosExt(nom) {
  var m = String(nom || '').toLowerCase().match(/\.([a-z0-9]+)$/);
  return m ? m[1] : '';
}

/* Le thème est le dossier le plus PROCHE du fichier : dans
   « base/Normes/IEC 62443/doc.pdf », c'est « IEC 62443 » et non « base ».
   Le dossier racine est écarté — c'est le nom du répertoire choisi, pas un
   classement. */
function dosTheme(chemin) {
  var parts = String(chemin || '').split('/').filter(Boolean);
  parts.pop();                            /* le nom du fichier */
  if (parts.length <= 1) return '';       /* fichier à la racine : pas de thème */
  return parts[parts.length - 1];
}

window.dosChoisir = function (files) {
  var liste = Array.prototype.slice.call(files || []);
  if (!liste.length) return;
  var gardes = [], ecartes = [];
  liste.forEach(function (f) {
    var chemin = f.webkitRelativePath || f.name;
    var nom = f.name || '';
    if (nom.charAt(0) === '.' || nom.indexOf('~$') === 0) {
      ecartes.push({ nom: chemin, motif: 'fichier système ou verrouillé' });
      return;
    }
    var e = dosExt(nom);
    if (DOS_EXT.indexOf(e) === -1) {
      ecartes.push({ nom: chemin, motif: e ? ('format .' + e + ' non lu') : 'sans extension' });
      return;
    }
    if (f.size > DOS_MAX) {
      ecartes.push({ nom: chemin,
                     motif: Math.round(f.size / 1048576) + ' Mo — au-delà de la limite' });
      return;
    }
    if (!f.size) { ecartes.push({ nom: chemin, motif: 'fichier vide' }); return; }
    gardes.push({ f: f, chemin: chemin, theme: dosTheme(chemin) });
  });

  DOS.fichiers = gardes;
  DOS.ecartes = ecartes;

  var themes = {};
  gardes.forEach(function (g) { if (g.theme) themes[g.theme] = (themes[g.theme] || 0) + 1; });
  var poids = gardes.reduce(function (a, g) { return a + g.f.size; }, 0);

  document.getElementById('dos-inv').innerHTML =
    '<div style="border:1px solid var(--rule2);border-radius:8px;padding:14px 16px;background:var(--bg)">'
    + '<div style="font-size:13px;font-weight:600;margin-bottom:2px">'
    + gardes.length + ' fichier(s) à charger · ' + impPoids(poids) + '</div>'
    + (Object.keys(themes).length
        ? '<div style="margin-top:9px"><div style="font-family:var(--mono);font-size:9px;'
          + 'text-transform:uppercase;letter-spacing:.06em;color:var(--muted2);margin-bottom:5px">'
          + 'Thèmes déduits des dossiers (' + Object.keys(themes).length + ')</div>'
          + '<div style="display:flex;flex-wrap:wrap;gap:5px">'
          + Object.keys(themes).sort().map(function (t) {
              return '<span class="rag-page-chip">' + impEsc(t) + ' · ' + themes[t] + '</span>';
            }).join('') + '</div></div>'
        : '<div style="font-size:11px;color:var(--muted);margin-top:6px">Aucun sous-dossier : '
          + 'les documents seront classés en « général ».</div>')
    + (ecartes.length
        ? '<div style="margin-top:10px;font-size:11px;color:var(--muted);max-height:150px;'
          + 'overflow:auto"><b style="color:var(--accent)">' + ecartes.length
          + ' fichier(s) écarté(s) :</b>'
          + ecartes.slice(0, 60).map(function (r) {
              return '<div>· ' + impEsc(r.nom) + ' — ' + impEsc(r.motif) + '</div>';
            }).join('')
          + (ecartes.length > 60 ? '<div>…</div>' : '') + '</div>'
        : '')
    + '</div>';
  document.getElementById('dos-go').style.display = gardes.length ? '' : 'none';
  document.getElementById('dos-etat').innerHTML = '';
};

window.dosLancer = function () {
  if (DOS.encours || !DOS.fichiers.length) return;
  DOS.encours = true; DOS.arret = false;
  document.getElementById('dos-go').style.display = 'none';
  document.getElementById('dos-stop').style.display = '';

  var i = 0, verses = 0, refuses = [], aIndexer = [];
  var etat = document.getElementById('dos-etat');
  var total = DOS.fichiers.length;

  function afficher(fin, courant) {
    etat.innerHTML =
      '<div class="rag-progress-track"><div class="rag-progress-fill" style="width:'
      + Math.round(100 * Math.min(i, total) / total) + '%"></div></div>'
      + '<div style="font-size:11.5px;color:var(--ink2);margin-top:7px">'
      + (fin ? '<b>Chargement terminé.</b> ' : 'Chargement… ')
      + Math.min(i, total) + ' / ' + total + ' — <b>' + verses + '</b> versé(s)'
      + (refuses.length ? ', <span style="color:var(--accent)">' + refuses.length
          + ' refusé(s)</span>' : '')
      + (courant && !fin ? ' · ' + impEsc(courant) : '') + '</div>'
      + (refuses.length ? '<div style="margin-top:8px;font-size:11px;color:var(--muted);'
          + 'max-height:170px;overflow:auto">' + refuses.map(function (r) {
              return '<div>· <b>' + impEsc(r.nom) + '</b> — ' + impEsc(r.motif) + '</div>';
            }).join('') + '</div>' : '')
      + (fin && aIndexer.length ? '<div style="font-size:11.5px;color:var(--ink2);margin-top:8px">'
          + 'Indexation sémantique de ' + aIndexer.length + ' document(s) — laissez cet onglet '
          + 'ouvert.</div>' : '');
  }

  function suivant() {
    if (DOS.arret || i >= total) return fini();
    var g = DOS.fichiers[i];
    afficher(false, g.chemin);

    var fd = new FormData();
    fd.append('file', g.f, g.f.name);
    fd.append('pages_liees', 'general');
    if (g.theme) fd.append('theme', g.theme);

    var ctrl = new AbortController();
    var minuteur = setTimeout(function () { ctrl.abort(); }, 180000);

    fetch('/api/rag/upload', { method: 'POST', headers: window.ragHeaders(),
                               body: fd, signal: ctrl.signal })
      .then(function (r) { clearTimeout(minuteur); return window.ragLireReponse(r); })
      .then(function (rep) {
        var res = { s: rep.status, d: rep.data, json: rep.json, brut: rep.brut };
        if (window.ragHandleAuthError(res.s)) { DOS.arret = true; return fini(); }
        if (!res.json) {
          refuses.push({ nom: g.chemin, motif: window.ragCauseHttp(rep) });
          i++;
          return setTimeout(suivant, 400);
        }
        if (res.s === 201) {
          verses++;
          var doc = (res.d || {}).document || {};
          if ((res.d || {}).statut_indexation === 'en_cours' && doc.id) {
            aIndexer.push({ id: doc.id, nom: doc.nom_fichier, fragments: doc.nb_chunks });
          }
        } else {
          refuses.push({ nom: g.chemin, motif: (res.d || {}).error || ('refus ' + res.s) });
        }
        i++;
        /* En SÉRIE, et avec une respiration : dix envois simultanés de gros
           fichiers arriveraient ensemble sur un serveur qui n'a pas la mémoire
           de les traiter ensemble. */
        setTimeout(suivant, 120);
      })
      .catch(function (e) {
        clearTimeout(minuteur);
        refuses.push({ nom: g.chemin,
                       motif: e && e.name === 'AbortError' ? 'délai dépassé — fichier trop lourd ?'
                                                           : 'connexion interrompue, aucune réponse'
                                                             + (e && e.message ? ' (' + e.message + ')' : '') });
        i++;
        setTimeout(suivant, 400);
      });
  }

  function fini() {
    DOS.encours = false;
    document.getElementById('dos-stop').style.display = 'none';
    document.getElementById('dos-go').style.display = '';
    afficher(true);
    if (window.ragRenderList) window.ragRenderList();
    var n = 0;
    (function indexerSuivant() {
      if (n >= aIndexer.length) { afficher(true); return; }
      var doc = aIndexer[n++];
      window.ragPollIndexation(doc.id, doc.nom, doc.fragments);
      setTimeout(indexerSuivant, 1200);
    })();
  }

  afficher(false);
  suivant();
};


function impEsc(x) {
  return String(x == null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function impPoids(o) {
  if (o >= 1024 * 1024 * 1024) return (o / 1073741824).toFixed(1) + ' Go';
  if (o >= 1024 * 1024) return Math.round(o / 1048576) + ' Mo';
  return Math.max(1, Math.round(o / 1024)) + ' Ko';
}

/* Le début réel du fichier, rendu lisible. Les caractères de contrôle
   deviennent visibles : sans cela un fichier binaire s'afficherait comme une
   zone vide, et on n'aurait rien montré du tout. */
function impVisible(t, n) {
  var s = String(t == null ? '' : t);
  return impEsc(s.slice(0, n).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/g, '·'))
    + (s.length > n ? '…' : '');
}

/* Montrer plutôt qu'affirmer. Dire « ce fichier ne commence pas par son
   en-tête » à quelqu'un qui voit un fichier nommé conseilprevcyber-rag-….json
   ne lui apprend rien : le NOM vient bien du bouton, c'est le CONTENU qui
   vient d'ailleurs. Les quatre cents premiers caractères tranchent. */
function impApercuBloc(t, titre, depart) {
  var d = depart || 0;
  if (!t || d >= t.length) return '';
  return '<div style="margin-top:10px">'
    + '<div style="font-family:var(--mono);font-size:9px;text-transform:uppercase;'
    + 'letter-spacing:.06em;color:var(--muted2);margin-bottom:4px">'
    + impEsc(titre || 'Début réel du fichier') + '</div>'
    + '<div style="font-family:var(--mono);font-size:10.5px;color:var(--ink2);background:var(--bg2);'
    + 'border:1px solid var(--rule2);border-radius:6px;padding:8px 10px;white-space:pre-wrap;'
    + 'word-break:break-all;max-height:130px;overflow:auto">'
    + (d ? '…' : '') + impVisible(t.slice(d), 400) + '</div></div>';
}

function impSansBalises(h) {
  return String(h || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}

/* Le diagnostic ne sert a rien s'il reste dans l'ecran. Un bouton le met dans
   le presse-papiers en entier — apercu compris — parce que c'est justement
   l'apercu, le bloc decisif, qu'on oublie de recopier. */
function impBoutonCopie() {
  return '<button class="mat-export-btn" style="margin-top:10px" '
    + 'onclick="impCopierRapport(this)">Copier le diagnostic</button>';
}

/* Le rapport est dans la fermeture ; on l'expose pour qu'il soit verifiable
   seul — c'est le bloc que l'utilisateur doit pouvoir transmettre. */
window.impDernierRapport = function () { return IMP.rapport || ''; };

window.impCopierRapport = function (btn) {
  var txt = IMP.rapport || '';
  var fini = function (ok) { btn.textContent = ok ? 'Diagnostic copié' : 'Copie impossible'; };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(txt).then(function () { fini(true); },
                                           function () { impCopieSecours(txt, fini); });
  } else { impCopieSecours(txt, fini); }
};

function impCopieSecours(txt, fini) {
  var z = document.createElement('textarea');
  z.value = txt; z.style.position = 'fixed'; z.style.top = '-1000px'; z.style.opacity = '0';
  document.body.appendChild(z); z.focus(); z.select();
  var ok = false;
  try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
  z.remove();
  fini(ok);
}

function impRefus(inv, s, apercu, nom) {
  IMP.sauvegarde = null;
  document.getElementById('imp-go').style.display = 'none';
  IMP.rapport = 'Sentinel — diagnostic de sauvegarde\n'
    + 'fichier : ' + (nom || '(inconnu)') + '\n'
    + 'message : ' + impSansBalises(s.titre + ' ' + (s.cause || '') + ' ' + (s.faire || '')) + '\n'
    + '--- début réel du fichier ---\n' + String(apercu || '').slice(0, 400) + '\n';
  inv.innerHTML = '<div class="reg-empty" style="color:var(--accent);text-align:left">'
    + '<b>' + s.titre + '</b>'
    + (s.cause ? '<div style="margin-top:6px;color:var(--ink2);font-size:12px">' + s.cause + '</div>' : '')
    + (s.faire ? '<div style="margin-top:6px;color:var(--ink2);font-size:12px">' + s.faire + '</div>' : '')
    + impApercuBloc(apercu) + impBoutonCopie() + '</div>';
}

var IMP_REFAIRE = 'Rouvrez <b>/admin/base-connaissance</b>, vérifiez que la liste des documents '
                + 's’affiche — donc que la session est bien ouverte — puis relancez '
                + '<b>💾 Sauvegarder</b>.';

/* Ce que disent les premiers octets. Rend null si le fichier peut être du
   JSON, sinon ce qu'il est RÉELLEMENT — et on le sait avant d'avoir chargé
   le reste : lire cent cinquante mégaoctets pour n'apprendre que ce que huit
   octets disaient coûterait une minute et autant de mémoire au navigateur. */
function impSignature(octets, tete) {
  var n = octets.length, i = 0;
  if (n >= 3 && octets[0] === 0xEF && octets[1] === 0xBB && octets[2] === 0xBF) i = 3;
  while (i < n && (octets[i] === 32 || octets[i] === 9 || octets[i] === 10 || octets[i] === 13)) i++;
  if (i >= n) return { titre: 'Ce fichier ne contient que des espaces.',
    cause: 'La sauvegarde n’a rien écrit.', faire: IMP_REFAIRE };

  if (octets[0] === 0x1F && octets[1] === 0x8B)
    return { titre: 'Ce fichier est une archive compressée (gzip), pas une sauvegarde.',
      cause: 'Le navigateur a enregistré la réponse sans la décompresser.',
      faire: 'Décompressez-le, ou retéléchargez-le par le bouton <b>💾 Sauvegarder</b> '
           + 'plutôt qu’en ouvrant l’adresse à la main.' };
  if (octets[0] === 0x50 && octets[1] === 0x4B)
    return { titre: 'Ce fichier est une archive ZIP, pas une sauvegarde.', cause: '',
      faire: 'La sauvegarde attendue est un <code>.json</code> non compressé.' };
  if (tete.slice(0, 5) === '%PDF-')
    return { titre: 'Ce fichier est un PDF, pas une sauvegarde.', cause: '',
      faire: 'La sauvegarde attendue est un <code>.json</code>.' };

  if (octets[i] === 0x7B || octets[i] === 0x5B) return null;      /* { ou [ — c'est du JSON */

  if (octets[i] === 0x3C) {                                      /* < — HTML ou XML */
    var titre = (tete.match(/<title[^>]*>([^<]{0,120})/i) || [])[1] || '';
    return { titre: 'Ce fichier est une page web (HTML)'
        + (titre ? ' : « ' + impEsc(titre.replace(/\s+/g, ' ').trim()) + ' »' : '')
        + ', pas une sauvegarde.',
      cause: 'Le navigateur a enregistré une page sous le nom du fichier attendu : page '
           + 'd’erreur pendant un redémarrage de conseilprevcyber, ou écran de connexion '
           + 'parce que la session d’administration avait expiré. Le nom commence donc bien '
           + 'par « conseilprevcyber » — c’est le contenu qui n’en est pas une.',
      faire: IMP_REFAIRE };
  }
  return { titre: 'Ce fichier n’est pas du JSON.',
    cause: 'Il ne commence ni par une accolade ni par un crochet.',
    faire: 'Vérifiez que c’est bien le fichier produit par le bouton <b>💾 Sauvegarder</b> '
         + 'de /admin/base-connaissance.' };
}

/* Du JSON, mais pas une sauvegarde. Le cas le plus fréquent est une réponse
   d'erreur enregistrée telle quelle : « Authentification requise » tient dans
   quarante octets et porte, lui aussi, le nom du fichier attendu. */
function impFormeInattendue(obj, apercu, inv, nom) {
  var err = obj && !Array.isArray(obj) && (obj.error || obj.message);
  if (err) {
    impRefus(inv, { titre: 'conseilprevcyber a répondu par une erreur, pas par une sauvegarde : '
        + '« ' + impEsc(String(err).slice(0, 160)) + ' »',
      cause: 'C’est cette réponse-là qui a été enregistrée dans le fichier. Presque toujours : '
           + 'la session d’administration avait expiré au moment du téléchargement.',
      faire: 'Reconnectez-vous sur conseilprevcyber, puis ' + IMP_REFAIRE.charAt(0).toLowerCase()
           + IMP_REFAIRE.slice(1) }, apercu, nom);
    return;
  }
  var cles = Array.isArray(obj) ? [] : Object.keys(obj || {}).slice(0, 8);
  impRefus(inv, { titre: 'Ce fichier est bien du JSON, mais ce n’est pas une sauvegarde '
      + 'conseilprevcyber.',
    cause: 'Une sauvegarde est un objet portant une liste <code>documents</code>.'
         + (Array.isArray(obj) ? ' Celui-ci est une liste.'
            : cles.length ? ' Celui-ci porte : <code>' + impEsc(cles.join(', ')) + '</code>.' : ''),
    faire: 'Vérifiez que c’est bien le fichier produit par le bouton <b>💾 Sauvegarder</b> '
         + 'de /admin/base-connaissance.' }, apercu, nom);
}

window.impChoisir = function (files) {
  if (!files || !files.length) return;
  var f = files[0];
  var inv = document.getElementById('imp-inv');
  IMP.sauvegarde = null;
  document.getElementById('imp-go').style.display = 'none';

  if (!f.size) {
    impRefus(inv, { titre: 'Ce fichier est vide (0 octet).',
      cause: 'Le téléchargement n’a rien rapporté.', faire: IMP_REFAIRE }, '', f.name);
    return;
  }
  inv.innerHTML = '<div class="reg-loading">Lecture de ' + impEsc(f.name) + ' ('
    + impPoids(f.size) + ')…</div>';

  /* On renifle d'abord les premiers octets, on charge le reste ensuite. */
  var tete = new FileReader();
  tete.onerror = function () {
    inv.innerHTML = '<div class="reg-empty" style="color:var(--accent)">Le fichier n’a pas pu '
      + 'être lu.</div>';
  };
  tete.onload = function () {
    var octets = new Uint8Array(tete.result), debut = '';
    try { debut = new TextDecoder('utf-8').decode(octets); }
    catch (e) { for (var k = 0; k < octets.length; k++) debut += String.fromCharCode(octets[k]); }
    var s = impSignature(octets, debut);
    if (s) { impRefus(inv, s, debut, f.name); return; }
    if (f.size > window.IMP_SEUIL_FLUX) { impProposerFlux(f, inv); return; }
    impLireTout(f, inv, debut);
  };
  tete.readAsArrayBuffer(f.slice(0, 4096));
};

function impLireTout(f, inv, debut) {
  var fr = new FileReader();
  fr.onerror = function () {
    inv.innerHTML = '<div class="reg-empty" style="color:var(--accent)">Le fichier n’a pas pu '
      + 'être lu en entier' + (f.size > 400 * 1024 * 1024
        ? ' : ' + impPoids(f.size) + ' dépassent ce qu’un navigateur tient en mémoire.' : '.')
      + '</div>';
  };
  fr.onload = function () {
    var obj;
    try { obj = JSON.parse(fr.result); }
    catch (e) {
      /* « JSON invalide » ne dit rien d'exploitable. Dans les faits, c'est
         presque toujours un fichier TRONQUÉ : le téléchargement s'est
         interrompu, ou le serveur d'origine a manqué de mémoire en le
         fabriquant. On le diagnostique, et surtout on RÉCUPÈRE les documents
         complets — un téléchargement coupé aux trois quarts contient les trois
         quarts des documents, il serait absurde de tout jeter. */
      impDiagnostiquer(fr.result, e, inv, f);
      return;
    }
    if (!obj || typeof obj !== 'object' || !Array.isArray(obj.documents)) {
      impFormeInattendue(obj, debut, inv, f.name);
      return;
    }
    IMP.sauvegarde = obj;
    /* L'inventaire est demandé AU SERVEUR : c'est lui qui classera, et on veut
       voir son classement avant de transférer, pas celui du navigateur. */
    fetch('/api/rag/import-inventaire', {
      method: 'POST',
      headers: Object.assign({ 'Content-Type': 'application/json' }, window.ragHeaders()),
      body: JSON.stringify({ app: obj.app, count: obj.count, created_at: obj.created_at,
                             documents: (obj.documents || []).map(function (d) {
                               /* On n'envoie PAS le contenu pour l'inventaire : seul le
                                  classement compte, et transmettre 300 Mo pour compter
                                  des thèmes serait absurde. Un contenu minimal suffit à
                                  passer le contrôle de forme. */
                               return { title: d.title, filename: d.filename, theme: d.theme,
                                        visibility: d.visibility, content_b64: 'AA==' };
                             }) })
    }).then(function (r) { return r.json().then(function (d) { return { s: r.status, d: d }; }); })
      .then(function (res) {
        if (window.ragHandleAuthError(res.s)) return;
        if (!res.d.ok) {
          inv.innerHTML = '<div class="reg-empty" style="color:var(--accent)">'
            + impEsc(res.d.error || 'Sauvegarde illisible.') + '</div>';
          return;
        }
        impRendreInventaire(res.d.inventaire, f.name);
        document.getElementById('imp-go').style.display = '';
      })
      .catch(function () {
        inv.innerHTML = '<div class="reg-empty" style="color:var(--accent)">Le serveur n’a pas '
          + 'répondu.</div>';
      });
  };
  fr.readAsText(f);
}

/* Extrait les objets JSON COMPLETS du tableau « documents » d'une sauvegarde
   tronquée. Le balayage tient compte des chaînes et des échappements : un
   accolade à l'intérieur d'un titre ne doit pas être prise pour une frontière
   d'objet, sans quoi on découperait au mauvais endroit et tout serait perdu. */
window.impRecuperer = function (texte) {
  var depart = texte.indexOf('"documents"');
  if (depart < 0) return [];
  var crochet = texte.indexOf('[', depart);
  if (crochet < 0) return [];
  var docs = [], i = crochet + 1, n = texte.length;
  while (i < n) {
    while (i < n && (texte[i] === ',' || texte[i] === ' ' || texte[i] === '\n'
                     || texte[i] === '\r' || texte[i] === '\t')) i++;
    if (i >= n || texte[i] !== '{') break;
    var debut = i, profondeur = 0, chaine = false, echap = false;
    for (; i < n; i++) {
      var c = texte[i];
      if (echap) { echap = false; continue; }
      if (c === '\\') { echap = true; continue; }
      if (c === '"') { chaine = !chaine; continue; }
      if (chaine) continue;
      if (c === '{') profondeur++;
      else if (c === '}') {
        profondeur--;
        if (profondeur === 0) { i++; break; }
      }
    }
    if (profondeur !== 0) break;          /* dernier objet coupé : on l'écarte */
    try { docs.push(JSON.parse(texte.slice(debut, i))); }
    catch (e) { break; }
  }
  return docs;
};

function impDiagnostiquer(texte, err, inv, f) {
  var t = String(texte || '');
  var ouvre = /^[\uFEFF\s]*\{/.test(t);
  var liste = /^[\uFEFF\s]*\[/.test(t);
  /* La marque de fabrique, ou à défaut la liste elle-même : une sauvegarde
     dont le tout début manque garde ses documents, et c'est eux qui comptent. */
  var signe = t.indexOf('conseilprevcyber-rag') >= 0 || t.indexOf('"documents"') >= 0;
  var finOk = /\}\s*$/.test(t.slice(-40));
  var pos = (String(err && err.message || '').match(/position (\d+)/) || [])[1];
  /* La récupération est tentée QUOI QU'IL ARRIVE : ce qu'on cherche est un
     document entier, pas un en-tête conforme. */
  var recuperes = window.impRecuperer(t);

  var motif;
  if (!t.length) {
    motif = '<b>Le fichier n’a produit aucun texte à la lecture.</b> Il occupe pourtant '
          + impPoids(f ? f.size : 0) + ' sur le disque. Au-delà d’environ 512 Mo, un navigateur '
          + 'ne peut plus faire une chaîne de caractères d’un fichier : il en rend une vide, sans '
          + 'erreur — <b>le fichier est bon, c’est la lecture qui ne l’était pas</b>. Rechargez '
          + 'la page et redéposez-le : il sera lu par tranches.';
  } else if (liste) {
    motif = '<b>Ce fichier est une liste JSON, pas une sauvegarde.</b> Une sauvegarde '
          + 'conseilprevcyber est un <i>objet</i> portant une liste <code>documents</code>.';
  } else if (!ouvre) {
    motif = '<b>Ce fichier ne commence pas par un objet JSON.</b> Une sauvegarde '
          + 'conseilprevcyber commence par <code>{"version":1,"app":"conseilprevcyber-rag"</code>. '
          + 'Comparez avec le début réel affiché ci-dessous.';
  } else if (!signe) {
    motif = '<b>Ce fichier est bien du JSON, mais il ne porte nulle part la marque d’une '
          + 'sauvegarde conseilprevcyber</b> — ni <code>conseilprevcyber-rag</code>, ni une '
          + 'liste <code>documents</code>. Le nom du fichier peut très bien commencer par '
          + '« conseilprevcyber » sans que son contenu en vienne : comparez avec le '
          + 'début réel affiché ci-dessous, puis retéléchargez par le '
          + 'bouton <b>💾 Sauvegarder</b> de /admin/base-connaissance.';
  } else if (!finOk) {
    motif = '<b>Le fichier est incomplet.</b> Il commence bien comme une sauvegarde '
          + 'conseilprevcyber mais se termine au milieu : le téléchargement s’est '
          + 'interrompu, ou le serveur d’origine a manqué de mémoire en le fabriquant. '
          + '<b>Redéployez conseilprevcyber</b> (le correctif de mémoire y est poussé) '
          + 'puis retéléchargez la sauvegarde.';
  } else {
    motif = 'Le fichier est complet en apparence mais son contenu est mal formé'
          + (pos ? ' (première anomalie au caractère ' + pos + ')' : '') + '.';
  }

  /* Les octets du DISQUE et les caracteres LUS sont deux nombres differents,
     et leur ecart est parlant : un fichier de deux cents megaoctets dont on ne
     lit que quelques milliers de caracteres n'est pas du texte. */
  var technique = 'fichier : ' + (f ? f.size.toLocaleString('fr-FR') + ' octets' : 'taille inconnue')
    + ' · texte lu : ' + t.length.toLocaleString('fr-FR') + ' caractères'
    + ' · en-tête : ' + (ouvre && signe ? 'reconnu' : 'non reconnu')
    + ' · fin : ' + (finOk ? 'complète' : 'coupée')
    + (pos ? ' · anomalie au caractère ' + Number(pos).toLocaleString('fr-FR') : '');

  /* Sur un fichier de cent cinquante megaoctets, les quatre cents premiers
     caracteres sont presque toujours irreprochables : c'est AUTOUR DE
     L'ANOMALIE qu'il faut regarder. */
  var fenetre = (pos && +pos > 400) ? Math.max(0, +pos - 120) : 0;

  IMP.rapport = 'Sentinel — diagnostic de sauvegarde\n'
    + 'fichier : ' + (f ? f.name : '(inconnu)') + '\n'
    + technique + '\n'
    + 'message : ' + impSansBalises(motif) + '\n'
    + 'documents récupérables : ' + recuperes.length + '\n'
    + '--- début réel du fichier ---\n' + t.slice(0, 400) + '\n'
    + (fenetre ? '--- autour du caractère ' + pos + ' ---\n' + t.slice(fenetre, fenetre + 400) + '\n'
               : '');

  inv.innerHTML =
    '<div class="reg-empty" style="color:var(--accent);text-align:left">' + motif
    + '<div style="margin-top:8px;font-family:var(--mono);font-size:10.5px;color:var(--muted)">'
    + technique + '</div>'
    + (recuperes.length
        ? '<div style="margin-top:10px;color:var(--ink2);font-size:12px">'
          + '<b>' + recuperes.length + ' document(s) entier(s)</b> sont malgré tout lisibles '
          + 'dans ce fichier. Vous pouvez les transférer maintenant et refaire une '
          + 'sauvegarde complète ensuite : un document déjà transféré sera sauté.'
          + '<br><button class="mat-export-btn" style="margin-top:8px" '
          + 'onclick="impRecuperationLancer()">Transférer les ' + recuperes.length
          + ' document(s) lisibles</button></div>'
        : '')
    + impApercuBloc(t)
    + (fenetre ? impApercuBloc(t, 'Autour du caractère ' + pos, fenetre) : '')
    + impBoutonCopie()
    + '</div>';

  /* La sauvegarde partielle est gardée telle quelle : l'utilisateur décide. */
  IMP.sauvegarde = recuperes.length
    ? { app: 'conseilprevcyber-rag', version: 1, count: recuperes.length, documents: recuperes }
    : null;
  document.getElementById('imp-go').style.display = 'none';
}

window.impRecuperationLancer = function () {
  if (!IMP.sauvegarde) return;
  impRendreInventaire({ documents: (IMP.sauvegarde.documents || []).length, rejets: 0,
                        octets: 0, themes: {}, familles: {}, entreprises: {} },
                      'documents récupérés');
  window.impLancer();
};

/* ─────────────────────────────────────────────────────────────────────────
   QUAND LE FICHIER NE TIENT PAS EN MÉMOIRE

   Un navigateur ne peut pas faire une chaîne de caractères d’un fichier de
   651 Mo : la limite de V8 est d’environ 512 Mo de caractères, et readAsText
   rend alors une chaîne VIDE sans rien signaler — ni erreur, ni exception. Le
   fichier était parfaitement bon ; c’est la façon de le lire qui ne l’était
   pas, et le diagnostic accusait le fichier.

   On le lit donc par tranches, on en extrait les documents un par un, et on
   les verse au fur et à mesure. La mémoire occupée ne dépasse jamais une
   tranche plus le document en cours — la même leçon que côté serveur, où
   l’ingestion avait dû cesser de dépendre de la taille du fichier.
   ───────────────────────────────────────────────────────────────────────── */
window.IMP_SEUIL_FLUX = 64 * 1024 * 1024;   /* au-delà : lecture par tranches */
var IMP_TRANCHE = 4 * 1024 * 1024;

/* Extrait les documents d’un flux de texte remis morceau par morceau. Le
   balayage tient compte des chaînes et des échappements : une accolade dans
   un titre ne doit pas être prise pour une frontière d’objet. */
function impScanner(surDocument) {
  var buf = '', dansTableau = false, termine = false, i = 0;
  var enObjet = false, debut = 0, profondeur = 0, chaine = false, echap = false;

  function balayer() {
    while (i < buf.length) {
      if (!enObjet) {
        var ch = buf.charAt(i);
        if (ch === ',' || ch === ' ' || ch === '\n' || ch === '\r' || ch === '\t') { i++; continue; }
        if (ch !== '{') { termine = true; return; }        /* ] : fin du tableau */
        enObjet = true; debut = i; profondeur = 0; chaine = false; echap = false;
      }
      var complet = false;
      for (; i < buf.length; i++) {
        var c = buf.charAt(i);
        if (echap) { echap = false; continue; }
        if (c === '\\') { echap = true; continue; }
        if (c === '"') { chaine = !chaine; continue; }
        if (chaine) continue;
        if (c === '{') profondeur++;
        else if (c === '}') { profondeur--; if (profondeur === 0) { i++; complet = true; break; } }
      }
      if (!complet) return;                    /* objet à cheval : on attend la suite */
      try { surDocument(JSON.parse(buf.slice(debut, i))); }
      catch (e) { /* objet illisible : on le passe plutôt que tout perdre */ }
      enObjet = false;
    }
  }

  return {
    pousser: function (bout) {
      if (termine) return;
      buf += bout;
      if (!dansTableau) {
        var d = buf.indexOf('"documents"');
        if (d < 0) {
          /* Tant que la clé n’est pas trouvée, on ne garde qu’une queue :
             sinon le tampon grandirait avec le fichier, ce qu’on refuse. */
          if (buf.length > 65536) buf = buf.slice(-32);
          return;
        }
        var c = buf.indexOf('[', d);
        if (c < 0) return;
        buf = buf.slice(c + 1); i = 0; dansTableau = true;
      }
      balayer();
      /* UNE seule compaction par tranche : recopier le tampon après chaque
         document le ferait des dizaines de fois par tranche. */
      var coupe = enObjet ? debut : i;
      if (coupe > 0) { buf = buf.slice(coupe); i -= coupe; if (enObjet) debut = 0; }
    },
    fini: function () { return termine; }
  };
}

/* Lit le fichier par tranches et rend la main entre chaque : le versement
   d’un lot doit pouvoir s’intercaler, sinon tout le fichier serait lu avant
   le premier envoi et on n’aurait rien gagné. */
function impLireParTranches(f, surTexte, surFin, surErreur) {
  var decodeur = new TextDecoder('utf-8');
  var pos = 0;
  (function suivant() {
    if (pos >= f.size) return surFin();
    var fin = Math.min(pos + IMP_TRANCHE, f.size);
    var fr = new FileReader();
    fr.onerror = function () { surErreur(fr.error); };
    fr.onload = function () {
      /* stream:true : un caractère accentué coupé en deux par la frontière de
         tranche serait sinon rendu « ￼ », et un titre deviendrait faux. */
      var txt = decodeur.decode(new Uint8Array(fr.result), { stream: fin < f.size });
      pos = fin;
      surTexte(txt, pos, suivant);
    };
    fr.readAsArrayBuffer(f.slice(pos, fin));
  })();
}

/* Poids d'un envoi, en base64. Cinq documents « moyens » font une dizaine de
   megaoctets ; cinq gros en font cent cinquante, que le serveur doit tenir
   ENTIEREMENT en memoire (JSON parse + decodage base64). C'est le poids qui
   fait tomber un envoi, pas le nombre — on compose donc les lots au poids. */
var IMP_POIDS_LOT = 3 * 1024 * 1024;
var IMP_LOT_MAX = 5;

function impPoidsDoc(d) { return (d && d.content_b64 ? d.content_b64.length : 0); }

function impPrelever(attente) {
  var lot = [], poids = 0;
  while (attente.length) {
    var p = impPoidsDoc(attente[0]);
    if (lot.length && (lot.length >= IMP_LOT_MAX || poids + p > IMP_POIDS_LOT)) break;
    lot.push(attente.shift());
    poids += p;
    if (poids >= IMP_POIDS_LOT) break;        /* un gros document part seul */
  }
  return lot;
}

/* Un lot qui echoue EN BLOC emporte avec lui des documents parfaitement
   valides. On les repasse alors UN PAR UN : le refus ne coute plus que le
   document qui le merite. C'est la difference entre perdre cinq documents et
   en perdre un. */
function impEnvoyerAvecRepli(tranche, suite) {
  impEnvoyerLot(tranche, function (r) {
    if (r.stop || !r.echecLot || tranche.length < 2) return suite(r);
    var i = 0, cumul = { verses: 0, sautes: 0, refuses: [], aIndexer: [], stop: false };
    (function suivant() {
      if (i >= tranche.length) return suite(cumul);
      impEnvoyerLot([tranche[i++]], function (u) {
        cumul.verses += u.verses; cumul.sautes += u.sautes;
        cumul.refuses = cumul.refuses.concat(u.refuses);
        cumul.aIndexer = cumul.aIndexer.concat(u.aIndexer);
        if (u.stop) { cumul.stop = true; return suite(cumul); }
        setTimeout(suivant, 60);
      });
    })();
  });
}

function impEnvoyerLot(tranche, suite) {
  var r = { verses: 0, sautes: 0, refuses: [], aIndexer: [], stop: false, echecLot: false };
  /* Un echec de lot vaut pour CHACUN de ses documents : une seule ligne pour
     cinq documents perdus rendait le compte faux — « 66 refuses » pour 330
     documents disparus, et une soustraction qui ne tombait pas juste. */
  var parDoc = function (motif) {
    return tranche.map(function (x) {
      return { nom: (x || {}).filename || '?', motif: motif };
    });
  };
  fetch('/api/rag/import-lot', {
    method: 'POST',
    headers: Object.assign({ 'Content-Type': 'application/json' }, window.ragHeaders()),
    body: JSON.stringify({ origine: 'conseilprevcyber', documents: tranche })
  }).then(function (rep) { return window.ragLireReponse(rep); })
    .then(function (rep) {
      if (window.ragHandleAuthError(rep.status)) { r.stop = true; return suite(r); }
      var d = rep.data || {};
      if (rep.json && d.ok) {
        r.verses = (d.compte || {}).verses || 0;
        r.sautes = (d.compte || {}).sautes || 0;
        r.refuses = d.refuses || [];
        (d.verses || []).forEach(function (v) { if (v.a_indexer) r.aIndexer.push(v); });
      } else {
        r.echecLot = true;
        r.refuses = parDoc(rep.json ? (d.error || 'refusé par le serveur')
                                    : window.ragCauseHttp(rep));
      }
      suite(r);
    })
    .catch(function () {
      r.echecLot = true;
      r.refuses = parDoc('connexion interrompue — relancez pour reprendre');
      suite(r);
    });
}

window.impScanner = impScanner;
window.impLireParTranches = impLireParTranches;

function impProposerFlux(f, inv) {
  IMP.fichier = f;
  IMP.sauvegarde = null;
  document.getElementById('imp-go').style.display = 'none';
  inv.innerHTML =
    '<div style="border:1px solid var(--rule2);border-radius:8px;padding:14px 16px;background:var(--bg)">'
    + '<div style="font-size:13px;font-weight:600;margin-bottom:3px">' + impEsc(f.name) + '</div>'
    + '<div style="font-size:11.5px;color:var(--muted);line-height:1.6">'
    + '<b>' + impPoids(f.size) + '</b> — trop volumineux pour être ouvert d’un seul tenant. '
    + 'Au-delà d’environ 512 Mo, un navigateur ne peut plus faire une chaîne de caractères d’un '
    + 'fichier : il en rend une <b>vide</b>, sans erreur. Ce fichier sera donc <b>lu par tranches '
    + 'et transféré au fil de l’eau</b> — la mémoire occupée ne dépasse jamais quelques '
    + 'mégaoctets.'
    + '<br>L’inventaire préalable n’est pas possible dans ce mode : les thèmes s’affichent au fur '
    + 'et à mesure. <b>Le transfert reste rejouable</b> — un document déjà présent est sauté, et '
    + 'vous pouvez l’interrompre puis le reprendre.'
    + '</div>'
    + '<button class="mat-export-btn" style="margin-top:10px" onclick="impFluxLancer()">'
    + 'Transférer au fil de l’eau</button></div>';
}

window.impFluxLancer = function () {
  var f = IMP.fichier;
  if (!f || IMP.encours) return;
  IMP.encours = true; IMP.arret = false;
  document.getElementById('imp-go').style.display = 'none';
  document.getElementById('imp-stop').style.display = '';
  var etat = document.getElementById('imp-etat');

  var attente = [], poidsAttente = 0;
  var lus = 0, verses = 0, sautes = 0, refuses = [], aIndexer = [];
  var octetsLus = 0, themes = {};

  function afficher(fin) {
    var pct = f.size ? Math.round(100 * octetsLus / f.size) : 0;
    var cles = Object.keys(themes).sort(function (a, b) { return themes[b] - themes[a]; });
    /* Le compte doit TOMBER JUSTE : trouvés = versés + déjà présents + refusés
       (+ ce qui reste en file). Sans ce reliquat affiché, une soustraction qui
       ne tombe pas juste laisse croire que des documents se sont volatilisés. */
    var restant = lus - verses - sautes - refuses.length;

    /* Tout le detail, pas les soixante premieres lignes : c'est la liste des
       refus qui dit quoi corriger, et elle doit pouvoir etre transmise. */
    IMP.rapport = 'Sentinel — compte rendu de transfert\n'
      + 'fichier : ' + f.name + ' (' + f.size.toLocaleString('fr-FR') + ' octets)\n'
      + lus + ' document(s) trouvé(s) · ' + verses + ' versé(s) · ' + sautes
      + ' déjà présent(s) · ' + refuses.length + ' refusé(s)'
      + (restant > 0 ? ' · ' + restant + ' non traité(s)' : '') + '\n'
      + (refuses.length ? '\n--- documents refusés ---\n'
          + refuses.map(function (x) { return x.nom + ' — ' + x.motif; }).join('\n') + '\n' : '');

    etat.innerHTML =
      '<div class="rag-progress-track"><div class="rag-progress-fill" style="width:' + pct
      + '%"></div></div>'
      + '<div style="font-size:11.5px;color:var(--ink2);margin-top:7px">'
      + (fin ? '<b>Transfert terminé.</b> ' : 'Lecture au fil de l’eau… ')
      + impPoids(octetsLus) + ' / ' + impPoids(f.size) + ' · ' + lus + ' document(s) trouvé(s) = <b>'
      + verses + '</b> versé(s) + ' + sautes + ' déjà présent(s)'
      + (refuses.length ? ' + <span style="color:var(--accent)">' + refuses.length
          + ' refusé(s)</span>' : '')
      + (restant > 0 ? ' + ' + restant + ' en attente' : '')
      + '</div>'
      + (cles.length ? '<div style="margin-top:9px;display:flex;flex-wrap:wrap;gap:5px">'
          + cles.slice(0, 40).map(function (k) {
              return '<span class="rag-page-chip">' + impEsc(k) + ' · ' + themes[k] + '</span>';
            }).join('') + '</div>' : '')
      + (refuses.length ? '<div style="margin-top:8px;font-size:11px;color:var(--muted);'
          + 'max-height:200px;overflow:auto">' + refuses.slice(0, 200).map(function (x) {
              return '<div>· <b>' + impEsc(x.nom) + '</b> — ' + impEsc(x.motif) + '</div>';
            }).join('')
          + (refuses.length > 200 ? '<div style="margin-top:4px">… et '
              + (refuses.length - 200) + ' autre(s) — tous dans le compte rendu copiable.</div>'
              : '')
          + '</div>' : '')
      + (fin && refuses.length ? impBoutonCopie() : '')
      + (fin && aIndexer.length ? '<div style="font-size:11.5px;color:var(--ink2);margin-top:8px">'
          + 'Indexation sémantique de ' + aIndexer.length + ' document(s) en cours — '
          + 'laissez cet onglet ouvert.</div>' : '');
  }

  var scan = impScanner(function (d) {
    attente.push(d); lus++; poidsAttente += impPoidsDoc(d);
    var th = d && d.theme;
    if (th) themes[th] = (themes[th] || 0) + 1;
  });

  /* Vide la file par lots, en série : dix envois simultanés de plusieurs
     mégaoctets arriveraient ensemble sur un serveur qui n’a pas la mémoire de
     les traiter ensemble. */
  function viderLots(force, suite) {
    if (IMP.arret) return suite();
    if (!attente.length) return suite();
    if (!force && attente.length < IMP_LOT_MAX && poidsAttente < IMP_POIDS_LOT) return suite();
    var tranche = impPrelever(attente);
    tranche.forEach(function (d) { poidsAttente -= impPoidsDoc(d); });
    impEnvoyerAvecRepli(tranche, function (r) {
      verses += r.verses; sautes += r.sautes;
      refuses = refuses.concat(r.refuses);
      aIndexer = aIndexer.concat(r.aIndexer);
      afficher(false);
      if (r.stop) { IMP.arret = true; return suite(); }
      setTimeout(function () { viderLots(force, suite); }, 60);
    });
  }

  function fini() {
    IMP.encours = false;
    document.getElementById('imp-stop').style.display = 'none';
    document.getElementById('imp-go').style.display = 'none';
    afficher(true);
    if (window.ragRenderList) window.ragRenderList();
    var n = 0;
    (function suivant() {
      if (n >= aIndexer.length) { afficher(true); return; }
      var doc = aIndexer[n++];
      window.ragPollIndexation(doc.id, doc.nom, doc.fragments);
      setTimeout(suivant, 1200);
    })();
  }

  afficher(false);
  impLireParTranches(f,
    function (txt, position, continuer) {
      if (IMP.arret) return fini();
      octetsLus = position;
      scan.pousser(txt);
      afficher(false);
      viderLots(false, continuer);
    },
    function () { viderLots(true, fini); },
    function (err) {
      refuses.push({ nom: f.name,
                     motif: 'lecture interrompue' + (err && err.name ? ' (' + err.name + ')' : '') });
      viderLots(true, fini);
    });
};

function impRendreInventaire(iv, nom) {
  var liste = function (o, titre) {
    var cles = Object.keys(o || {});
    if (!cles.length) return '';
    return '<div style="margin-top:10px"><div style="font-family:var(--mono);font-size:9px;'
      + 'text-transform:uppercase;letter-spacing:.06em;color:var(--muted2);margin-bottom:5px">'
      + impEsc(titre) + ' (' + cles.length + ')</div><div style="display:flex;flex-wrap:wrap;'
      + 'gap:5px">' + cles.map(function (k) {
        return '<span class="rag-page-chip">' + impEsc(k) + ' · ' + o[k] + '</span>';
      }).join('') + '</div></div>';
  };
  document.getElementById('imp-inv').innerHTML =
    '<div style="border:1px solid var(--rule2);border-radius:8px;padding:14px 16px;background:var(--bg)">'
    + '<div style="font-size:13px;font-weight:600;margin-bottom:2px">' + impEsc(nom) + '</div>'
    + '<div style="font-size:11.5px;color:var(--muted)"><b>' + iv.documents + ' document(s)</b> · '
    + impPoids(iv.octets || 0)
    + (iv.rejets ? ' · <span style="color:var(--accent)">' + iv.rejets
        + ' inexploitable(s), ils seront signalés</span>' : '')
    + '</div>'
    + liste(iv.entreprises, 'Entreprises et références')
    + liste(iv.familles, 'Familles')
    + liste(iv.themes, 'Thèmes')
    + '</div>';
}

window.impLancer = function () {
  if (IMP.encours || !IMP.sauvegarde) return;
  var docs = IMP.sauvegarde.documents || [];
  if (!docs.length) return;
  IMP.encours = true; IMP.arret = false;
  document.getElementById('imp-go').style.display = 'none';
  document.getElementById('imp-stop').style.display = '';

  var i = 0, verses = 0, sautes = 0, refuses = [], aIndexer = [];
  var etat = document.getElementById('imp-etat');

  function afficher(fin) {
    etat.innerHTML =
      '<div class="rag-progress-track"><div class="rag-progress-fill" style="width:'
      + Math.round(100 * Math.min(i, docs.length) / docs.length) + '%"></div></div>'
      + '<div style="font-size:11.5px;color:var(--ink2);margin-top:7px">'
      + (fin ? '<b>Transfert terminé.</b> ' : 'Transfert en cours… ')
      + Math.min(i, docs.length) + ' / ' + docs.length + ' = <b>' + verses + '</b> versé(s) + '
      + sautes + ' déjà présent(s)'
      + (refuses.length ? ' + <span style="color:var(--accent)">' + refuses.length
          + ' refusé(s)</span>' : '')
      + '</div>'
      + (refuses.length ? '<div style="margin-top:8px;font-size:11px;color:var(--muted);'
          + 'max-height:170px;overflow:auto">' + refuses.map(function (r) {
              return '<div>· <b>' + impEsc(r.nom) + '</b> — ' + impEsc(r.motif) + '</div>';
            }).join('') + '</div>' : '')
      + (fin && aIndexer.length ? '<div style="font-size:11.5px;color:var(--ink2);margin-top:8px">'
          + 'Indexation sémantique de ' + aIndexer.length + ' document(s) en cours — '
          + 'laissez cet onglet ouvert.</div>' : '');
  }

  function lot() {
    if (IMP.arret || i >= docs.length) return fini();
    /* Meme mecanique que le flux : composition au poids, repli document par
       document si le lot echoue en bloc, et comptage EN DOCUMENTS. */
    var file = docs.slice(i, i + IMP_LOT_MAX);
    var tranche = impPrelever(file);
    impEnvoyerAvecRepli(tranche, function (r) {
      verses += r.verses; sautes += r.sautes;
      refuses = refuses.concat(r.refuses);
      aIndexer = aIndexer.concat(r.aIndexer);
      i += tranche.length;
      afficher(false);
      if (r.stop) { IMP.arret = true; return fini(); }
      setTimeout(lot, 60);            /* laisser respirer le serveur entre deux lots */
    });
  }

  function fini() {
    IMP.encours = false;
    document.getElementById('imp-stop').style.display = 'none';
    document.getElementById('imp-go').style.display = '';
    afficher(true);
    if (window.ragRenderList) window.ragRenderList();
    /* L'indexation sémantique se poursuit document par document, avec la même
       mécanique « pull » que l'import manuel : aucun thread serveur. */
    var n = 0;
    (function suivant() {
      if (n >= aIndexer.length) { afficher(true); return; }
      var doc = aIndexer[n++];
      window.ragPollIndexation(doc.id, doc.nom, doc.fragments);
      setTimeout(suivant, 1200);
    })();
  }

  afficher(false);
  lot();
};

function _ragEsc(x){ return String(x == null ? '' : x)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

window.ragRenderDiag = function(){
  var el = document.getElementById('rag-diag');
  if(!el) return;
  fetch('/api/rag/diagnostic', { headers: window.ragHeaders() })
    .then(function(r){ return r.ok ? r.json() : Promise.reject(r.status); })
    .then(function(d){
      var e = d.etat || {};
      var lis = (d.constats || []).map(function(c){
        return '<li class="n-' + c.niveau + '">' + _ragEsc(c.texte) + '</li>';
      }).join('');
      var fmts = Object.keys(d.formats || {}).filter(function(k){ return d.formats[k]; });
      el.innerHTML =
        '<div class="rag-diag-head"><span class="rag-diag-mode m-' + _ragEsc(d.mode || '') + '">'
        + _ragEsc(d.mode || '\u2014') + '</span>'
        + '<span class="rag-diag-lib">' + _ragEsc(d.mode_libelle || '') + '</span></div>'
        + '<ul>' + lis + '</ul>'
        + '<div class="rag-diag-chiffres">'
        + '<span>' + (e.documents || 0) + ' document(s)</span>'
        + '<span>' + (e.fragments || 0) + ' fragment(s)</span>'
        + '<span>' + (e.fragments_vectorises || 0) + ' vectoris\u00e9(s)</span>'
        + '<span>' + (d.taille_max_mo || 0) + ' Mo max</span>'
        + '<span>' + fmts.sort().join(' \u00b7 ') + '</span></div>';
      /* La limite de taille du dépôt en masse suit celle du serveur. */
      if(d.taille_max_mo && typeof DOS_MAX !== 'undefined'){
        DOS_MAX = d.taille_max_mo * 1024 * 1024;
        RAG_TAILLE_MAX = DOS_MAX;
      }
      el.style.display = 'block';
    })
    .catch(function(){ el.style.display = 'none'; });
};

window.ragRenderList = function(){
  var holder = document.getElementById('rag-doc-list');
  if(!holder) return;
  holder.innerHTML = '<div class="reg-loading">Chargement de vos documents\u2026</div>';
  window.ragRenderDiag();

  var filterEl = document.getElementById('rag-filter-select');
  var pageFilter = filterEl ? filterEl.value : '';
  var url = '/api/rag/documents' + (pageFilter ? '?page='+encodeURIComponent(pageFilter) : '');

  fetch(url, { headers: window.ragHeaders() }).then(function(r){
    if(window.ragHandleAuthError(r.status)){ holder.innerHTML=''; return Promise.reject('auth'); }
    return r.json();
  }).then(function(d){
    var docs = d.documents || [];
    if(docs.length === 0){
      holder.innerHTML = '<div class="reg-empty">Aucun document dans la base de connaissance. Importez un fichier ci-dessus pour commencer.</div>';
      return;
    }
    window.__ragDocs = docs;
    holder.innerHTML = window.ragGroupBySujet(docs);
  }).catch(function(){
    holder.innerHTML = '<div class="reg-empty" style="color:var(--accent)">Erreur de chargement.</div>';
  });
};

/* Fonction reutilisable par les autres pages (Audit, FRIA, Registre) pour enrichir leur contexte IA */
window.ragSearchContext = function(query, page, topK, perimetre){
  return fetch('/api/rag/search', {
    method: 'POST', headers: {'Content-Type':'application/json'},
    body: JSON.stringify({ query: query, page: page||'', top_k: topK||3,
                           perimetre: perimetre||'' })
  }).then(function(r){ return r.json(); }).catch(function(){ return {resultats:[]}; });
};

/* Les perimetres de redaction, charges UNE fois et gardes. Ils viennent du
   serveur plutot que d'une liste recopiee ici : deux vocabulaires finiraient
   par diverger, et l'ecran proposerait un perimetre que la recherche ignore. */
window.__ragPerimetres = null;
window.ragPerimetres = function(){
  if(window.__ragPerimetres) return Promise.resolve(window.__ragPerimetres);
  return fetch('/api/rag/perimetres', { credentials:'same-origin' })
    .then(function(r){ return r.json(); })
    .then(function(d){ window.__ragPerimetres = (d && d.perimetres) || []; return window.__ragPerimetres; })
    .catch(function(){ window.__ragPerimetres = []; return []; });
};

var _ragOrigGo = window.go;
window.go = function(id){
  var r = _ragOrigGo ? _ragOrigGo.apply(this, arguments) : undefined;
  if(id === "rag") setTimeout(window.ragRenderList, 80);
  return r;
};

})();



