window.roadmapOpenPhaseModal = function(phaseIndex){
  var p = window.MAT_PHASES[phaseIndex];
  var modal = document.getElementById("roadmap-modal");
  if(!modal){ modal = document.createElement("div"); modal.id = "roadmap-modal"; modal.className = "mat-modal"; document.body.appendChild(modal); }

  modal.innerHTML = '<div class="mat-modal-box mat-modal-wide">'
    + '<div class="mat-modal-head"><div><div class="mat-modal-eyebrow">Plan d action · Phase ' + p.n + '</div>'
    + '<div class="mat-modal-title">' + p.title + '</div></div>'
    + '<button class="mat-modal-close" onclick="document.getElementById(\'roadmap-modal\').classList.remove(\'on\')" title="Fermer cette fenêtre">×</button></div>'
    + '<div class="mat-modal-body">'
    + '<p style="font-size:12px;color:var(--muted);margin-bottom:16px">Génère un livrable détaillé et actionnable pour cette phase, basé sur vos données réelles (Registre IA, Audit) et votre secteur d activité.</p>'
    + '<div class="mat-api-row" style="margin-bottom:16px">'
    + '<button class="mat-api-btn on" id="roadmap-api-mistral" onclick="roadmapSetApi(\'mistral\')" title="Utiliser Mistral Large pour generer ce livrable.">Mistral</button>'
    + '<button class="mat-api-btn" id="roadmap-api-claude" onclick="roadmapSetApi(\'claude\')" title="Utiliser Claude Sonnet pour generer ce livrable.">Claude</button>'
    + '</div>'
    + '<button class="mat-export-btn" style="background:var(--ink);color:#fff;width:100%" onclick="roadmapGenerateDeliv(' + phaseIndex + ')">🤖 Générer le livrable détaillé</button>'
    + '<div id="roadmap-modal-body" style="margin-top:16px"></div>'
    + '</div>'
    + '<div class="mat-modal-foot" id="roadmap-modal-foot" style="display:none">'
    + '<button class="mat-export-btn" style="background:#1C5A8A;color:#fff" onclick="roadmapSaveToHisto(' + phaseIndex + ')">💾 Enregistrer dans l’historique</button>'
    + '</div></div>';
  modal.classList.add("on");
  window.__roadmapCurrentDeliv = { phaseIndex: phaseIndex, content: null, apiName: null };
};

window.roadmapSetApi = function(api){
  ROADMAP_DELIV_API = api;
  document.getElementById("roadmap-api-mistral").classList.toggle("on", api === "mistral");
  document.getElementById("roadmap-api-claude").classList.toggle("on", api === "claude");
};

window.roadmapGenerateDeliv = function(phaseIndex){
  var bodyEl = document.getElementById("roadmap-modal-body");
  var footEl = document.getElementById("roadmap-modal-foot");
  if(bodyEl) bodyEl.innerHTML = '<div class="reg-loading">Génération du livrable en cours…</div>';
  if(footEl) footEl.style.display = "none";

  cpGetDashboardData(function(d){
    var prompt = roadmapBuildPrompt(phaseIndex, d);
    window.matCallAIBridge(prompt, ROADMAP_DELIV_API, function(err, text, apiName){
      if(err || !text){
        if(bodyEl) bodyEl.innerHTML = '<div style="padding:20px;text-align:center;color:var(--accent)">Erreur de génération. Réessayez ou contactez christophe.cerf@outlook.com</div>';
        return;
      }
      window.__roadmapCurrentDeliv.content = text;
      window.__roadmapCurrentDeliv.apiName = apiName;
      if(bodyEl) bodyEl.innerHTML = '<div class="mat-deliv-content">' + window.matMdToHtmlBridge(text) + '</div>';
      if(footEl) footEl.style.display = "flex";
    }, "maturite");
  });
};

window.roadmapSaveToHisto = function(phaseIndex){
  var cur = window.__roadmapCurrentDeliv;
  if(!cur || !cur.content){ alert("Générez d abord le livrable."); return; }
  var p = window.MAT_PHASES[phaseIndex];
  window.histoSave('maturite', 'Livrable Roadmap — Phase ' + p.n,
    { phase: p.n, titre: p.title, api: cur.apiName },
    { extrait: cur.content.substring(0, 500) },
    'Roadmap — Phase ' + p.n + ' : ' + p.title
  ).then(function(r){
    if(r && r.calcul) alert('✅ Livrable enregistré dans l historique (#' + r.calcul.id + ').');
    else alert('Erreur lors de l enregistrement.');
  });
};

