window.sentinelCheckout = function(plan){
  var _ov = document.createElement('div');
  _ov.id = 'checkout-overlay';
  _ov.style.cssText = 'position:fixed;inset:0;z-index:10002;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.45)';
  _ov.innerHTML = '<div style="background:var(--white,#fff);color:var(--ink,#111);padding:22px 30px;border-radius:12px;font-size:14px;font-weight:600">Ouverture du paiement sécurisé\u2026</div>';
  document.body.appendChild(_ov);
  function _fin(){ if(_ov && _ov.parentNode) _ov.parentNode.removeChild(_ov); }
  fetch('/api/sentinel/checkout', {method:'POST', credentials:'same-origin', headers:{'Content-Type':'application/json'}, body:JSON.stringify({plan:plan})})
    .then(function(r){ return r.json().then(function(j){ return j; }).catch(function(){ return {}; }); })
    .then(function(j){ if(j && j.url){ window.location.href = j.url; } else { _fin(); window.location.href = '/tarifications'; } })
    .catch(function(){ _fin(); window.location.href = '/tarifications'; });
};
window.sentinelActivationToast = function(){
  try{
    if(new URLSearchParams(location.search).get('activation') === 'ok'){
      var t = document.createElement('div');
      t.style.cssText = 'position:fixed;top:18px;left:50%;transform:translateX(-50%);z-index:10001;background:var(--green,#0E7C7B);color:#fff;padding:12px 22px;border-radius:10px;font-size:13px;font-weight:600;box-shadow:0 8px 30px rgba(0,0,0,.25)';
      t.textContent = '\u2713 Votre offre est activée. Bienvenue !';
      document.body.appendChild(t);
      setTimeout(function(){ if(t.parentNode) t.parentNode.removeChild(t); }, 6000);
    }
  }catch(e){}
};
if(document.readyState === 'complete'){ window.sentinelActivationToast(); } else { window.addEventListener('load', window.sentinelActivationToast); }

var _planOrigGo = window.go;
window.go = function(id){
  if(window.__IS_CONSEILPREV) return _planOrigGo ? _planOrigGo.apply(this, arguments) : undefined;
  var plan = window.__SENTINEL_PLAN;
  if((plan === 'gratuit' || plan === 'pro') && !planIsAllowed(id)){
    sentinelLockPrompt();
    return;
  }
  return _planOrigGo ? _planOrigGo.apply(this, arguments) : undefined;
};


/* ═══ PILOTAGE JALONS RAAS — Agent Sentinel Pricing Orchestrator ═══ */
window.raasAdminClients = [];

window.raasAdminPopulate = function(){
  var sel = document.getElementById('raas-client-select');
  if(!sel) return;
  fetch('/api/admin/clients', {credentials:'same-origin'})
    .then(function(r){ return r.json(); })
    .then(function(d){
      var list = d.clients || d || [];
      window.raasAdminClients = list;
      sel.innerHTML = '<option value="">— Sélectionner un client —</option>' + list.map(function(c){
        return '<option value="'+c.id+'">'+(c.nom_entreprise||('Client #'+c.id))+' ('+(c.plan||'gratuit')+')</option>';
      }).join('');
    })
    .catch(function(){ sel.innerHTML = '<option value="">Erreur de chargement</option>'; });
};

window.raasAdminLoad = function(){
  var sel = document.getElementById('raas-client-select');
  var out = document.getElementById('raas-admin-table');
  var msg = document.getElementById('raas-admin-msg');
  if(!sel || !out) return;
  if(!sel.value){ out.innerHTML=''; var _sp0=document.getElementById('client-sub-panel'); if(_sp0) _sp0.innerHTML=''; return; }
  if(window.clientSubLoad) clientSubLoad(sel.value);
  if(msg) msg.textContent = '';
  out.innerHTML = '<div style="padding:14px;color:var(--muted)">Chargement…</div>';
  fetch('/api/raas/milestones?client_id='+encodeURIComponent(sel.value), {credentials:'same-origin'})
    .then(function(r){ return r.json(); })
    .then(function(d){
      if(!d.ok){ out.innerHTML = '<div style="padding:14px;color:var(--accent)">'+(d.error||'Erreur')+'</div>'; return; }
      if(!d.milestones.length){
        out.innerHTML = '<div style="padding:14px;color:var(--muted2)">Aucun jalon initialisé pour ce client. Renseignez le SaaS mensuel de référence puis cliquez sur « Initialiser l’échéancier ».</div>';
        return;
      }
      function eur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
      var stLbl = {pending:'⏳ En attente', verified:'✅ Vérifié', invoiced:'Facturé'};
      var rows = '';
      function __fwOf(id){ id=String(id); if(id.indexOf('rgpd_')===0) return 'RGPD'; if(id.indexOf('iso_')===0) return 'ISO 42001'; return 'IA Act'; }
      function __fwOrder(f){ return f==='IA Act'?0:(f==='RGPD'?1:2); }
      function __fwColor(f){ return f==='RGPD'?'#6B46C1':(f==='ISO 42001'?'#0E7C7B':'var(--ink)'); }
      var __msList = d.milestones.slice().sort(function(a,b){ return __fwOrder(__fwOf(a.milestone_id))-__fwOrder(__fwOf(b.milestone_id)); });
      var __lastFw = null, __env = {}, __ver = {};
      __msList.forEach(function(m){ var f=__fwOf(m.milestone_id); __env[f]=(__env[f]||0)+(m.amount_eur||0); if(m.status==='verified'||m.status==='invoiced') __ver[f]=(__ver[f]||0)+(m.amount_eur||0); });
      __msList.forEach(function(m){
        var __fw = __fwOf(m.milestone_id);
        if(__fw!==__lastFw){ rows += '<tr><td colspan="6" style="background:'+__fwColor(__fw)+';color:#fff;font-weight:700;font-size:11px;padding:7px 10px">Cadre '+__fw+' \u2014 enveloppe '+eur(__env[__fw]||0)+' \u00b7 acquis '+eur(__ver[__fw]||0)+'</td></tr>'; __lastFw=__fw; }
        var canVerify = (m.status === 'pending');
        rows += '<tr>'
          + '<td>'+m.label+'</td>'
          + '<td><span class="ms-badge-art">'+(m.art||'')+'</span></td>'
          + '<td><span class="ms-badge-seuil">score \u2265 '+m.threshold+'</span></td>'
          + '<td class="ms-amount">'+eur(m.amount_eur)+'</td>'
          + '<td>'+(stLbl[m.status]||m.status)
          + (m.verified_at ? '<div style="font-size:9px;color:var(--muted2)">'+String(m.verified_at).substring(0,10)+' · score '+(m.score_at_verification||'—')+'</div>' : '')
          + (m.evidence ? '<div style="font-size:9px;color:var(--muted2);font-style:italic">Preuve\u00a0: '+String(m.evidence).replace(/</g,'&lt;')+'</div>' : '')
          + '</td>'
          + '<td>'+(canVerify
            ? '<button class="mat-export-btn" style="padding:4px 10px;font-size:10px" onclick="raasAdminVerify(\''+m.milestone_id+'\','+m.threshold+')">Vérifier</button>'
            : '<span style="font-size:10px;color:var(--muted2)">'+(m.status==='invoiced'?'Échelonné 2 mens.':'Acquis — irrévocable')+'</span>')+'</td>'
          + '</tr>';
      });
      /* Memoriser les donnees du client pour la generation de facture et de contrat */
      var clientName = '';
      var opt = sel.options[sel.selectedIndex];
      if(opt) clientName = opt.textContent.replace(/\s*\([^)]*\)\s*$/, '').trim();
      window.__raasCurrentClient = {id: sel.value, name: clientName, data: d};
      if(window.raasExpertRender) window.raasExpertRender(sel.value);
      var invoiced = d.milestones.filter(function(m){ return m.status === 'invoiced'; });
      var verified = d.milestones.filter(function(m){ return m.status === 'verified'; });
      out.innerHTML =
        '<div style="display:flex;gap:16px;margin-bottom:10px;font-size:12px">'
        + '<div>Enveloppe totale\u00a0: <strong>'+eur(d.envelope_total)+'</strong></div>'
        + '<div>Vérifié/facturé\u00a0: <strong style="color:var(--green)">'+eur(d.verified_total)+'</strong></div>'
        + '</div>'
        + '<table class="ms-table"><thead><tr>'
        + '<th>Jalon</th><th>Réf.</th><th>Seuil</th><th>Montant</th><th>Statut</th><th>Action</th>'
        + '</tr></thead><tbody>'+rows+'</tbody></table>'
        + '<div class="raas-doc-actions" style="display:flex;gap:10px;flex-wrap:wrap;margin-top:14px;padding-top:14px;border-top:1px solid var(--rule)">'
        + '<button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="raasAdminContract()" title="Genere le contrat RaaS PDF recapitulant l echeancier de ce client">Générer le contrat RaaS (PDF)</button>'
        + '<button class="mat-export-btn"'+(invoiced.length?'':' disabled style="opacity:.5;cursor:default"')+' onclick="raasAdminInvoice()" title="Genere la facture PDF des jalons factures">Générer la facture ('+invoiced.length+' jalon'+(invoiced.length>1?'s':'')+' facturé'+(invoiced.length>1?'s':'')+')</button>'
        + (verified.length?'<span style="font-size:11px;color:var(--muted2);align-self:center">'+verified.length+' jalon(s) vérifié(s) en attente de facturation</span>':'')
        + '</div>';
    })
    .catch(function(){ out.innerHTML = '<div style="padding:14px;color:var(--accent)">Erreur réseau.</div>'; });
};

window.raasAdminInit = function(framework){
  var fw = (framework === 'rgpd') ? 'rgpd' : ((framework === 'iso42001') ? 'iso42001' : 'ai_act');
  var sel = document.getElementById('raas-client-select');
  var saas = parseFloat((document.getElementById('raas-saas-monthly')||{value:'350'}).value||'350');
  var msg = document.getElementById('raas-admin-msg');
  if(!sel || !sel.value){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Sélectionnez d’abord un client.'; } return; }
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Initialisation…'; }
  fetch('/api/raas/milestones/init', {
    method:'POST', credentials:'same-origin',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({client_id: parseInt(sel.value,10), saas_monthly: saas, framework: fw})
  }).then(function(r){ return r.json(); }).then(function(d){
    if(msg){
      msg.style.color = d.ok ? 'var(--green)' : 'var(--accent)';
      msg.textContent = d.ok
        ? (d.created+' jalon(s) créé(s) — enveloppe '+((d.envelope||0).toLocaleString('fr-FR'))+'\u202f\u20ac (60\u00a0% du SaaS annuel). Les jalons existants n’ont pas été modifiés.')
        : (d.error||'Erreur');
    }
    raasAdminLoad();
  }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur réseau.'; } });
};

window.raasAdminVerify = function(milestoneId, threshold){
  var __isRgpd = String(milestoneId).indexOf('rgpd_')===0;
  var __isIso = String(milestoneId).indexOf('iso_')===0;
  var sel = document.getElementById('raas-client-select');
  var msg = document.getElementById('raas-admin-msg');
  if(!sel || !sel.value) return;
  var score = prompt(__isIso ? 'Couverture ISO/IEC 42001 constat\u00e9e pour ce client (0\u2013100, seuil requis\u00a0: '+threshold+')\u00a0:' : (__isRgpd ? 'Indice de conformit\u00e9 RGPD constat\u00e9 pour ce client (0\u2013100, seuil requis\u00a0: '+threshold+')\u00a0:' : 'Score Sentinel constat\u00e9 pour ce jalon (seuil requis\u00a0: '+threshold+')\u00a0:'));
  if(score === null) return;
  var evidence = prompt('Évidence documentaire (obligatoire — référence du document, lien, constat)\u00a0:');
  if(evidence === null) return;
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Vérification…'; }
  fetch('/api/raas/milestones/verify', {
    method:'POST', credentials:'same-origin',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({client_id: parseInt(sel.value,10), milestone_id: milestoneId,
                          score: parseFloat(score), evidence: evidence})
  }).then(function(r){ return r.json(); }).then(function(d){
    if(msg){
      msg.style.color = d.ok ? 'var(--green)' : 'var(--accent)';
      msg.textContent = d.ok
        ? ('Jalon vérifié — '+((d.amount_eur||0).toLocaleString('fr-FR'))+'\u202f\u20ac acquis définitivement (irrévocable).')
        : (d.error||'Erreur');
    }
    raasAdminLoad();
  }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur réseau.'; } });
};

window.raasAdminBill = function(){
  var sel = document.getElementById('raas-client-select');
  var msg = document.getElementById('raas-admin-msg');
  if(!sel || !sel.value){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Sélectionnez d’abord un client.'; } return; }
  if(!confirm('Facturer tous les jalons vérifiés de ce client\u00a0? Chaque jalon sera échelonné sur 2 mensualités (montants figés).')) return;
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Cycle de facturation…'; }
  fetch('/api/raas/billing-cycle', {
    method:'POST', credentials:'same-origin',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({client_id: parseInt(sel.value,10)})
  }).then(function(r){ return r.json(); }).then(function(d){
    if(msg){
      msg.style.color = d.ok ? 'var(--green)' : 'var(--accent)';
      if(d.ok && d.invoiced_count > 0){
        var det = (d.schedule||[]).map(function(s){ return s.label+' ('+s.installments.join('\u202f\u20ac + ')+'\u202f\u20ac)'; }).join(' · ');
        msg.textContent = d.invoiced_count+' jalon(s) facturé(s) — total '+((d.total_eur||0).toLocaleString('fr-FR'))+'\u202f\u20ac — '+det;
      } else if(d.ok){
        msg.textContent = 'Aucun jalon vérifié en attente de facturation.';
      } else {
        msg.textContent = d.error||'Erreur';
      }
    }
    raasAdminLoad();
  }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur réseau.'; } });
};

/* ── Generation du CONTRAT RaaS (PDF) pour le client selectionne ── */
window.raasAdminContract = function(){
  var cur = window.__raasCurrentClient;
  if(!cur || !cur.data){ alert('Sélectionnez un client et chargez son échéancier.'); return; }
  var d = cur.data;
  var k = cur.kyc || {};
  function eur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
  /* Coordonnees client depuis la fiche KYC, avec repli sur le nom courant */
  function esc(s){ return s?String(s).replace(/</g,'&lt;').replace(/>/g,'&gt;'):''; }
  var cliNom = esc(k.raison_sociale) || cur.name;
  var cliLignes = '<strong>'+cliNom+'</strong>';
  if(k.forme_juridique) cliLignes += ' ('+esc(k.forme_juridique)+')';
  if(k.siren) cliLignes += '<br>SIREN\u00a0: '+esc(k.siren);
  if(k.tva_intra) cliLignes += '<br>TVA\u00a0: '+esc(k.tva_intra);
  if(k.adresse) cliLignes += '<br>'+esc(k.adresse);
  if(k.code_postal || k.ville) cliLignes += '<br>'+esc(k.code_postal||'')+' '+esc(k.ville||'');
  if(k.pays && k.pays!=='France') cliLignes += '<br>'+esc(k.pays);
  if(k.representant) cliLignes += '<br>Repr\u00e9sentant\u00a0: '+esc(k.representant)+(k.fonction_representant?' ('+esc(k.fonction_representant)+')':'');
  if(k.email_contact) cliLignes += '<br>'+esc(k.email_contact);
  if(k.telephone) cliLignes += '<br>'+esc(k.telephone);
  cliLignes += '<br>R\u00e9f. client\u00a0: '+cur.id;
  var today = new Date().toLocaleDateString('fr-FR');
  var ref = 'RAAS-'+cur.id+'-'+(new Date().getFullYear());
  var rows = d.milestones.map(function(m){
    return '<tr><td>'+m.label+'</td><td>'+(m.art||'')+'</td><td style="text-align:center">score \u2265 '+m.threshold+'</td>'
      + '<td style="text-align:right"><strong>'+eur(m.amount_eur)+'</strong></td></tr>';
  }).join('');
  var html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Contrat RaaS \u2014 '+cur.name+'</title>'
    + '<style>@page{margin:2cm}body{font-family:Georgia,serif;color:#1C1C1C;max-width:860px;margin:0 auto;padding:20px;line-height:1.6}'
    + 'h1{font-size:21px;border-bottom:3px solid #B83222;padding-bottom:10px;margin-bottom:4px}'
    + 'h2{font-size:14px;color:#B83222;margin-top:22px}'
    + '.sub{color:#666;font-size:11px;font-family:Arial;margin-bottom:16px}'
    + '.parties{display:flex;gap:24px;font-size:12px;font-family:Arial;margin:14px 0}'
    + '.parties div{flex:1;background:#faf9f7;border:1px solid #eee;border-radius:6px;padding:12px}'
    + 'table{width:100%;border-collapse:collapse;font-size:11.5px;margin:10px 0}'
    + 'th{background:#1C1C1C;color:#fff;padding:7px 9px;text-align:left;font-size:10px;font-family:Arial}'
    + 'td{border:1px solid #ddd;padding:7px 9px}'
    + '.tot td{border-top:2px solid #1C1C1C;font-weight:bold;background:#f4f2ee}'
    + '.clause{font-size:11.5px;line-height:1.7;margin:5px 0}'
    + '.sign{display:flex;gap:40px;margin-top:40px;font-size:12px;font-family:Arial}'
    + '.sign div{flex:1;border-top:1px solid #999;padding-top:8px}'
    + '.foot{font-size:9.5px;color:#999;margin-top:30px;font-family:Arial;font-style:italic;border-top:1px solid #eee;padding-top:10px}'
    + '</style></head><body>'
    + '<h1>Contrat de tarification RaaS par jalons</h1>'
    + '<div class="sub">R\u00e9f\u00e9rence '+ref+' \u00b7 \u00c9tabli le '+today+' \u00b7 CONSEILPREV \u2014 Sentinel AI \u00b7 R\u00e8glement (UE) 2024/1689</div>'
    + '<div class="parties">'
    + '<div><strong>Prestataire</strong><br>CONSEILPREV \u2014 SARL au capital de 8\u202f000\u202f\u20ac<br>Christophe CERF, g\u00e9rant<br>19 rue Auguste Chabri\u00e8res, 75015 Paris<br>SIREN 494\u202f530\u202f157 \u2014 RCS Paris<br>TVA\u202f: FR\u202f24\u202f494\u202f530\u202f157<br>christophe.cerf@outlook.com</div>'
    + '<div><strong>Client</strong><br>'+cliLignes+'</div>'
    + '</div>'
    + '<h2>Article 1 \u2014 Objet</h2>'
    + '<div class="clause">Le pr\u00e9sent contrat d\u00e9finit les modalit\u00e9s de la tarification RaaS (Results as a Service) par laquelle le Client r\u00e9mun\u00e8re le Prestataire selon l\u2019atteinte v\u00e9rifi\u00e9e de jalons de conformit\u00e9 \u00e0 l\u2019AI Act, et non selon un forfait fixe.</div>'
    + '<h2>Article 2 \u2014 \u00c9ch\u00e9ancier des jalons</h2>'
    + '<table><thead><tr><th>Jalon de conformit\u00e9</th><th>R\u00e9f\u00e9rence</th><th>Seuil Sentinel</th><th>Montant</th></tr></thead>'
    + '<tbody>'+rows
    + '<tr class="tot"><td colspan="3">Enveloppe r\u00e9sultats totale (HT)</td><td style="text-align:right">'+eur(d.envelope_total)+'</td></tr>'
    + '</tbody></table>'
    + '<h2>Article 3 \u2014 Conditions de facturation</h2>'
    + '<div class="clause">Chaque jalon n\u2019est factur\u00e9 qu\u2019apr\u00e8s double v\u00e9rification\u00a0: atteinte du score Sentinel du domaine <em>et</em> validation documentaire par CONSEILPREV. Un jalon v\u00e9rifi\u00e9 est acquis d\u00e9finitivement et irr\u00e9vocable. Le paiement de chaque jalon est \u00e9chelonn\u00e9 sur deux mensualit\u00e9s \u00e9gales.</div>'
    + '<h2>Article 4 \u2014 Garanties</h2>'
    + '<div class="clause">Le total per\u00e7u au titre des jalons ne peut exc\u00e9der l\u2019enveloppe contractuelle ci-dessus. En cas de progression partielle, seuls les jalons atteints sont dus\u00a0: le risque d\u2019ex\u00e9cution est port\u00e9 par le Prestataire.</div>'    + '<h2>Article 5 \u2014 Conditions de paiement</h2>'    + '<div class="clause">Chaque jalon factur\u00e9 est payable \u00e0 r\u00e9ception de la facture, selon l\u2019\u00e9ch\u00e9ancier \u00e9chelonn\u00e9 sur deux mensualit\u00e9s \u00e9gales. Conform\u00e9ment aux articles L.441-10 et D.441-5 du Code de commerce, tout retard de paiement entra\u00eene des p\u00e9nalit\u00e9s au taux de trois fois le taux d\u2019int\u00e9r\u00eat l\u00e9gal et une indemnit\u00e9 forfaitaire de recouvrement de 40\u202f\u20ac. Les montants sont exprim\u00e9s hors taxes\u00a0; la TVA au taux de 20\u202f% (n\u00b0 FR\u202f24\u202f494\u202f530\u202f157) s\u2019ajoute aux sommes factur\u00e9es.</div>'    + '<h2>Article 6 \u2014 Prise d\u2019effet et dur\u00e9e</h2>'    + '<div class="clause">Le pr\u00e9sent contrat prend effet \u00e0 sa date de signature par les deux parties et demeure en vigueur jusqu\u2019\u00e0 l\u2019atteinte de l\u2019attestation finale de conformit\u00e9 ou la r\u00e9siliation dans les conditions du droit commun. Il est conclu conform\u00e9ment aux articles 1103 et 1104 du Code civil, qui conf\u00e8rent force obligatoire aux conventions l\u00e9galement form\u00e9es et imposent leur ex\u00e9cution de bonne foi.</div>'    + '<h2>Article 7 \u2014 Droit applicable et juridiction</h2>'    + '<div class="clause">Le pr\u00e9sent contrat est soumis au droit fran\u00e7ais. \u00c0 d\u00e9faut de r\u00e9solution amiable, tout litige relatif \u00e0 sa formation, son ex\u00e9cution ou son interpr\u00e9tation rel\u00e8ve de la comp\u00e9tence du Tribunal de commerce de Paris.</div>'
    + '<h2>Article 8 \u2014 Protection des donn\u00e9es personnelles (RGPD)</h2>'
    + '<div class="clause">CONSEILPREV, SARL au capital de 8\u202f000\u202f\u20ac, SIREN 494\u202f530\u202f157, agit en qualit\u00e9 de <strong>responsable de traitement</strong> au sens du R\u00e8glement (UE) 2016/679 (RGPD) pour les donn\u00e9es collect\u00e9es dans le cadre du pr\u00e9sent contrat. <strong>Finalit\u00e9\u00a0:</strong> gestion contractuelle, facturation et suivi de la relation client. <strong>Base l\u00e9gale\u00a0:</strong> ex\u00e9cution du contrat (art. 6.1.b) et obligations l\u00e9gales comptables et fiscales (art. 6.1.c). <strong>Conservation\u00a0:</strong> pendant la relation contractuelle, puis 3 ans \u00e0 des fins de prospection\u00a0; les pi\u00e8ces comptables sont conserv\u00e9es 10 ans (art. L.123-22 du Code de commerce). <strong>Droits\u00a0:</strong> le Client dispose des droits d\u2019acc\u00e8s, de rectification, d\u2019effacement, de limitation et d\u2019opposition (art. 15 \u00e0 21 RGPD), exer\u00e7ables aupr\u00e8s du d\u00e9l\u00e9gu\u00e9 \u00e0 la protection des donn\u00e9es (DPO) de CONSEILPREV\u00a0: christophe.cerf@outlook.com. Une r\u00e9clamation peut \u00eatre introduite aupr\u00e8s de la CNIL.</div>'
    + '<div class="sign"><div>Pour CONSEILPREV<br><br><br>Christophe CERF</div><div>Pour '+cliNom+'<br><br><br>'+(k.representant?esc(k.representant)+(k.fonction_representant?', '+esc(k.fonction_representant):''):'Nom, fonction, signature')+'</div></div>'
    + '<div class="foot">Document contractuel g\u00e9n\u00e9r\u00e9 par Sentinel AI. Les seuils et montants sont ceux de l\u2019\u00e9ch\u00e9ancier en vigueur \u00e0 la date d\u2019\u00e9tablissement. CONSEILPREV \u2014 Christophe CERF \u2014 christophe.cerf@outlook.com</div>'
    + '</body></html>';
  var w = window.open('', '_blank');
  if(!w){ alert('Autorisez les pop-ups pour générer le contrat.'); return; }
  w.document.write(html + '<scr'+'ipt>window.onload=function(){window.print();}<'+'/scr'+'ipt>');
  w.document.close();
};

/* ── Generation de la FACTURE (PDF) des jalons factures ── */
window.raasAdminInvoice = function(){
  var cur = window.__raasCurrentClient;
  if(!cur || !cur.data){ alert('Sélectionnez un client et chargez son échéancier.'); return; }
  var k = cur.kyc || {};
  function esc(s){ return s?String(s).replace(/</g,'&lt;').replace(/>/g,'&gt;'):''; }
  var cliNom = esc(k.raison_sociale) || cur.name;
  var billTo = '<strong>'+cliNom+'</strong>';
  if(k.adresse) billTo += '<br>'+esc(k.adresse);
  if(k.code_postal || k.ville) billTo += '<br>'+esc(k.code_postal||'')+' '+esc(k.ville||'');
  if(k.siren) billTo += '<br>SIREN\u00a0: '+esc(k.siren);
  if(k.tva_intra) billTo += '<br>TVA\u00a0: '+esc(k.tva_intra);
  if(k.email_contact) billTo += '<br>'+esc(k.email_contact);
  billTo += '<br>R\u00e9f. client\u00a0: '+cur.id;
  var invoiced = cur.data.milestones.filter(function(m){ return m.status === 'invoiced'; });
  if(!invoiced.length){ alert('Aucun jalon facturé pour ce client. Lancez d\u2019abord le cycle de facturation.'); return; }
  function eur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
  var today = new Date();
  var num = 'F'+today.getFullYear()+String(today.getMonth()+1).padStart(2,'0')+'-'+cur.id+'-'+String(today.getDate()).padStart(2,'0');
  var dateStr = today.toLocaleDateString('fr-FR');
  var totalHT = invoiced.reduce(function(a,m){ return a+m.amount_eur; }, 0);
  var tva = Math.round(totalHT * 0.20);
  var ttc = totalHT + tva;
  var rows = invoiced.map(function(m){
    var half = Math.round(m.amount_eur/2);
    return '<tr><td>'+m.label+'<div style="font-size:9px;color:#888">'+(m.art||'')+' \u00b7 v\u00e9rifi\u00e9 le '+String(m.verified_at||'').substring(0,10)+'</div></td>'
      + '<td style="text-align:center">2 mensualit\u00e9s de '+eur(half)+'</td>'
      + '<td style="text-align:right"><strong>'+eur(m.amount_eur)+'</strong></td></tr>';
  }).join('');
  var html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Facture '+num+' \u2014 '+cur.name+'</title>'
    + '<style>@page{margin:2cm}body{font-family:Arial,sans-serif;color:#1C1C1C;max-width:820px;margin:0 auto;padding:20px;line-height:1.55}'
    + '.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #B83222;padding-bottom:14px;margin-bottom:18px}'
    + 'h1{font-size:22px;margin:0;color:#B83222}'
    + '.meta{text-align:right;font-size:11px;color:#555}'
    + '.bill-to{background:#faf9f7;border:1px solid #eee;border-radius:6px;padding:12px 14px;font-size:12px;margin-bottom:16px}'
    + 'table{width:100%;border-collapse:collapse;font-size:12px;margin:10px 0}'
    + 'th{background:#1C1C1C;color:#fff;padding:8px 10px;text-align:left;font-size:10px}'
    + 'td{border:1px solid #ddd;padding:8px 10px}'
    + '.totrow td{border-top:2px solid #1C1C1C;font-weight:bold;background:#f4f2ee;font-size:13px}'
    + '.note{font-size:10.5px;color:#666;margin-top:14px;line-height:1.6}'
    + '.foot{font-size:9.5px;color:#999;margin-top:26px;border-top:1px solid #eee;padding-top:10px}'
    + '</style></head><body>'
    + '<div class="head"><div><h1>FACTURE</h1><div style="font-size:11px;color:#555;margin-top:4px">Tarification RaaS par jalons \u2014 Sentinel AI</div></div>'
    + '<div class="meta">N\u00b0 '+num+'<br>Date d\u2019\u00e9mission\u00a0: '+dateStr+'<br>Prestation\u00a0: v\u00e9rification des jalons list\u00e9s<br>R\u00e9f. client\u00a0: '+cur.id+'</div></div>'
    + '<div style="display:flex;gap:20px;margin-bottom:16px">'
    + '<div style="flex:1;font-size:12px"><strong>\u00c9metteur</strong><br>CONSEILPREV \u2014 SARL au capital de 8\u202f000\u202f\u20ac<br>Christophe CERF, g\u00e9rant<br>19 rue Auguste Chabri\u00e8res, 75015 Paris<br>SIREN 494\u202f530\u202f157 \u2014 RCS Paris<br>TVA\u202f: FR\u202f24\u202f494\u202f530\u202f157<br>christophe.cerf@outlook.com</div>'
    + '<div class="bill-to" style="flex:1"><strong>Factur\u00e9 \u00e0</strong><br>'+billTo+'</div>'
    + '</div>'
    + '<table><thead><tr><th>Jalon de conformit\u00e9 factur\u00e9</th><th style="text-align:center">\u00c9chelonnement</th><th style="text-align:right">Montant</th></tr></thead>'
    + '<tbody>'+rows
    + '<tr><td colspan="2" style="text-align:right">Total HT</td><td style="text-align:right">'+eur(totalHT)+'</td></tr>'
    + '<tr><td colspan="2" style="text-align:right">TVA 20\u202f%</td><td style="text-align:right">'+eur(tva)+'</td></tr>'
    + '<tr class="totrow"><td colspan="2" style="text-align:right">Total TTC \u00e0 r\u00e9gler</td><td style="text-align:right">'+eur(ttc)+'</td></tr>'
    + '</tbody></table>'
    + '<div class="note"><strong>Conditions de r\u00e8glement.</strong> Paiement \u00e0 r\u00e9ception de la facture, selon l\u2019\u00e9ch\u00e9ancier contractuel \u00e9chelonn\u00e9 sur deux mensualit\u00e9s \u00e9gales. Aucun escompte pour paiement anticip\u00e9.<br><strong>Retard de paiement.</strong> Conform\u00e9ment aux articles L.441-10 et D.441-5 du Code de commerce, tout retard entra\u00eene l\u2019application de p\u00e9nalit\u00e9s au taux de trois fois le taux d\u2019int\u00e9r\u00eat l\u00e9gal, ainsi qu\u2019une indemnit\u00e9 forfaitaire pour frais de recouvrement de 40\u202f\u20ac.<br><strong>TVA.</strong> TVA au taux de 20\u202f% \u2014 num\u00e9ro de TVA intracommunautaire FR\u202f24\u202f494\u202f530\u202f157.<br>Chaque jalon factur\u00e9 a fait l\u2019objet d\u2019une double v\u00e9rification (score Sentinel atteint et validation documentaire) et constitue un r\u00e9sultat de conformit\u00e9 acquis. Mentions \u00e9tablies au titre des articles L.441-9 du Code de commerce et 242 nonies A de l\u2019annexe II au CGI.</div>'
    + '<div class="foot">CONSEILPREV \u2014 SARL au capital de 8\u202f000\u202f\u20ac \u2014 SIREN 494\u202f530\u202f157 RCS Paris \u2014 Responsable de traitement (RGPD), DPO\u00a0: christophe.cerf@outlook.com \u2014 Facture g\u00e9n\u00e9r\u00e9e par Sentinel AI le '+dateStr+'.</div>'
    + '</body></html>';
  var w = window.open('', '_blank');
  if(!w){ alert('Autorisez les pop-ups pour générer la facture.'); return; }
  w.document.write(html + '<scr'+'ipt>window.onload=function(){window.print();}<'+'/scr'+'ipt>');
  w.document.close();
};

/* ══ GESTION EXPERTE DES CLIENTS RAAS — KYC, notes, contrats BDD, factures ══ */
window.raasExpertRender = function(clientId){
  var box = document.getElementById('raas-admin-expert');
  if(!box) return;
  box.innerHTML =
    '<div class="raas-expert-tabs" style="display:flex;gap:6px;margin:18px 0 12px;flex-wrap:wrap">'
    + '<button class="raas-tab-btn active" data-tab="suivi" onclick="raasExpertTab(\'suivi\')">\ud83d\udcca Suivi &amp; Relances</button>'
    + '<button class="raas-tab-btn" data-tab="kyc" onclick="raasExpertTab(\'kyc\')">KYC client</button>'
    + '<button class="raas-tab-btn" data-tab="notes" onclick="raasExpertTab(\'notes\')">Notes</button>'
    + '<button class="raas-tab-btn" data-tab="contracts" onclick="raasExpertTab(\'contracts\')">Contrats</button>'
    + '<button class="raas-tab-btn" data-tab="invoices" onclick="raasExpertTab(\'invoices\')">Factures</button>'
    + '</div>'
    + '<div id="raas-tab-suivi" class="raas-tab-pane"></div>'
    + '<div id="raas-tab-kyc" class="raas-tab-pane" style="display:none"></div>'
    + '<div id="raas-tab-notes" class="raas-tab-pane" style="display:none"></div>'
    + '<div id="raas-tab-contracts" class="raas-tab-pane" style="display:none"></div>'
    + '<div id="raas-tab-invoices" class="raas-tab-pane" style="display:none"></div>';
  raasSuiviLoad(clientId);
  raasKycLoad(clientId);
  raasNotesLoad(clientId);
  raasContractsLoad(clientId);
  raasInvoicesLoad(clientId);
};

window.raasExpertTab = function(tab){
  ['suivi','kyc','notes','contracts','invoices'].forEach(function(t){
    var pane=document.getElementById('raas-tab-'+t);
    if(pane) pane.style.display = (t===tab)?'block':'none';
  });
  document.querySelectorAll('.raas-tab-btn').forEach(function(b){
    b.classList.toggle('active', b.getAttribute('data-tab')===tab);
  });
};

function raasCid(){ var s=document.getElementById('raas-client-select'); return s?s.value:''; }
function raasEur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }

/* ── SUIVI & RELANCES (tableau de bord) ── */
window.RAAS_STATUTS = {prospect:'Prospect', onboarding:'Onboarding', actif:'Actif', a_risque:'\u00c0 risque', inactif:'Inactif', clos:'Clos'};
window.RAAS_SANTES = {a_evaluer:'\u00c0 \u00e9valuer', bonne:'Bonne', moyenne:'Moyenne', fragile:'Fragile'};
window.RAAS_SANTE_COLOR = {a_evaluer:'var(--muted2)', bonne:'var(--green)', moyenne:'#c98a00', fragile:'var(--accent)'};

window.raasSuiviLoad = function(clientId){
  var pane=document.getElementById('raas-tab-suivi'); if(!pane) return;
  pane.innerHTML='<div style="color:var(--muted);font-size:12px;padding:10px">Chargement du tableau de bord…</div>';
  fetch('/api/clients/dashboard?client_id='+encodeURIComponent(clientId),{credentials:'same-origin'})
    .then(function(r){return r.json();}).then(function(d){
      if(!d.ok){ pane.innerHTML='<div style="color:var(--accent);font-size:12px;padding:10px">'+(d.error||'Erreur')+'</div>'; return; }
      var st=d.status||{};
      var statut=st.statut||'prospect';
      var sante=st.sante||'a_evaluer';
      function eur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
      // Bandeau KPI
      var kpis =
        '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px">'
        + '<div class="ms-sum-card"><div class="ms-sum-lbl">Factures impay\u00e9es</div><div class="ms-sum-val" style="color:'+(d.unpaid_invoices.length?'var(--accent)':'var(--green)')+'">'+d.unpaid_invoices.length+'</div><div class="ms-sum-sub">'+eur(d.unpaid_total)+'</div></div>'
        + '<div class="ms-sum-card"><div class="ms-sum-lbl">Relances en attente</div><div class="ms-sum-val">'+d.pending_relances.length+'</div><div class="ms-sum-sub">\u00e0 traiter</div></div>'
        + '<div class="ms-sum-card"><div class="ms-sum-lbl">Jalons en attente</div><div class="ms-sum-val">'+d.milestones_pending+'</div><div class="ms-sum-sub">sur '+d.milestones_total+'</div></div>'
        + '<div class="ms-sum-card"><div class="ms-sum-lbl">Dernier contact</div><div class="ms-sum-val">'+(d.last_contact_days!==null?d.last_contact_days+'j':'\u2014')+'</div><div class="ms-sum-sub">'+(d.last_contact_days!==null?'jours':'jamais')+'</div></div>'
        + '</div>';
      // Statut & sante (editables)
      var statOpts=Object.keys(window.RAAS_STATUTS).map(function(k){return '<option value="'+k+'"'+(k===statut?' selected':'')+'>'+window.RAAS_STATUTS[k]+'</option>';}).join('');
      var santeOpts=Object.keys(window.RAAS_SANTES).map(function(k){return '<option value="'+k+'"'+(k===sante?' selected':'')+'>'+window.RAAS_SANTES[k]+'</option>';}).join('');
      var statusBar =
        '<div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;background:var(--bg);border:1px solid var(--rule2);border-radius:8px;padding:12px 14px;margin-bottom:14px">'
        + '<div><label style="font-size:9px;font-family:var(--mono);text-transform:uppercase;color:var(--muted2);display:block;margin-bottom:3px">Statut client</label><select id="suivi-statut" style="padding:6px 10px;border:1px solid var(--rule2);border-radius:5px;font-size:12px">'+statOpts+'</select></div>'
        + '<div><label style="font-size:9px;font-family:var(--mono);text-transform:uppercase;color:var(--muted2);display:block;margin-bottom:3px">Sant\u00e9 relation</label><select id="suivi-sante" style="padding:6px 10px;border:1px solid var(--rule2);border-radius:5px;font-size:12px">'+santeOpts+'</select></div>'
        + '<div><label style="font-size:9px;font-family:var(--mono);text-transform:uppercase;color:var(--muted2);display:block;margin-bottom:3px">Prochaine action</label><input id="suivi-next-label" value="'+(st.next_action_label?String(st.next_action_label).replace(/"/g,'&quot;'):'')+'" placeholder="Ex: appel de suivi" style="padding:6px 10px;border:1px solid var(--rule2);border-radius:5px;font-size:12px;min-width:170px"></div>'
        + '<div><label style="font-size:9px;font-family:var(--mono);text-transform:uppercase;color:var(--muted2);display:block;margin-bottom:3px">Le</label><input type="date" id="suivi-next-date" value="'+(st.next_action_at?String(st.next_action_at).substring(0,10):'')+'" style="padding:6px 10px;border:1px solid var(--rule2);border-radius:5px;font-size:12px"></div>'
        + '<button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="raasStatusSave()">Enregistrer le statut</button>'
        + '<span id="suivi-status-msg" style="font-size:11px;align-self:center"></span>'
        + '</div>';
      // Suggestions automatiques
      var sugg = d.suggestions.length ? '<div style="margin-bottom:14px"><strong style="font-size:12px;display:block;margin-bottom:6px">\ud83d\udca1 Relances sugg\u00e9r\u00e9es</strong>'
        + d.suggestions.map(function(s){
            var col=s.priorite==='urgente'?'var(--accent)':(s.priorite==='haute'?'#c98a00':'var(--muted2)');
            return '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;border-left:3px solid '+col+';background:var(--bg);padding:8px 12px;margin-bottom:6px;border-radius:4px">'
              + '<span style="font-size:12px">'+s.objet+'</span>'
              + '<button class="mat-export-btn" style="padding:3px 10px;font-size:10px" onclick="raasRelanceQuick(\''+s.type+'\',\''+encodeURIComponent(s.objet)+'\',\''+s.priorite+'\',\''+(s.related_ref||'')+'\')">Planifier</button>'
              + '</div>';
          }).join('') + '</div>' : '';
      // Factures impayees avec action "marquer payee" + "relancer"
      var unpaid = d.unpaid_invoices.length ? '<div style="margin-bottom:14px"><strong style="font-size:12px;display:block;margin-bottom:6px">Factures impay\u00e9es</strong>'
        + '<table class="ms-table"><thead><tr><th>N\u00b0</th><th>Montant</th><th>\u00c9mise le</th><th>Action</th></tr></thead><tbody>'
        + d.unpaid_invoices.map(function(i){
            return '<tr><td>'+i.numero+'</td><td class="ms-amount">'+eur(i.amount_eur)+'</td><td style="font-size:10px">'+String(i.issued_at).substring(0,10)+'</td>'
              + '<td style="display:flex;gap:5px"><button class="mat-export-btn" style="padding:3px 9px;font-size:10px" onclick="raasInvoiceRemind(\''+i.numero+'\')">\u2709 Relancer</button><button class="mat-export-btn" style="padding:3px 9px;font-size:10px" onclick="raasInvoicePay(\''+i.numero+'\')">Marquer pay\u00e9e</button></td></tr>';
          }).join('') + '</tbody></table></div>' : '';
      pane.innerHTML = kpis + statusBar + sugg + unpaid + '<div id="suivi-relances"></div>';
      raasRelancesLoad(clientId);
    }).catch(function(){ pane.innerHTML='<div style="color:var(--accent);font-size:12px;padding:10px">Erreur de chargement du tableau de bord.</div>'; });
};

window.raasStatusSave = function(){
  var cid=raasCid(); if(!cid) return;
  var msg=document.getElementById('suivi-status-msg');
  var body={client_id:parseInt(cid,10),
    statut:(document.getElementById('suivi-statut')||{}).value,
    sante:(document.getElementById('suivi-sante')||{}).value,
    next_action_label:(document.getElementById('suivi-next-label')||{}).value,
    next_action_at:(document.getElementById('suivi-next-date')||{}).value};
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Enregistrement…'; }
  fetch('/api/clients/status',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
    .then(function(r){return r.json();}).then(function(d){
      if(msg){ msg.style.color=d.ok?'var(--green)':'var(--accent)'; msg.textContent=d.ok?'Statut enregistr\u00e9':(d.error||'Erreur'); }
    }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur r\u00e9seau.'; } });
};

window.raasInvoicePay = function(numero){
  var cid=raasCid(); if(!cid) return;
  if(!confirm('Marquer la facture '+numero+' comme pay\u00e9e ?')) return;
  fetch('/api/clients/invoices/pay',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:parseInt(cid,10),numero:numero})})
    .then(function(r){return r.json();}).then(function(d){ if(d.ok){ raasSuiviLoad(cid); if(window.raasInvoicesLoad) raasInvoicesLoad(cid); } });
};

window.raasInvoiceRemind = function(numero){
  var cid=raasCid(); if(!cid) return;
  if(!confirm('Envoyer un email de rappel de paiement au client pour la facture '+numero+' ?')) return;
  fetch('/api/clients/invoices/remind',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:parseInt(cid,10),numero:numero})})
    .then(function(r){return r.json();}).then(function(d){
      if(d.ok && d.email_sent){ alert('Rappel envoy\u00e9 \u00e0 '+d.to+'.'); }
      else if(d.ok && !d.email_sent){ alert('Rappel non envoy\u00e9 : '+(d.email_error||d.message||'v\u00e9rifiez l\'email KYC du client')+'. La relance a \u00e9t\u00e9 enregistr\u00e9e.'); }
      else { alert(d.error||'Erreur'); }
      raasSuiviLoad(cid);
    }).catch(function(){ alert('Erreur r\u00e9seau.'); });
};

window.raasRelanceQuick = function(type,objetEnc,priorite,ref){
  var cid=raasCid(); if(!cid) return;
  var objet=decodeURIComponent(objetEnc);
  var body={client_id:parseInt(cid,10),type:type,objet:objet,priorite:priorite,related_ref:ref||'',
            due_date:new Date(Date.now()+3*86400000).toISOString().substring(0,10)};
  fetch('/api/clients/relances',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
    .then(function(r){return r.json();}).then(function(d){ if(d.ok) raasSuiviLoad(cid); });
};

window.raasRelancesLoad = function(clientId){
  var box=document.getElementById('suivi-relances'); if(!box) return;
  fetch('/api/clients/relances?client_id='+encodeURIComponent(clientId),{credentials:'same-origin'})
    .then(function(r){return r.json();}).then(function(d){
      var rel=(d.ok&&d.relances)?d.relances:[];
      var TYPES={email:'Email',appel:'Appel',rdv:'RDV',relance_facture:'Relance facture',relance_jalon:'Relance jalon',autre:'Autre'};
      var PRIOC={basse:'var(--muted2)',normale:'var(--ink2)',haute:'#c98a00',urgente:'var(--accent)'};
      var rows = rel.length ? rel.map(function(r){
        var done=r.status!=='planifiee';
        var col=PRIOC[r.priorite]||'var(--ink2)';
        return '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;border-left:3px solid '+col+';background:'+(done?'var(--bg2)':'var(--white)')+';border:1px solid var(--rule2);border-radius:5px;padding:9px 12px;margin-bottom:7px'+(done?';opacity:.6':'')+'">'
          + '<div><div style="font-size:12px;font-weight:500'+(done?';text-decoration:line-through':'')+'">'+String(r.objet).replace(/</g,"&lt;")+'</div>'
          + '<div style="font-size:9px;color:var(--muted2);margin-top:3px">'+(TYPES[r.type]||r.type)+' \u00b7 '+r.priorite+(r.due_date?' \u00b7 \u00e9ch\u00e9ance '+String(r.due_date).substring(0,10):'')+(r.status!=='planifiee'?' \u00b7 '+r.status:'')+'</div>'
          + (r.notes?'<div style="font-size:11px;color:var(--ink2);margin-top:4px;white-space:pre-wrap">'+String(r.notes).replace(/</g,"&lt;")+'</div>':'')+'</div>'
          + (done?'':'<div style="display:flex;gap:5px;flex-shrink:0"><button class="mat-export-btn" style="padding:3px 9px;font-size:10px" onclick="raasRelanceComplete('+r.id+',\'faite\')">\u2713 Faite</button><button class="mat-export-btn" style="padding:3px 9px;font-size:10px" onclick="raasRelanceComplete('+r.id+',\'annulee\')">Annuler</button></div>')
          + '</div>';
      }).join('') : '<div style="color:var(--muted2);font-size:12px;padding:8px">Aucune relance enregistr\u00e9e.</div>';
      box.innerHTML =
        '<div style="display:flex;justify-content:space-between;align-items:center;margin:6px 0 10px"><strong style="font-size:13px">Relances</strong>'
        + '<button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="raasRelanceForm()">+ Nouvelle relance</button></div>'
        + '<div id="suivi-relance-form"></div>'
        + rows;
    }).catch(function(){ box.innerHTML='<div style="color:var(--accent);font-size:12px;padding:8px">Erreur de chargement des relances.</div>'; });
};

window.raasRelanceForm = function(){
  var box=document.getElementById('suivi-relance-form'); if(!box) return;
  if(box.innerHTML){ box.innerHTML=''; return; }
  box.innerHTML =
    '<div style="background:var(--bg);border:1px solid var(--rule2);border-radius:6px;padding:12px;margin-bottom:10px">'
    + '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">'
    + '<input id="rel-objet" placeholder="Objet de la relance" style="flex:2;min-width:200px;padding:7px 10px;border:1px solid var(--rule2);border-radius:5px;font-size:12px">'
    + '<select id="rel-type" style="padding:7px 10px;border:1px solid var(--rule2);border-radius:5px;font-size:12px"><option value="email">Email</option><option value="appel">Appel</option><option value="rdv">RDV</option><option value="relance_facture">Relance facture</option><option value="relance_jalon">Relance jalon</option><option value="autre">Autre</option></select>'
    + '<select id="rel-prio" style="padding:7px 10px;border:1px solid var(--rule2);border-radius:5px;font-size:12px"><option value="basse">Basse</option><option value="normale" selected>Normale</option><option value="haute">Haute</option><option value="urgente">Urgente</option></select>'
    + '<input type="date" id="rel-date" style="padding:7px 10px;border:1px solid var(--rule2);border-radius:5px;font-size:12px">'
    + '</div>'
    + '<textarea id="rel-notes" placeholder="Notes (facultatif)" style="width:100%;min-height:50px;padding:8px;border:1px solid var(--rule2);border-radius:5px;font-size:12px;font-family:inherit;margin-bottom:8px"></textarea>'
    + '<button class="mat-export-btn" style="background:var(--accent);color:#fff" onclick="raasRelanceAdd()">Enregistrer la relance</button>'
    + '<span id="rel-msg" style="font-size:11px;margin-left:10px"></span></div>';
};

window.raasRelanceAdd = function(){
  var cid=raasCid(); if(!cid) return;
  var msg=document.getElementById('rel-msg');
  var objet=(document.getElementById('rel-objet')||{}).value||'';
  if(!objet.trim()){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Objet requis.'; } return; }
  var body={client_id:parseInt(cid,10),objet:objet,
    type:(document.getElementById('rel-type')||{}).value,
    priorite:(document.getElementById('rel-prio')||{}).value,
    due_date:(document.getElementById('rel-date')||{}).value,
    notes:(document.getElementById('rel-notes')||{}).value};
  fetch('/api/clients/relances',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
    .then(function(r){return r.json();}).then(function(d){
      if(d.ok){ raasRelancesLoad(cid); } else if(msg){ msg.style.color='var(--accent)'; msg.textContent=d.error||'Erreur'; }
    }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur r\u00e9seau.'; } });
};

window.raasRelanceComplete = function(id,status){
  var cid=raasCid(); if(!cid) return;
  fetch('/api/clients/relances/complete',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:parseInt(cid,10),id:id,status:status})})
    .then(function(r){return r.json();}).then(function(d){ if(d.ok){ raasRelancesLoad(cid); raasSuiviLoad(cid); } });
};

/* ── KYC ── */
window.raasKycLoad = function(clientId){
  var pane=document.getElementById('raas-tab-kyc'); if(!pane) return;
  pane.innerHTML='<div style="color:var(--muted);font-size:12px;padding:10px">Chargement KYC…</div>';
  fetch('/api/clients/kyc?client_id='+encodeURIComponent(clientId),{credentials:'same-origin'})
    .then(function(r){return r.json();}).then(function(d){
      var k=(d.ok&&d.kyc)?d.kyc:{};
      if(window.__raasCurrentClient && String(window.__raasCurrentClient.id)===String(clientId)){
        window.__raasCurrentClient.kyc = k;
      }
      function fld(id,lbl,val,ph,w){ return '<div style="flex:'+(w||1)+';min-width:160px"><label style="font-size:9px;font-family:var(--mono);text-transform:uppercase;letter-spacing:.07em;color:var(--muted2);display:block;margin-bottom:3px">'+lbl+'</label><input id="kyc-'+id+'" value="'+(val?String(val).replace(/"/g,'&quot;'):'')+'" placeholder="'+(ph||'')+'" style="width:100%;padding:6px 9px;border:1px solid var(--rule2);border-radius:5px;font-size:12px"></div>'; }
      var badge = (k.kyc_status==='complet')
        ? '<span style="background:rgba(45,122,71,.12);color:var(--green);padding:3px 10px;border-radius:12px;font-size:10px;font-family:var(--mono)">\u2705 KYC complet</span>'
        : '<span style="background:rgba(184,50,34,.1);color:var(--accent);padding:3px 10px;border-radius:12px;font-size:10px;font-family:var(--mono)">\u26a0 KYC incomplet</span>';
      pane.innerHTML =
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><strong style="font-size:13px">Fiche KYC (Know Your Customer)</strong>'+badge+'</div>'
        + '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">'
        + fld('raison_sociale','Raison sociale',k.raison_sociale,'',2)+fld('siren','SIREN',k.siren,'9 chiffres')+fld('forme_juridique','Forme juridique',k.forme_juridique,'SAS, SARL…')
        + '</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">'
        + fld('adresse','Adresse',k.adresse,'',2)+fld('code_postal','Code postal',k.code_postal,'')+fld('ville','Ville',k.ville,'')
        + '</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">'
        + fld('representant','Représentant légal',k.representant,'')+fld('fonction_representant','Fonction',k.fonction_representant,'')+fld('pays','Pays',k.pays||'France','')
        + '</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">'
        + fld('email_contact','Email de contact',k.email_contact,'')+fld('telephone','Téléphone',k.telephone,'')+fld('tva_intra','TVA intracom.',k.tva_intra,'')
        + '</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px">'
        + fld('secteur','Secteur',k.secteur,'')+fld('effectif','Effectif',k.effectif,'')
        + '</div>'
        + '<button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="raasKycSave()">Enregistrer la fiche KYC</button>'
        + '<span id="kyc-msg" style="font-size:12px;margin-left:12px"></span>'
        + (k.updated_at?'<div style="font-size:10px;color:var(--muted2);margin-top:8px">Dernière mise à jour : '+String(k.updated_at).substring(0,16).replace('T',' ')+'</div>':'')
        + (window.raasRgpdBlock?window.raasRgpdBlock(clientId):'');
    }).catch(function(){ pane.innerHTML='<div style="color:var(--accent);font-size:12px;padding:10px">Erreur de chargement KYC.</div>'; });
};

window.raasKycSave = function(){
  var cid=raasCid(); if(!cid) return;
  var msg=document.getElementById('kyc-msg');
  function v(id){ var e=document.getElementById('kyc-'+id); return e?e.value.trim():''; }
  var body={client_id:parseInt(cid,10)};
  ['raison_sociale','siren','forme_juridique','adresse','code_postal','ville','pays','representant','fonction_representant','email_contact','telephone','tva_intra','secteur','effectif'].forEach(function(f){ body[f]=v(f); });
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Enregistrement…'; }
  fetch('/api/clients/kyc',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
    .then(function(r){return r.json();}).then(function(d){
      if(msg){ msg.style.color=d.ok?'var(--green)':'var(--accent)'; msg.textContent=d.ok?('Fiche enregistrée — statut : '+d.kyc_status):(d.error||'Erreur'); }
      if(d.ok) raasKycLoad(cid);
    }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur réseau.'; } });
};

/* ── NOTES ── */
window.raasNotesLoad = function(clientId){
  var pane=document.getElementById('raas-tab-notes'); if(!pane) return;
  pane.innerHTML='<div style="color:var(--muted);font-size:12px;padding:10px">Chargement…</div>';
  fetch('/api/clients/notes?client_id='+encodeURIComponent(clientId),{credentials:'same-origin'})
    .then(function(r){return r.json();}).then(function(d){
      var notes=(d.ok&&d.notes)?d.notes:[];
      var list = notes.length ? notes.map(function(n){
        return '<div style="border-left:3px solid var(--rule2);padding:8px 12px;margin-bottom:8px;background:var(--bg)"><div style="font-size:12px;color:var(--ink2);white-space:pre-wrap">'+String(n.note).replace(/</g,'&lt;')+'</div><div style="font-size:9px;color:var(--muted2);margin-top:4px">'+(n.author||'CONSEILPREV')+' · '+String(n.created_at).substring(0,16).replace('T',' ')+'</div></div>';
      }).join('') : '<div style="color:var(--muted2);font-size:12px;padding:8px">Aucune note pour ce client.</div>';
      pane.innerHTML =
        '<strong style="font-size:13px;display:block;margin-bottom:10px">Notes explicatives client</strong>'
        + '<textarea id="note-input" placeholder="Ajouter une note explicative (contexte, échanges, décisions…)" style="width:100%;min-height:70px;padding:9px;border:1px solid var(--rule2);border-radius:6px;font-size:12px;font-family:inherit;margin-bottom:8px"></textarea>'
        + '<button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="raasNoteAdd()">Ajouter la note</button>'
        + '<span id="note-msg" style="font-size:12px;margin-left:12px"></span>'
        + '<div style="margin-top:14px">'+list+'</div>';
    }).catch(function(){ pane.innerHTML='<div style="color:var(--accent);font-size:12px;padding:10px">Erreur de chargement.</div>'; });
};

window.raasNoteAdd = function(){
  var cid=raasCid(); if(!cid) return;
  var inp=document.getElementById('note-input'); var msg=document.getElementById('note-msg');
  var note=inp?inp.value.trim():'';
  if(!note){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Note vide.'; } return; }
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Ajout…'; }
  fetch('/api/clients/notes',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:parseInt(cid,10),note:note})})
    .then(function(r){return r.json();}).then(function(d){
      if(d.ok){ raasNotesLoad(cid); } else if(msg){ msg.style.color='var(--accent)'; msg.textContent=d.error||'Erreur'; }
    }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur réseau.'; } });
};

/* ── CONTRATS (BDD) ── */
window.raasContractsLoad = function(clientId){
  var pane=document.getElementById('raas-tab-contracts'); if(!pane) return;
  pane.innerHTML='<div style="color:var(--muted);font-size:12px;padding:10px">Chargement…</div>';
  fetch('/api/clients/contracts?client_id='+encodeURIComponent(clientId),{credentials:'same-origin'})
    .then(function(r){return r.json();}).then(function(d){
      var cs=(d.ok&&d.contracts)?d.contracts:[];
      var rows = cs.length ? '<table class="ms-table"><thead><tr><th>Référence</th><th>Enveloppe</th><th>Jalons</th><th>Statut</th><th>Créé le</th></tr></thead><tbody>'
        + cs.map(function(c){ return '<tr><td>'+c.reference+'</td><td class="ms-amount">'+raasEur(c.envelope_total)+'</td><td>'+(c.milestones_count||'—')+'</td><td>'+c.status+'</td><td style="font-size:10px">'+String(c.created_at).substring(0,10)+'</td></tr>'; }).join('')
        + '</tbody></table>' : '<div style="color:var(--muted2);font-size:12px;padding:8px">Aucun contrat enregistré.</div>';
      pane.innerHTML =
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><strong style="font-size:13px">Contrats RaaS enregistrés (base de données)</strong>'
        + '<button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="raasContractSaveDb()">Enregistrer le contrat courant</button></div>'
        + '<span id="contract-msg" style="font-size:12px"></span>'
        + '<div style="margin-top:10px">'+rows+'</div>'
        + '<div style="font-size:10px;color:var(--muted2);margin-top:8px">Le bouton « Générer le contrat RaaS (PDF) » ci-dessus produit le document imprimable ; l\'enregistrement ci-contre archive une référence traçable en base.</div>';
    }).catch(function(){ pane.innerHTML='<div style="color:var(--accent);font-size:12px;padding:10px">Erreur de chargement.</div>'; });
};

window.raasContractSaveDb = function(){
  var cur=window.__raasCurrentClient; var msg=document.getElementById('contract-msg');
  if(!cur||!cur.data){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Chargez d\'abord l\'échéancier.'; } return; }
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Enregistrement…'; }
  fetch('/api/clients/contracts',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({client_id:parseInt(cur.id,10),envelope_total:cur.data.envelope_total,milestones_count:(cur.data.milestones||[]).length,content:{milestones:cur.data.milestones}})})
    .then(function(r){return r.json();}).then(function(d){
      if(msg){ msg.style.color=d.ok?'var(--green)':'var(--accent)'; msg.textContent=d.ok?('Contrat enregistré — '+d.reference):(d.error||'Erreur'); }
      if(d.ok) raasContractsLoad(cur.id);
    }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur réseau.'; } });
};

/* ── FACTURES (selon échéancier) ── */
window.raasInvoicesLoad = function(clientId){
  var pane=document.getElementById('raas-tab-invoices'); if(!pane) return;
  pane.innerHTML='<div style="color:var(--muted);font-size:12px;padding:10px">Chargement…</div>';
  fetch('/api/clients/invoices?client_id='+encodeURIComponent(clientId),{credentials:'same-origin'})
    .then(function(r){return r.json();}).then(function(d){
      var inv=(d.ok&&d.invoices)?d.invoices:[];
      var rows = inv.length ? '<table class="ms-table"><thead><tr><th>N° facture</th><th>Jalon</th><th>Montant</th><th>Échelonnement</th><th>Statut</th><th>Émise le</th></tr></thead><tbody>'
        + inv.map(function(i){ return '<tr><td>'+i.numero+'</td><td style="font-size:11px">'+(i.milestone_id||'—')+'</td><td class="ms-amount">'+raasEur(i.amount_eur)+'</td><td>'+(i.installments||2)+' mens.</td><td>'+i.status+'</td><td style="font-size:10px">'+String(i.issued_at).substring(0,10)+'</td></tr>'; }).join('')
        + '</tbody></table>' : '<div style="color:var(--muted2);font-size:12px;padding:8px">Aucune facture émise.</div>';
      pane.innerHTML =
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex-wrap:wrap;gap:8px"><strong style="font-size:13px">Factures émises selon l\'échéancier</strong>'
        + '<label style="font-size:11px;color:var(--muted2);display:flex;align-items:center;gap:6px"><input type="checkbox" id="inv-notify" checked> Notifier le client par email</label></div>'
        + '<button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="raasInvoiceAuto()" title="Emet, genere le PDF juridique et notifie, en un clic">\u26a1 Générer la facture (automatique)</button> '
        + '<button class="mat-export-btn" style="background:var(--accent);color:#fff" onclick="raasInvoicesIssue()">Émettre les factures des jalons vérifiés</button>'
        + '<span id="invoice-msg" style="font-size:12px;margin-left:12px"></span>'
        + '<div style="margin-top:12px">'+rows+'</div>';
    }).catch(function(){ pane.innerHTML='<div style="color:var(--accent);font-size:12px;padding:10px">Erreur de chargement.</div>'; });
};

window.raasInvoiceAuto = function(){
  var cid=raasCid(); if(!cid) return;
  var msg=document.getElementById('invoice-msg');
  var notify=document.getElementById('inv-notify'); var doNotify=notify?notify.checked:true;
  if(!confirm('G\u00e9n\u00e9ration automatique\u00a0: \u00e9mettre les factures des jalons v\u00e9rifi\u00e9s selon la num\u00e9rotation officielle, produire le document juridique complet'+(doNotify?' et notifier le client par email':'')+'\u00a0?')) return;
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='\u00c9mission en cours…'; }
  fetch('/api/clients/invoices/issue',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:parseInt(cid,10),notify:doNotify})})
    .then(function(r){return r.json();}).then(function(d){
      if(!d.ok){ if(msg){ msg.style.color='var(--accent)'; msg.textContent=d.error||'Erreur'; } return; }
      if(!d.issued_count){ if(msg){ msg.style.color='var(--accent)'; msg.textContent=d.message||'Aucun jalon v\u00e9rifi\u00e9 \u00e0 facturer'; } return; }
      // Rafraichir en temps reel
      raasInvoicesLoad(cid); if(window.raasAdminLoad) raasAdminLoad(); if(window.raasSuiviLoad) raasSuiviLoad(cid);
      // Recuperer la KYC a jour puis generer le document juridique avec les numeros officiels
      fetch('/api/clients/kyc?client_id='+encodeURIComponent(cid),{credentials:'same-origin'})
        .then(function(r){return r.json();}).then(function(kd){
          var kyc=(kd.ok&&kd.kyc)?kd.kyc:{};
          raasLegalInvoicePDF(d.invoices||[], kyc, cid);
          if(msg){ msg.style.color='var(--green)'; msg.textContent=d.issued_count+' facture(s) \u00e9mise(s) et document g\u00e9n\u00e9r\u00e9'+(d.email_sent?' \u2014 client notifi\u00e9':(doNotify?' \u2014 email non envoy\u00e9':'')); }
        }).catch(function(){ raasLegalInvoicePDF(d.invoices||[], {}, cid); });
    }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur r\u00e9seau.'; } });
};

/* Document juridique complet : une facture conforme par numero officiel (saut de page) */
window.raasLegalInvoicePDF = function(invoices, kyc, clientId){
  if(!invoices || !invoices.length){ alert('Aucune facture \u00e0 g\u00e9n\u00e9rer.'); return; }
  function eur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
  function esc(s){ return s?String(s).replace(/</g,'&lt;').replace(/>/g,'&gt;'):''; }
  var k=kyc||{};
  var cur=window.__raasCurrentClient||{};
  var cliNom=esc(k.raison_sociale)||(cur.name||('Client #'+clientId));
  var billTo='<strong>'+cliNom+'</strong>';
  if(k.adresse) billTo+='<br>'+esc(k.adresse);
  if(k.code_postal||k.ville) billTo+='<br>'+esc(k.code_postal||'')+' '+esc(k.ville||'');
  if(k.siren) billTo+='<br>SIREN\u00a0: '+esc(k.siren);
  if(k.tva_intra) billTo+='<br>TVA\u00a0: '+esc(k.tva_intra);
  if(k.email_contact) billTo+='<br>'+esc(k.email_contact);
  billTo+='<br>R\u00e9f. client\u00a0: '+clientId;
  var dateStr=new Date().toLocaleDateString('fr-FR');
  var emetteur='<strong>\u00c9metteur</strong><br>CONSEILPREV \u2014 SARL au capital de 8\u202f000\u202f\u20ac<br>Christophe CERF, g\u00e9rant<br>19 rue Auguste Chabri\u00e8res, 75015 Paris<br>SIREN 494\u202f530\u202f157 \u2014 RCS Paris<br>TVA\u202f: FR\u202f24\u202f494\u202f530\u202f157<br>christophe.cerf@outlook.com';
  var pages=invoices.map(function(inv, idx){
    var ht=inv.amount_eur||0; var tva=Math.round(ht*0.20); var ttc=ht+tva;
    var due=inv.due||[]; var ech=due.length?due.map(function(x){return 'Mensualit\u00e9 '+x.echeance+'\u00a0: '+eur(x.montant);}).join(' \u00b7 '):'2 mensualit\u00e9s \u00e9gales';
    return '<div class="invoice"'+(idx>0?' style="page-break-before:always"':'')+'>'
      +'<div class="head"><div><h1>FACTURE</h1><div class="tag">Tarification RaaS par jalons \u2014 Sentinel AI</div></div>'
      +'<div class="meta">N\u00b0 <strong>'+esc(inv.numero)+'</strong><br>Date d\u2019\u00e9mission\u00a0: '+dateStr+'<br>Prestation\u00a0: jalon de conformit\u00e9 v\u00e9rifi\u00e9<br>R\u00e9f. client\u00a0: '+clientId+'</div></div>'
      +'<div class="parties"><div class="em">'+emetteur+'</div><div class="bt">'+billTo+'</div></div>'
      +'<table><thead><tr><th>Prestation factur\u00e9e</th><th style="text-align:center">\u00c9chelonnement</th><th style="text-align:right">Montant HT</th></tr></thead>'
      +'<tbody><tr><td>'+esc(inv.label||'Jalon de conformit\u00e9')+'</td><td style="text-align:center">'+ech+'</td><td style="text-align:right"><strong>'+eur(ht)+'</strong></td></tr>'
      +'<tr><td colspan="2" style="text-align:right">Total HT</td><td style="text-align:right">'+eur(ht)+'</td></tr>'
      +'<tr><td colspan="2" style="text-align:right">TVA 20\u202f%</td><td style="text-align:right">'+eur(tva)+'</td></tr>'
      +'<tr class="ttc"><td colspan="2" style="text-align:right">Total TTC \u00e0 r\u00e9gler</td><td style="text-align:right">'+eur(ttc)+'</td></tr>'
      +'</tbody></table>'
      +'<div class="note"><strong>Conditions de r\u00e8glement.</strong> Paiement \u00e0 r\u00e9ception, selon l\u2019\u00e9ch\u00e9ancier contractuel \u00e9chelonn\u00e9 sur deux mensualit\u00e9s \u00e9gales. Aucun escompte pour paiement anticip\u00e9.<br>'
      +'<strong>Retard de paiement.</strong> Articles L.441-10 et D.441-5 du Code de commerce\u00a0: p\u00e9nalit\u00e9s au taux de trois fois le taux d\u2019int\u00e9r\u00eat l\u00e9gal et indemnit\u00e9 forfaitaire de recouvrement de 40\u202f\u20ac.<br>'
      +'<strong>TVA.</strong> TVA au taux de 20\u202f% \u2014 num\u00e9ro FR\u202f24\u202f494\u202f530\u202f157.<br>'
      +'Jalon ayant fait l\u2019objet d\u2019une double v\u00e9rification (score Sentinel atteint et validation documentaire). Mentions \u00e9tablies au titre des articles L.441-9 du Code de commerce et 242 nonies A de l\u2019annexe II au CGI.</div>'
      +'<div class="foot">CONSEILPREV \u2014 SARL au capital de 8\u202f000\u202f\u20ac \u2014 SIREN 494\u202f530\u202f157 RCS Paris \u2014 Responsable de traitement (RGPD), DPO\u00a0: christophe.cerf@outlook.com \u2014 Facture g\u00e9n\u00e9r\u00e9e par Sentinel AI le '+dateStr+'.</div>'
      +'</div>';
  }).join('');
  var html='<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Factures \u2014 '+cliNom+'</title>'
    +'<style>@page{margin:2cm}body{font-family:Arial,sans-serif;color:#1C1C1C;max-width:820px;margin:0 auto;padding:20px;line-height:1.55}'
    +'.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #B83222;padding-bottom:14px;margin-bottom:18px}'
    +'h1{font-size:22px;margin:0;color:#B83222}.tag{font-size:11px;color:#555;margin-top:4px}'
    +'.meta{text-align:right;font-size:11px;color:#555}'
    +'.parties{display:flex;gap:20px;margin-bottom:16px}.parties .em,.parties .bt{flex:1;font-size:12px}'
    +'.parties .bt{background:#faf9f7;border:1px solid #eee;border-radius:6px;padding:12px 14px}'
    +'table{width:100%;border-collapse:collapse;font-size:12px;margin:10px 0}'
    +'th{background:#1C1C1C;color:#fff;padding:8px 10px;text-align:left;font-size:10px}'
    +'td{border:1px solid #ddd;padding:8px 10px}'
    +'.ttc td{border-top:2px solid #1C1C1C;font-weight:bold;background:#f4f2ee;font-size:13px}'
    +'.note{font-size:10.5px;color:#666;margin-top:14px;line-height:1.6}'
    +'.foot{font-size:9.5px;color:#999;margin-top:26px;border-top:1px solid #eee;padding-top:10px}'
    +'</style></head><body>'+pages+'</body></html>';
  var w=window.open('','_blank');
  if(!w){ alert('Autorisez les pop-ups pour g\u00e9n\u00e9rer les factures.'); return; }
  w.document.write(html+'<scr'+'ipt>window.onload=function(){window.print();}<'+'/scr'+'ipt>');
  w.document.close();
};

window.raasInvoicesIssue = function(){
  var cid=raasCid(); if(!cid) return;
  var msg=document.getElementById('invoice-msg');
  var notify=document.getElementById('inv-notify'); var doNotify=notify?notify.checked:true;
  if(!confirm('Émettre les factures de tous les jalons vérifiés de ce client selon l\'échéancier ?'+(doNotify?' Le client sera notifié par email.':''))) return;
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Émission…'; }
  fetch('/api/clients/invoices/issue',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:parseInt(cid,10),notify:doNotify})})
    .then(function(r){return r.json();}).then(function(d){
      if(msg){
        msg.style.color=d.ok?'var(--green)':'var(--accent)';
        if(d.ok&&d.issued_count>0){
          var em = d.email_sent ? ' — client notifié par email' : (doNotify?(' — email non envoyé'+(d.email_error?' ('+d.email_error+')':'')):'');
          msg.textContent = d.issued_count+' facture(s) émise(s)'+em;
        } else if(d.ok){ msg.textContent = d.message||'Aucun jalon vérifié à facturer'; }
        else { msg.textContent = d.error||'Erreur'; }
      }
      if(d.ok){ raasInvoicesLoad(cid); if(window.raasAdminLoad) raasAdminLoad(); }
    }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur réseau.'; } });
};

/* ── VUE PORTEFEUILLE MULTICLIENT + SYNTHESE ── */
window.raasPortfolioToggle = function(){
  var box=document.getElementById('raas-portfolio'); if(!box) return;
  if(box.style.display==='block'){ box.style.display='none'; return; }
  box.style.display='block';
  box.innerHTML='<div style="color:var(--muted);font-size:12px;padding:10px">Chargement du portefeuille…</div>';
  fetch('/api/clients/portfolio',{credentials:'same-origin'})
    .then(function(r){return r.json();}).then(function(d){
      if(!d.ok){ box.innerHTML='<div style="color:var(--accent);font-size:12px;padding:10px">'+(d.error||'Erreur')+'</div>'; return; }
      function eur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
      var STAT={prospect:'Prospect',onboarding:'Onboarding',actif:'Actif',a_risque:'\u00c0 risque',inactif:'Inactif',clos:'Clos'};
      var SANTEC={a_evaluer:'var(--muted2)',bonne:'var(--green)',moyenne:'#c98a00',fragile:'var(--accent)'};
      function plabel(p){ var m={gratuit:'Gratuit',pro:'Pro',entreprise:'Entreprise'}; var cc={gratuit:'var(--muted2)',pro:'#6B46C1',entreprise:'#0E7C7B'}; var pl=p.plan||'gratuit'; return '<span style="font-size:11px;font-weight:600;color:'+(cc[pl]||'var(--muted)')+'">'+(m[pl]||pl)+'</span>'+(p.has_sub?' <span title="Abonnement Stripe actif" style="color:var(--green,#0E7C7B)">\u25CF</span>':''); }
      var t=d.totals||{};
      window.__raasPortfolio = {portfolio:d.portfolio, totals:t};
      var head =
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex-wrap:wrap;gap:8px">'
        + '<strong style="font-size:14px">Portefeuille clients ('+t.clients+')</strong>'
        + '<div style="display:flex;gap:8px;flex-wrap:wrap">'
        + '<button class="mat-export-btn" onclick="raasPortfolioExport()" title="Exporter le portefeuille en PDF imprimable">\ud83d\udcc4 Exporter (PDF)</button>'
        + '<button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="raasPortfolioDigest()">\u2709 Envoyer la synth\u00e8se de relance</button>'
        + '</div>'
        + '</div>'
        + '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:12px">'
        + '<div class="ms-sum-card"><div class="ms-sum-lbl">Impay\u00e9s</div><div class="ms-sum-val" style="color:'+(t.unpaid_count?'var(--accent)':'var(--green)')+'">'+eur(t.unpaid_amount)+'</div><div class="ms-sum-sub">'+t.unpaid_count+' facture(s)</div></div>'
        + '<div class="ms-sum-card"><div class="ms-sum-lbl">Relances en attente</div><div class="ms-sum-val">'+t.pending_relances+'</div><div class="ms-sum-sub">tous clients</div></div>'
        + '<div class="ms-sum-card"><div class="ms-sum-lbl">Clients suivis</div><div class="ms-sum-val">'+t.clients+'</div><div class="ms-sum-sub">au total</div></div>'
        + '</div><span id="pf-digest-msg" style="font-size:11px"></span>';
      var rows = d.portfolio.map(function(p){
        var col=SANTEC[p.sante]||'var(--muted2)';
        var alert = p.unpaid_amount>0 || p.pending_relances>0;
        return '<tr style="cursor:pointer" onclick="raasPortfolioOpen('+p.id+')">'
          + '<td><strong>'+String(p.nom).replace(/</g,"&lt;")+'</strong></td>'
          + '<td>'+plabel(p)+'</td>'
          + '<td>'+(STAT[p.statut]||p.statut)+'</td>'
          + '<td><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:'+col+'"></span></td>'
          + '<td class="ms-amount" style="color:'+(p.unpaid_amount?'var(--accent)':'inherit')+'">'+(p.unpaid_count?eur(p.unpaid_amount)+' ('+p.unpaid_count+')':'\u2014')+'</td>'
          + '<td style="text-align:center">'+(p.pending_relances||'\u2014')+'</td>'
          + '<td style="text-align:center">'+raasMsCell(p)+'</td>'
          + '<td style="text-align:center;font-size:10px">'+(p.last_contact_days!==null?p.last_contact_days+'j':'\u2014')+'</td>'
          + '</tr>';
      }).join('');
      box.innerHTML = head
        + '<table class="ms-table"><thead><tr><th>Client</th><th>Offre</th><th>Statut</th><th>Sant\u00e9</th><th>Impay\u00e9s</th><th>Relances</th><th>Jalons</th><th>Contact</th></tr></thead><tbody>'+rows+'</tbody></table>'
        + '<div style="font-size:10px;color:var(--muted2);margin-top:6px">Cliquez sur une ligne pour ouvrir le suivi d\u00e9taill\u00e9 du client.</div>';
    }).catch(function(){ box.innerHTML='<div style="color:var(--accent);font-size:12px;padding:10px">Erreur de chargement du portefeuille.</div>'; });
};

window.raasPortfolioOpen = function(clientId){
  var sel=document.getElementById('raas-client-select');
  if(sel){ sel.value=clientId; raasAdminLoad(); }
  var box=document.getElementById('raas-portfolio'); if(box) box.style.display='none';
};

window.raasPortfolioExport = function(){
  var pf = window.__raasPortfolio;
  if(!pf || !pf.portfolio){ alert('Ouvrez d\u2019abord la vue portefeuille.'); return; }
  function eur(n){ return (n||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
  var STAT={prospect:'Prospect',onboarding:'Onboarding',actif:'Actif',a_risque:'\u00c0 risque',inactif:'Inactif',clos:'Clos'};
  var SANTE={a_evaluer:'\u00c0 \u00e9valuer',bonne:'Bonne',moyenne:'Moyenne',fragile:'Fragile'};
  var t=pf.totals||{};
  var today=new Date().toLocaleDateString('fr-FR');
  var rows=pf.portfolio.map(function(p){
    return '<tr><td>'+String(p.nom).replace(/</g,'&lt;')+'</td><td>'+(STAT[p.statut]||p.statut)+'</td>'
      +'<td>'+(SANTE[p.sante]||p.sante)+'</td>'
      +'<td style="text-align:right">'+(p.unpaid_count?eur(p.unpaid_amount)+' ('+p.unpaid_count+')':'\u2014')+'</td>'
      +'<td style="text-align:center">'+(p.pending_relances||'\u2014')+'</td>'
      +'<td style="text-align:center">'+raasMsCell(p)+'</td>'
      +'<td style="text-align:center">'+(p.last_contact_days!==null?p.last_contact_days+' j':'\u2014')+'</td></tr>';
  }).join('');
  var html='<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Portefeuille clients \u2014 CONSEILPREV</title>'
    +'<style>@page{margin:1.5cm}body{font-family:Arial,sans-serif;color:#1C1C1C;max-width:960px;margin:0 auto;padding:16px}'
    +'h1{font-size:19px;border-bottom:3px solid #B83222;padding-bottom:8px;margin-bottom:4px}'
    +'.sub{color:#666;font-size:11px;margin-bottom:14px}'
    +'.kpis{display:flex;gap:14px;margin:12px 0}'
    +'.kpi{flex:1;border:1px solid #e5e2dd;border-radius:6px;padding:10px 12px}'
    +'.kpi b{display:block;font-size:17px}.kpi span{font-size:9px;text-transform:uppercase;letter-spacing:.06em;color:#888}'
    +'table{width:100%;border-collapse:collapse;font-size:11px;margin-top:8px}'
    +'th{background:#1C1C1C;color:#fff;padding:7px 9px;text-align:left;font-size:9.5px}'
    +'td{border:1px solid #ddd;padding:6px 9px}tbody tr:nth-child(even){background:#faf9f7}'
    +'.foot{font-size:9px;color:#999;margin-top:20px;border-top:1px solid #eee;padding-top:8px}'
    +'</style></head><body>'
    +'<h1>Portefeuille clients</h1>'
    +'<div class="sub">CONSEILPREV \u2014 Sentinel AI \u00b7 \u00c9tabli le '+today+' \u00b7 Document interne de suivi</div>'
    +'<div class="kpis">'
    +'<div class="kpi"><span>Clients suivis</span><b>'+t.clients+'</b></div>'
    +'<div class="kpi"><span>Impay\u00e9s</span><b>'+eur(t.unpaid_amount)+'</b>'+t.unpaid_count+' facture(s)</div>'
    +'<div class="kpi"><span>Relances en attente</span><b>'+t.pending_relances+'</b></div>'
    +'</div>'
    +'<table><thead><tr><th>Client</th><th>Statut</th><th>Sant\u00e9</th><th>Impay\u00e9s</th><th>Relances</th><th>Jalons</th><th>Dernier contact</th></tr></thead>'
    +'<tbody>'+rows+'</tbody></table>'
    +'<div class="foot">Document interne CONSEILPREV \u2014 donn\u00e9es de suivi client \u00e0 usage strictement interne. G\u00e9n\u00e9r\u00e9 par Sentinel AI.</div>'
    +'</body></html>';
  var w=window.open('','_blank');
  if(!w){ alert('Autorisez les pop-ups pour exporter.'); return; }
  w.document.write(html+'<scr'+'ipt>window.onload=function(){window.print();}<'+'/scr'+'ipt>');
  w.document.close();
};

window.raasPortfolioDigest = function(){
  var msg=document.getElementById('pf-digest-msg');
  if(!confirm('Envoyer par email \u00e0 CONSEILPREV la synth\u00e8se des impay\u00e9s et relances en attente ?')) return;
  if(msg){ msg.style.color='var(--muted)'; msg.textContent='Envoi…'; }
  fetch('/api/clients/portfolio/digest',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'})
    .then(function(r){return r.json();}).then(function(d){
      if(msg){
        msg.style.color=(d.ok&&d.email_sent)?'var(--green)':'var(--accent)';
        msg.textContent=(d.ok&&d.email_sent)?('Synth\u00e8se envoy\u00e9e \u00e0 '+d.to+' \u2014 '+d.unpaid_lines+' impay\u00e9(s), '+d.relance_lines+' relance(s)')
          :(d.ok?('Email non envoy\u00e9'+(d.email_error?' ('+d.email_error+')':'')):(d.error||'Erreur'));
      }
    }).catch(function(){ if(msg){ msg.style.color='var(--accent)'; msg.textContent='Erreur r\u00e9seau.'; } });
};

/* ── RGPD : information + droit a l'effacement ── */
window.raasRgpdBlock = function(clientId){
  return '<div style="margin-top:16px;padding-top:14px;border-top:1px solid var(--rule)">'
    + '<details style="font-size:11px;color:var(--ink2)"><summary style="cursor:pointer;font-weight:600;color:var(--ink)">Protection des donn\u00e9es (RGPD)</summary>'
    + '<div style="margin-top:8px;line-height:1.6">'
    + '<strong>Finalit\u00e9\u00a0:</strong> les donn\u00e9es KYC sont collect\u00e9es aux fins de gestion contractuelle, de facturation et de suivi de la relation client.<br>'
    + '<strong>Base l\u00e9gale\u00a0:</strong> ex\u00e9cution du contrat (art. 6.1.b RGPD) et respect d\u2019obligations l\u00e9gales comptables et fiscales (art. 6.1.c RGPD).<br>'
    + '<strong>Dur\u00e9e de conservation\u00a0:</strong> donn\u00e9es de suivi conserv\u00e9es pendant la relation contractuelle puis 3 ans \u00e0 des fins de prospection\u00a0; pi\u00e8ces comptables (factures, contrats) conserv\u00e9es 10 ans au titre de l\u2019article L.123-22 du Code de commerce.<br>'
    + '<strong>Droits\u00a0:</strong> le client dispose d\u2019un droit d\u2019acc\u00e8s, de rectification et d\u2019effacement (art. 15 \u00e0 17 RGPD).'
    + '<div style="margin-top:10px"><button class="mat-export-btn" style="background:var(--accent);color:#fff;padding:5px 12px;font-size:11px" onclick="raasRgpdErase('+clientId+')">Exercer le droit \u00e0 l\u2019effacement</button>'
    + '<span style="font-size:10px;color:var(--muted2);margin-left:8px">Supprime KYC, notes, relances et suivi\u00a0; anonymise les coordonn\u00e9es du compte. Factures et contrats conserv\u00e9s et pseudonymis\u00e9s (obligation l\u00e9gale 10 ans).</span></div>'
    + '</div></details></div>';
};

window.raasRgpdErase = function(clientId){
  if(!confirm('EFFACEMENT RGPD \u2014 supprimer les donn\u00e9es KYC, notes, relances et suivi, et anonymiser les coordonn\u00e9es nominatives du compte de ce client ?\n\nLes factures et contrats sont conserv\u00e9s (li\u00e9s par identifiant pseudonymis\u00e9) au titre de l\u2019obligation comptable l\u00e9gale de 10 ans. Le compte sera d\u00e9sactiv\u00e9. Cette action est irr\u00e9versible.')) return;
  if(!confirm('Confirmez-vous d\u00e9finitivement cet effacement ?')) return;
  fetch('/api/clients/erase',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:parseInt(clientId,10),confirm:true,anonymize:true})})
    .then(function(r){return r.json();}).then(function(d){
      if(d.ok){ alert('Effacement effectu\u00e9. '+(d.note||'')); raasExpertRender(clientId); }
      else { alert(d.error||'Erreur'); }
    }).catch(function(){ alert('Erreur r\u00e9seau.'); });
};

