      var m=docStatusMeta(r.statut);
      return '<tr>'
        + '<td class="doc-name">'+traitEsc(it[1])+'</td>'
        + '<td><span class="aipd-lvl" id="doc-badge-'+it[0]+'" style="background:'+m[2]+'">'+m[1]+'</span></td>'
