/* ══ Conformite RGPD — tableau de bord consolidant les briques ══ */
window.__confLoaded = false;
window.confOpen = function(pid){ var el=document.querySelector(".sb-item[onclick*=\"go('"+pid+"'\"]"); if(el) el.click(); };
window.confLoadOnce = function(){ if(window.__confLoaded) return; confLoad(); };
window.confLoad = function(){
  var box=document.getElementById("conf-body"); if(box) box.innerHTML='<div class="veille-loading">Consolidation des indicateurs…</div>';
  fetch("/api/rgpd/traitements",{credentials:"same-origin"}).then(function(r){ return r.json(); })
    .then(function(d){ window.TRAIT_DATA=(d&&d.traitements)?d.traitements:[]; window.__confLoaded=true; confRender(); })
    .catch(function(){ window.TRAIT_DATA=window.TRAIT_DATA||[]; window.__confLoaded=true; confRender(); });
};
window.confPbdPct = function(){ try { return pbdCounts().pct; } catch(e){ return 0; } };
window.confDocPct = function(){ try { return docCounts().pct; } catch(e){ return 0; } };
window.confSensPct = function(){ try { return sensCounts().pct; } catch(e){ return 0; } };
window.confAipdStats = function(){
  var list=window.TRAIT_DATA||[]; var requises=0, traitees=0, eleves=0;
  try {
    list.forEach(function(t){ var s=aipdGet(t.id); var req=aipdCritCount(t,s)>=2; if(req) requises++;
      var hasRisk=false; try { AIPD_EVENTS.forEach(function(e){ var ev=s.events[e[0]]; if(ev.g>1||ev.v>1) hasRisk=true; }); } catch(x){}
      if(req && hasRisk) traitees++; if(aipdRiskLevel(s)>=3) eleves++; });
  } catch(e){}
  return { requises:requises, traitees:traitees, eleves:eleves };
};
window.confRegPct = function(){
  var list=window.TRAIT_DATA||[]; if(!list.length) return 0;
  var champs=["finalites","base_legale","categories_personnes","categories_donnees","duree_conservation","mesures_securite"];
  var tot=0, ok=0;
  list.forEach(function(t){ champs.forEach(function(c){ tot++; if(((t[c]||"").trim())) ok++; }); });
  return tot? Math.round(ok/tot*100):0;
};

window.confRender = function(){
  var box=document.getElementById("conf-body"); if(!box) return;
  var list=window.TRAIT_DATA||[];
  var cnt=document.getElementById("conf-count"); if(cnt) cnt.textContent=list.length+" traitement(s) au registre";
  var reg=confRegPct(), pbd=confPbdPct(), doc=confDocPct(), sens=confSensPct();
  var aipd=confAipdStats();
  var aipdPct = aipd.requises? Math.round(aipd.traitees/aipd.requises*100) : 100;
  var axes=[
    ["Registre des traitements", reg, "Complétude des champs art. 30", "rgpd-traitements"],
    ["AIPD (art. 35)", aipdPct, aipd.requises+" AIPD requise(s), "+aipd.traitees+" évaluée(s)", "rgpd-aipd"],
    ["Privacy by design", pbd, "Contrôles art. 25 en place", "rgpd-pbd"],
    ["Documentation", doc, "Documents d'accountability en place", "rgpd-doc"],
    ["Sensibilisation", sens, "Actions réalisées", "rgpd-sensibilisation"]
  ];
  var global = Math.round(axes.reduce(function(a,x){ return a+x[1]; },0)/axes.length);
  var gcolor = global>=75? "var(--green)" : global>=50? "#c98a00" : "#c0392b";
  function bar(pct){ var c=pct>=75?"var(--green)":pct>=50?"#c98a00":"#c0392b"; return '<div class="ct-bar-track" style="flex:1"><div class="ct-bar-fill" style="width:'+pct+'%;background:'+c+'"></div></div>'; }
  var rows=axes.map(function(a){
    return '<div class="conf-axis"><div class="conf-axis-h"><button class="conf-axis-name" onclick="confOpen(\''+a[3]+'\')">'+a[0]+'</button><span class="conf-axis-pct">'+a[1]+' %</span></div>'
      + '<div style="display:flex;align-items:center;gap:10px">'+bar(a[1])+'</div>'
      + '<div class="conf-axis-d">'+a[2]+'</div></div>';
  }).join("");
  var alerts=[];
  if(!list.length) alerts.push("Aucun traitement au registre : commencez par le registre des traitements.");
  if(aipd.eleves>0) alerts.push(aipd.eleves+" traitement(s) à risque élevé selon l'AIPD : mesures à renforcer.");
  if(reg<70 && list.length) alerts.push("Le registre est incomplet : complétez les champs de l'article 30.");
  if(doc<50) alerts.push("La documentation d'accountability est partielle.");
  if(sens<50) alerts.push("Le plan de sensibilisation reste à réaliser en grande partie.");
  var alertsHtml = alerts.length ? '<ul class="conf-alerts">'+alerts.map(function(a){ return '<li>'+traitEsc(a)+'</li>'; }).join("")+'</ul>' : '<p class="ct-none">Aucun point d\'attention majeur détecté.</p>';
  box.innerHTML =
      '<div class="conf-global"><div class="conf-global-v" style="color:'+gcolor+'">'+global+' %</div><div class="conf-global-l">Indice de conformité consolidé</div></div>'
    + '<div class="conf-axes">'+rows+'</div>'
    + '<div class="ct-card ct-warn" style="margin-top:16px"><div class="ct-card-t">Points d\'attention</div>'+alertsHtml+'</div>';
};

window.confExportPdf = function(){
  var list=window.TRAIT_DATA||[]; var reg=confRegPct(), pbd=confPbdPct(), doc=confDocPct(), sens=confSensPct();
  var aipd=confAipdStats(); var aipdPct = aipd.requises? Math.round(aipd.traitees/aipd.requises*100) : 100;
  var axes=[["Registre des traitements",reg],["AIPD (art. 35)",aipdPct],["Privacy by design",pbd],["Documentation",doc],["Sensibilisation",sens]];
  var global=Math.round(axes.reduce(function(a,x){ return a+x[1]; },0)/axes.length);
  var today=new Date().toLocaleDateString("fr-FR");
  function esc(x){ return String(x==null?"":x).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
  var rows=axes.map(function(a){ return '<tr><td>'+esc(a[0])+'</td><td style="text-align:right">'+a[1]+' %</td></tr>'; }).join("");
  var html='<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Bilan de conformité RGPD</title>'
    +'<style>@page{margin:1.6cm}body{font-family:Arial,sans-serif;color:#1C1C1C;max-width:820px;margin:0 auto;padding:16px}'
    +'h1{font-size:19px;border-bottom:3px solid #6B46C1;padding-bottom:8px;margin-bottom:2px}.sub{color:#666;font-size:11px;margin-bottom:14px}'
    +'.g{font-size:34px;font-weight:700;color:#6B46C1;margin:10px 0}table{width:100%;border-collapse:collapse;font-size:12px;margin-top:8px}'
    +'td,th{border:1px solid #ddd;padding:6px 10px}th{background:#faf9f7;text-align:left}'
    +'.foot{font-size:9px;color:#999;margin-top:18px;border-top:1px solid #eee;padding-top:8px}</style></head><body>'
    +'<h1>Bilan de conformité RGPD</h1>'
    +'<div class="sub">CONSEILPREV — Sentinel · '+list.length+' traitement(s) · '+today+'</div>'
    +'<div class="g">'+global+' %</div><p style="font-size:11px;color:#666;margin-top:-6px">Indice consolidé (aide au pilotage)</p>'
    +'<table><thead><tr><th>Axe</th><th style="text-align:right">Niveau</th></tr></thead><tbody>'+rows+'</tbody></table>'
    +'<div class="foot">Aide au pilotage consolidant des éléments déclaratifs et le registre. Ne vaut pas attestation de conformité juridique. Généré par Sentinel — un audit approfondi est recommandé.</div>'
    +'</body></html>';
  var w=window.open("","_blank"); if(!w){ alert("Autorisez les pop-ups pour exporter."); return; }
  w.document.write(html+'<scr'+'ipt>window.onload=function(){window.print();}<'+'/scr'+'ipt>'); w.document.close();
};

