window.hubLoad = function(){
  var box=document.getElementById("hub-cards"); if(box) box.innerHTML='<div class="veille-loading">Chargement du dispositif…</div>';
  fetch("/api/rgpd/traitements",{credentials:"same-origin"}).then(function(r){ return r.json(); })
    .then(function(d){ window.TRAIT_DATA=(d&&d.traitements)?d.traitements:[]; window.__hubLoaded=true; hubRender(); })
    .catch(function(){ window.TRAIT_DATA=window.TRAIT_DATA||[]; window.__hubLoaded=true; hubRender(); });
};
window.hubPct = function(fnName){ try { return (typeof window[fnName]==="function") ? window[fnName]() : 0; } catch(e){ return 0; } };
window.hubRender = function(){
  var snap=document.getElementById("hub-snapshot");
  var reg=hubPct("confRegPct"), pbd=hubPct("confPbdPct"), doc=hubPct("confDocPct"), sens=hubPct("confSensPct");
  var aipd = (typeof confAipdStats==="function") ? confAipdStats() : {requises:0,traitees:0,eleves:0};
  var overall = Math.round((reg+pbd+doc+sens)/4);
  if(snap){
    function mini(v,l){ return '<div class="hub-mini"><div class="hub-mini-bar"><div class="hub-mini-fill" style="width:'+v+'%"></div></div><div class="hub-mini-l">'+l+' · '+v+'%</div></div>'; }
    snap.innerHTML='<div class="hub-snap">'
      + '<div class="hub-index"><div class="hub-index-v">'+overall+'%</div><div class="hub-index-l">Indice global<br>du dispositif</div></div>'
      + '<div class="hub-minis">'
      + mini(reg,"Registre (art. 30)")
      + mini(pbd,"Privacy by design")
      + mini(doc,"Documentation")
      + mini(sens,"Sensibilisation")
      + '</div></div>'
      + (aipd.eleves>0 ? '<div class="hub-alert">'+aipd.eleves+' traitement(s) à risque élevé identifié(s) dans l\'AIPD — consultez la page AIPD.</div>' : '');
  }
  var box=document.getElementById("hub-cards"); if(!box) return;
  box.innerHTML = HUB_BRICKS.map(function(g){
    var cards=g[1].map(function(b){
      return '<div class="hub-card" onclick="hubGo(\''+b[0]+'\')"><div class="hub-card-t">'+traitEsc(b[1])+'</div><div class="hub-card-d">'+traitEsc(b[2])+'</div><div class="hub-card-go">Ouvrir →</div></div>';
    }).join("");
    return '<div class="hub-group"><div class="hub-group-t">'+traitEsc(g[0])+'</div><div class="hub-grid">'+cards+'</div></div>';
  }).join("");
};

/* Navigation des parcours RGPD : reproduit le clic menu (go + init) */
["rgpd-hub","rgpd-traitements","rgpd-cartographie","rgpd-aipd","rgpd-pbd","rgpd-doc","rgpd-sensibilisation","rgpd-conformite"].forEach(function(pid){ window["gnav_"+pid]=function(){ if(typeof hubGo==="function"){ hubGo(pid); } else { go(pid); } }; });
/* Cellule portefeuille : jalons en attente par cadre (IA Act / RGPD) */
window.raasMsCell = function(p){
  if(p.milestones_pending_ai===undefined && p.milestones_pending_rgpd===undefined && p.milestones_pending_iso===undefined) return (p.milestones_pending||'\u2014');
  var a=p.milestones_pending_ai||0, r=p.milestones_pending_rgpd||0, i=p.milestones_pending_iso||0;
  if(!(a+r+i)) return '\u2014';
  var parts=[a+' IA'];
  if(r) parts.push('<span style="color:#6B46C1">'+r+' RGPD</span>');
  if(i) parts.push('<span style="color:#0E7C7B">'+i+' ISO</span>');
  return parts.join(' \u00b7 ');
};
/* ══ Indice de conformité global — consolide IA Act / RGPD / ISO 42001 ══ */
window.gcAuditPct = function(){
  try{
    if(!window.AUDIT_SECTIONS) return null;
    var tot=0, done=0;
    window.AUDIT_SECTIONS.forEach(function(sec){ (sec.items||[]).forEach(function(it){ tot++; var st=(window.AUDIT_STATE&&window.AUDIT_STATE[it.id])||'none'; if(st==='done') done++; }); });
    return tot? Math.round(done/tot*100) : 0;
  }catch(e){ return null; }
};
window.gcRgpdPct = function(){
  try{
    var fns=['confRegPct','confPbdPct','confDocPct','confSensPct'];
    var ok=fns.filter(function(f){ return typeof window[f]==='function'; });
    if(!ok.length) return null;
    var v=fns.map(function(f){ return (typeof window[f]==='function')?(window[f]()||0):0; });
    return Math.round(v.reduce(function(a,b){return a+b;},0)/v.length);
  }catch(e){ return null; }
};
window.gcIsoPct = function(){
  try{
    if(typeof window.matGlobalScore!=='function') return null;
    var sec = window.MAT_CUR || (window.MAT_SECTORS ? Object.keys(window.MAT_SECTORS)[0] : null);
    var s = window.matGlobalScore(sec); // échelle 0–4
    if(typeof s!=='number' || isNaN(s)) return null;
    return Math.max(0, Math.min(100, Math.round((s/4)*100)));
  }catch(e){ return null; }
};
window.gcLoad = function(){ gcRender(); };
window.gcRender = function(){
  var box=document.getElementById('gc-body'); if(!box) return;
  var ia=gcAuditPct(), rg=gcRgpdPct(), iso=gcIsoPct();
  function col(v){ return v==null?'var(--muted2)':(v<50?'#c0392b':(v<75?'#c98a00':'var(--green)')); }
  function txt(v){ return v==null?'—':v+'%'; }
  var vals=[ia,rg,iso].filter(function(x){ return x!==null; });
  var g = vals.length ? Math.round(vals.reduce(function(a,b){return a+b;},0)/vals.length) : null;
  function fw(name, sub, v, target){
    return '<div class="gc-fw" onclick="hubGo(\''+target+'\')">'
      + '<div class="gc-fw-top"><span class="gc-fw-name">'+name+'</span><span class="gc-fw-val" style="color:'+col(v)+'">'+txt(v)+'</span></div>'
      + '<div class="gc-fw-sub">'+sub+'</div>'
      + '<div class="gc-bar"><div class="gc-bar-fill" style="width:'+(v==null?0:v)+'%;background:'+col(v)+'"></div></div>'
      + '<div class="gc-fw-go">Ouvrir \u2192</div></div>';
  }
  box.innerHTML =
      '<div class="gc-hero">'
    + '<div class="gc-hero-num" style="color:'+col(g)+'">'+txt(g)+'</div>'
    + '<div class="gc-hero-right"><div class="gc-hero-l">Indice de conformité global</div>'
    + '<div class="gc-hero-s">Moyenne des cadres évalués'+(vals.length<3?' ('+vals.length+'/3 renseigné(s))':'')+'</div>'
    + '<div class="gc-hero-bar"><div class="gc-hero-fill" style="width:'+(g==null?0:g)+'%;background:'+col(g)+'"></div></div></div>'
    + '</div>'
    + '<div class="gc-grid">'
    + fw('Règlement IA', 'Avancement de l\'Audit IA Act', ia, 'audit-ia-act')
    + fw('RGPD', 'Conformité RGPD consolidée', rg, 'rgpd-conformite')
    + fw('ISO/IEC 42001', 'Estimé via l\'audit de maturité', iso, 'maturite')
    + '</div>';
};

