window.__iahLoaded = false;
window.iahLoadOnce = function(){ if(window.__iahLoaded) return; window.__iahLoaded=true; iahRender(); };
window.iahLoad = function(){ iahRender(); };
window.iahRender = function(){
  var snap=document.getElementById("iah-snapshot");
  var ia = (typeof gcAuditPct==="function") ? gcAuditPct() : null;
  var mat = (typeof gcIsoPct==="function") ? gcIsoPct() : null;
  function col(v){ return v==null?"var(--muted2)":(v<50?"#c0392b":(v<75?"#c98a00":"var(--green)")); }
  function txt(v){ return v==null?"—":v+"%"; }
  if(snap){
    function mini(v,l){ return '<div class="hub-mini"><div class="hub-mini-bar"><div class="hub-mini-fill" style="width:'+(v==null?0:v)+'%;background:'+col(v)+'"></div></div><div class="hub-mini-l">'+l+' · '+txt(v)+'</div></div>'; }
    snap.innerHTML='<div class="hub-snap">'
      + '<div class="hub-index"><div class="hub-index-v" style="color:'+col(ia)+'">'+txt(ia)+'</div><div class="hub-index-l">Avancement<br>Audit IA Act</div></div>'
      + '<div class="hub-minis">'+mini(ia,"Audit IA Act")+mini(mat,"Maturité / ISO 42001")+'</div></div>';
  }
  var box=document.getElementById("iah-cards"); if(!box) return;
  box.innerHTML = IA_HUB_BRICKS.map(function(g){
    var cards=g[1].map(function(b){
      return '<div class="hub-card" onclick="hubGo(\''+b[0]+'\')"><div class="hub-card-t">'+traitEsc(b[1])+'</div><div class="hub-card-d">'+traitEsc(b[2])+'</div><div class="hub-card-go">Ouvrir →</div></div>';
    }).join("");
    return '<div class="hub-group"><div class="hub-group-t">'+traitEsc(g[0])+'</div><div class="hub-grid">'+cards+'</div></div>';
  }).join("");
};

/* Ouverture directe d'une page via ?goto= (ex. redirection depuis la connexion vers la tarification) */
window.sentinelGotoDeepLink = function(){ try{ var g=new URLSearchParams(location.search).get('goto'); if(g){ setTimeout(function(){ if(typeof hubGo==='function') hubGo(g); else if(typeof go==='function') go(g); }, 350); } }catch(e){} };
if(document.readyState==='complete') window.sentinelGotoDeepLink(); else window.addEventListener('load', window.sentinelGotoDeepLink);
/* ══ Cycle de facturation échelonnée — prélèvements Stripe (Gestion des clients) ══ */
window.billingRenderList = function(out, list){
  if(!out) return;
  if(!list || !list.length){ out.innerHTML = '<div style="padding:12px;color:var(--muted);font-size:12px">Aucune échéance due.</div>'; return; }
  var rows = list.map(function(e){
    return '<tr><td style="padding:6px 8px;border-bottom:1px solid var(--rule)">'+(e.numero||'')+'</td><td style="padding:6px 8px;border-bottom:1px solid var(--rule);text-align:center">#'+(e.echeance||'')+'</td><td style="padding:6px 8px;border-bottom:1px solid var(--rule);text-align:right">'+(e.montant||0)+' €</td><td style="padding:6px 8px;border-bottom:1px solid var(--rule)">'+(e.due||'')+'</td><td style="padding:6px 8px;border-bottom:1px solid var(--rule)">client '+(e.client_id||'')+'</td></tr>';
  }).join('');
  out.innerHTML = '<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr><th style="text-align:left;padding:6px 8px;color:var(--muted);font-size:10px;text-transform:uppercase">Facture</th><th style="padding:6px 8px;color:var(--muted);font-size:10px">Éch.</th><th style="padding:6px 8px;color:var(--muted);font-size:10px;text-align:right">Montant</th><th style="text-align:left;padding:6px 8px;color:var(--muted);font-size:10px">Échéance</th><th style="text-align:left;padding:6px 8px;color:var(--muted);font-size:10px">Client</th></tr></thead><tbody>'+rows+'</tbody></table>';
};
window.billingRenderResults = function(out, list){
  if(!out) return;
  if(!list || !list.length){ out.innerHTML = '<div style="padding:12px;color:var(--muted);font-size:12px">Aucune échéance traitée.</div>'; return; }
  var rows = list.map(function(e){
    var col = e.ok ? 'var(--green,#0E7C7B)' : 'var(--accent)';
    var txt = e.ok ? 'Prélèvement émis' : (e.error || 'Échec');
    return '<tr><td style="padding:6px 8px;border-bottom:1px solid var(--rule)">'+(e.numero||'')+'</td><td style="padding:6px 8px;border-bottom:1px solid var(--rule);text-align:center">#'+(e.echeance||'')+'</td><td style="padding:6px 8px;border-bottom:1px solid var(--rule);color:'+col+'">'+txt+'</td></tr>';
  }).join('');
  out.innerHTML = '<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr><th style="text-align:left;padding:6px 8px;color:var(--muted);font-size:10px;text-transform:uppercase">Facture</th><th style="padding:6px 8px;color:var(--muted);font-size:10px">Éch.</th><th style="text-align:left;padding:6px 8px;color:var(--muted);font-size:10px">Résultat</th></tr></thead><tbody>'+rows+'</tbody></table>';
};
window.billingRunPreview = function(){
  var msg = document.getElementById('billing-run-msg');
  var out = document.getElementById('billing-run-out');
  if(msg) msg.textContent = 'Chargement…';
  fetch('/api/clients/billing-run', {method:'POST', credentials:'same-origin', headers:{'Content-Type':'application/json'}, body:JSON.stringify({mode:'preview'})})
    .then(function(r){ return r.json(); })
    .then(function(d){
      if(!d || !d.ok){ if(msg) msg.innerHTML = '<span style="color:var(--accent)">'+((d&&d.error)||'Erreur')+'</span>'; return; }
      if(msg) msg.textContent = d.due_count + ' échéance(s) due(s) à ce jour.';
      billingRenderList(out, d.echeances);
    })
    .catch(function(){ if(msg) msg.textContent = 'Erreur réseau.'; });
};
window.billingRunExecute = function(){
  if(!window.confirm('Déclencher les prélèvements Stripe pour toutes les échéances dues ? Cette action prélève réellement les clients.')) return;
  var msg = document.getElementById('billing-run-msg');
  var out = document.getElementById('billing-run-out');
  if(msg) msg.textContent = 'Traitement…';
  fetch('/api/clients/billing-run', {method:'POST', credentials:'same-origin', headers:{'Content-Type':'application/json'}, body:JSON.stringify({mode:'execute', confirm:true})})
    .then(function(r){ return r.json().then(function(j){ return {status:r.status, j:j}; }).catch(function(){ return {status:r.status, j:{}}; }); })
    .then(function(res){
      var d = res.j || {};
      if(!d.ok){
        if(res.status === 501){ if(msg) msg.innerHTML = '<span style="color:var(--accent)">Stripe n\u2019est pas encore configuré : aucun prélèvement effectué.</span>'; if(out) billingRenderList(out, d.echeances); }
        else if(msg){ msg.innerHTML = '<span style="color:var(--accent)">'+(d.error||'Erreur')+'</span>'; }
        return;
      }
      var _rem = d.remaining || 0;
      if(msg) msg.textContent = (d.processed ? d.processed.length : 0) + ' échéance(s) traitée(s)' + (_rem > 0 ? ' — ' + _rem + ' restante(s), relancez pour continuer.' : '.');
      billingRenderResults(out, d.processed);
    })
    .catch(function(){ if(msg) msg.textContent = 'Erreur réseau.'; });
};

window.__caeCid = null;
window.clientEntApercu = function(cid){
  var box = document.getElementById('client-ent-apercu'); if(!box) return;
  window.__caeCid = cid;
  fetch('/api/clients/entreprise-apercu?client_id='+encodeURIComponent(cid), {credentials:'same-origin'})
    .then(function(r){ return r.json(); })
    .then(function(d){
      if(!d || !d.ok){ box.innerHTML = ''; return; }
      var SC = {operationnel:'var(--green,#0E7C7B)', echec:'var(--accent)', non_teste:'var(--muted)'};
      var SL = {operationnel:'op\u00e9rationnel', echec:'\u00e9chec', non_teste:'non test\u00e9'};
      var inp = 'font-size:11px;padding:5px 7px;border:1px solid var(--rule2);border-radius:4px';
      var lnk = 'font-size:10px;background:none;border:none;cursor:pointer';
      var addb = inp + ';cursor:pointer;background:var(--ink,#111827);color:#fff;border:none';
      var h = '<div style="border:1px solid var(--rule2);border-radius:10px;padding:12px 14px;background:var(--white)"><div style="font-weight:700;font-size:12px;margin-bottom:6px">P\u00e9rim\u00e8tre Entreprise \u2014 gestion</div>';
      h += '<div style="font-weight:600;font-size:11px;color:var(--ink);margin:8px 0 3px 0">Entit\u00e9s ('+(d.entites||[]).length+')</div>';
      h += (d.entites||[]).map(function(e){ return '<div style="display:flex;justify-content:space-between;font-size:11px;padding:2px 0"><span style="color:var(--muted)">'+String(e.nom).replace(/</g,"&lt;")+' \u00b7 '+String(e.type).replace(/</g,"&lt;")+'</span><button onclick="caeDelEntite('+e.id+')" style="'+lnk+';color:var(--accent)">Retirer</button></div>'; }).join('');
      h += '<div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:4px"><input id="cae-ent-nom" placeholder="Nom" style="'+inp+';flex:1;min-width:80px"><select id="cae-ent-type" style="'+inp+'"><option>Filiale</option><option>Groupe</option><option>P\u00e9rim\u00e8tre</option><option>Site</option></select><button onclick="caeAddEntite()" title="Ajouter une entit\u00e9" style="'+addb+'">+</button></div>';
      h += '<div style="font-weight:600;font-size:11px;color:var(--ink);margin:10px 0 3px 0">Connecteurs ('+(d.connecteurs||[]).length+')</div>';
      h += (d.connecteurs||[]).map(function(c){ return '<div style="padding:2px 0;font-size:11px"><div style="display:flex;justify-content:space-between"><span style="color:var(--muted)">'+String(c.categorie).replace(/</g,"&lt;")+' \u00b7 '+String(c.nom||'').replace(/</g,"&lt;")+'</span><span style="color:'+(SC[c.statut]||'var(--muted)')+'">'+(SL[c.statut]||String(c.statut||'').replace(/</g,"&lt;"))+'</span></div><div style="display:flex;gap:8px;margin-top:1px"><button onclick="caeTestConn('+c.id+')" style="'+lnk+';color:var(--ink);text-decoration:underline">Tester</button><button onclick="caeSyncConn('+c.id+',\''+c.categorie+'\')" style="'+lnk+';color:var(--ink);text-decoration:underline">Synchroniser</button><button onclick="caeDelConn('+c.id+')" style="'+lnk+';color:var(--accent)">Retirer</button></div></div>'; }).join('');
      h += '<div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:4px"><select id="cae-conn-cat" style="'+inp+'"><option>GRC</option><option>ERP</option><option>ITSM</option></select><input id="cae-conn-nom" placeholder="Nom" style="'+inp+';flex:1;min-width:60px"><input id="cae-conn-url" placeholder="https://..." style="'+inp+';flex:1;min-width:90px"><input id="cae-conn-sec" placeholder="Jeton" style="'+inp+';width:60px"><button onclick="caeAddConn()" title="Ajouter un connecteur" style="'+addb+'">+</button></div><div id="cae-conn-msg" style="font-size:10px;color:var(--accent);margin-top:2px"></div>';
      h += '<div style="font-weight:600;font-size:11px;color:var(--ink);margin:10px 0 3px 0">Formations ('+(d.formations||[]).length+')</div>';
      h += (d.formations||[]).map(function(f){ return '<div style="display:flex;justify-content:space-between;font-size:11px;padding:2px 0"><span style="color:var(--muted)">'+String(f.date_prevue).replace(/</g,"&lt;")+' \u00b7 '+String(f.theme||'').replace(/</g,"&lt;")+'</span><button onclick="caeDelForm('+f.id+')" style="'+lnk+';color:var(--accent)">Retirer</button></div>'; }).join('');
      h += '<div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:4px"><input id="cae-form-date" type="date" style="'+inp+'"><input id="cae-form-theme" placeholder="Th\u00e8me" style="'+inp+';flex:1;min-width:70px"><button onclick="caeAddForm()" title="Planifier une session" style="'+addb+'">+</button></div>';
      h += '</div>';
      box.innerHTML = h;
    })
    .catch(function(){ if(box) box.innerHTML = ''; });
};
function _caeRefresh(){ if(window.__caeCid) window.clientEntApercu(window.__caeCid); }
window.caeAddEntite = function(){
  var cid=window.__caeCid, n=document.getElementById('cae-ent-nom'), t=document.getElementById('cae-ent-type');
  if(!cid||!n||!n.value.trim()) return;
  fetch('/api/entreprise/entites', {method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:cid,nom:n.value.trim(),type:(t?t.value:'Filiale')})}).then(function(){ _caeRefresh(); }).catch(function(){});
};
window.caeDelEntite = function(id){ var cid=window.__caeCid; fetch('/api/entreprise/entites/'+id+'?client_id='+encodeURIComponent(cid),{method:'DELETE',credentials:'same-origin'}).then(function(){ _caeRefresh(); }).catch(function(){}); };
window.caeAddConn = function(){
  var cid=window.__caeCid, cat=document.getElementById('cae-conn-cat'), nom=document.getElementById('cae-conn-nom'), url=document.getElementById('cae-conn-url'), sec=document.getElementById('cae-conn-sec'), msg=document.getElementById('cae-conn-msg');
  if(!cid||!url||!url.value.trim()){ if(msg) msg.textContent='URL HTTPS requise.'; return; }
  fetch('/api/entreprise/connecteurs', {method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:cid,categorie:(cat?cat.value:'GRC'),nom:(nom?nom.value.trim():''),url:url.value.trim(),secret:(sec?sec.value.trim():'')})}).then(function(r){return r.json();}).then(function(d){ if(d&&d.ok){ _caeRefresh(); } else if(msg){ msg.textContent=(d&&d.error)||'Erreur'; } }).catch(function(){});
};
window.caeDelConn = function(id){ var cid=window.__caeCid; fetch('/api/entreprise/connecteurs/'+id+'?client_id='+encodeURIComponent(cid),{method:'DELETE',credentials:'same-origin'}).then(function(){ _caeRefresh(); }).catch(function(){}); };
window.caeTestConn = function(id){ var cid=window.__caeCid; fetch('/api/entreprise/connecteurs/'+id+'/test?client_id='+encodeURIComponent(cid),{method:'POST',credentials:'same-origin'}).then(function(){ _caeRefresh(); }).catch(function(){}); };
window.caeSyncConn = function(id, cat){
  var cid=window.__caeCid;
  function pct(fn){ try { var v=(typeof window[fn]==='function')?window[fn]():null; return (typeof v==='number'&&!isNaN(v))?Math.round(v):null; } catch(e){ return null; } }
  var body; if(cat==='GRC'){ body={type:'compliance_snapshot',indices:{ia_act:pct('gcAuditPct'),rgpd:pct('gcRgpdPct'),iso42001:pct('gcIsoPct')}}; } else if(cat==='ITSM'){ body={type:'compliance_ticket',titre:'Suivi de conformit\u00e9 IA Act'}; } else { body={type:'governance_context'}; }
  fetch('/api/entreprise/connecteurs/'+id+'/sync?client_id='+encodeURIComponent(cid),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(){ _caeRefresh(); }).catch(function(){});
};
