  var body;
  if(cat==='GRC'){ body = { type:'compliance_snapshot', indices:{ ia_act:pct('gcAuditPct'), rgpd:pct('gcRgpdPct'), iso42001:pct('gcIsoPct') } }; }
  else if(cat==='ITSM'){ body = { type:'compliance_ticket', titre:'Suivi de conformit\u00e9 IA Act', description:'Point de conformit\u00e9 transmis depuis Sentinel.' }; }
