      + row(['<strong>P\u00e9rim\u00e8tre op\u00e9rationnel</strong>', esc(h.perimetre.operationnel)])
      + row(['<strong>H\u00e9bergement</strong>', esc(h.perimetre.hebergement)])
      + row(['<strong>Fournisseurs de mod\u00e8les</strong>', esc(h.perimetre.fournisseurs_modeles)])
