window.__rgpdTimer = null;
window.rgpdAutoToggle = function(){
  var el = document.getElementById('rgpd-auto');
  if(el && el.checked){ window.rgpdAutoStart(); } else { window.rgpdAutoStop(); }
};
window.rgpdAutoStart = function(){
  window.rgpdAutoStop();
  /* Recalcul periodique tant que la page RGPD est affichee : le taux reflete
     en continu l'etat reel (preuves deposees, retraits, controles). */
  window.__rgpdTimer = setInterval(function(){
    var on = document.querySelector('.page.on');
    if(!on || on.id !== 'p-rgpd-site'){ window.rgpdAutoStop(); return; }
    if(document.hidden) return;
    window.rgpdChecks();
  }, 30000);
};
window.rgpdAutoStop = function(){
  if(window.__rgpdTimer){ clearInterval(window.__rgpdTimer); window.__rgpdTimer = null; }
};
