window.__veille = {data:null, ts:0, loading:false, regs:[], timer:null};
window.veilleInit = function(containerId, updId, filter){
  window.__veille.regs.push({id:containerId, upd:updId, filter:filter||{}});
  veilleEnsureLoaded(false);
  var r=window.__veille.regs[window.__veille.regs.length-1]; veilleRenderOne(r);
  if(!window.__veille.timer){ window.__veille.timer=setInterval(function(){ veilleEnsureLoaded(false); }, 600000); }
};
window.veilleEnsureLoaded = function(force){
  var v=window.__veille, now=Date.now();
  if(!force && v.data && (now - v.ts < 300000)) return;
  if(v.loading) return; v.loading=true;
  fetch('/api/veille'+(force?'?refresh=1':''), {credentials:'same-origin'})
    .then(function(r){ return r.json(); })
    .then(function(d){ v.data=d; v.ts=Date.now(); v.loading=false; v.regs.forEach(veilleRenderOne); })
    .catch(function(){ v.loading=false; v.regs.forEach(function(r){ var b=document.getElementById(r.id); if(b && !v.data) b.innerHTML='<div class=\"veille-empty\">Veille momentan\u00e9ment indisponible. R\u00e9essayez plus tard.</div>'; }); });
};
window.veilleRefresh = function(){ veilleEnsureLoaded(true); };
window.veilleRenderOne = function(reg){
  var box=document.getElementById(reg.id); if(!box) return;
  var d=window.__veille.data;
  function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;'); }
  function fdate(iso){ if(!iso) return ''; var x=new Date(iso); if(isNaN(x.getTime())) return ''; return x.toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'numeric'}); }
  if(!d){ box.innerHTML='<div class=\"veille-loading\">Chargement de la veille\u2026</div>'; return; }
  if(!d.ok || !d.items || !d.items.length){ box.innerHTML='<div class=\"veille-empty\">Aucune actualit\u00e9 disponible pour le moment.</div>'; return; }
  var items=d.items.filter(function(it){
    if(reg.filter.theme && it.theme!==reg.filter.theme) return false;
    if(reg.filter.jur && it.jur!==reg.filter.jur) return false;
    return true;
  });
  if(reg.filter.max) items=items.slice(0, reg.filter.max);
  if(!items.length){ box.innerHTML='<div class=\"veille-empty\">Aucune actualit\u00e9 correspondante.</div>'; return; }
  box.innerHTML = items.map(function(it){
    var dt=fdate(it.date);
    return '<a class=\"veille-item\" href=\"'+esc(it.link)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'
      + '<div class=\"veille-item-top\"><span class=\"veille-chip vj\">'+esc(it.jur)+'</span>'
      + '<span class=\"veille-chip vt\">'+esc(it.theme)+'</span>'
      + (dt?'<span class=\"veille-date\">'+dt+'</span>':'')+'</div>'
      + '<div class=\"veille-item-title\">'+esc(it.title)+'</div>'
      + (it.summary?'<div class=\"veille-item-sum\">'+esc(it.summary)+'</div>':'')
      + '<div class=\"veille-item-src\">'+esc(it.source)+'</div>'
      + '</a>';
  }).join('');
  var upd=document.getElementById(reg.upd);
  if(upd && d.updated_at){ var u=new Date(d.updated_at); if(!isNaN(u.getTime())) upd.textContent='Mise \u00e0 jour : '+u.toLocaleString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}); }
};
