    +'.big{font-size:15px;font-weight:bold;margin:10px 0}'
    +'table{width:100%;border-collapse:collapse;font-size:11px;margin-top:6px}'
    +'th{background:#1C1C1C;color:#fff;padding:6px 8px;text-align:left;font-size:9px}'
    +'td{border:1px solid #ddd;padding:5px 8px}tbody tr:nth-child(even){background:#faf9f7}'
    +'ul{font-size:11px;line-height:1.6}.foot{font-size:9px;color:#999;margin-top:18px;border-top:1px solid #eee;padding-top:8px}</style></head><body>'
    +'<h1>Diagnostic de maturité data et compétences techniques</h1>'
    +'<div class="sub">CONSEILPREV \u2014 Sentinel AI \u00b7 Secteur : '+sec+' \u00b7 Établi le '+today+'</div>'
    +'<div class="big">Indice de maturité global : '+g.toFixed(2)+'/5 \u2014 '+niv.label+'</div>'
