if(!window.__mpBuilder) window.__mpBuilder = MP_MODULES.map(function(m,i){ return {id:m.id, on:(m.id==='carto-uc'||m.id==='pricing'||m.id==='__synthese')}; });

window.monParcoursBuilder = function(){
  var modal=document.getElementById('mp-builder-modal');
  if(!modal){ modal=document.createElement('div'); modal.id='mp-builder-modal'; modal.className='mat-modal'; document.body.appendChild(modal); }
  modal.innerHTML='<div class="mat-modal-card" style="max-width:600px">'
    + '<div class="mat-modal-head"><div><div class="mat-modal-eyebrow">Mon parcours chiffré</div><div class="mat-modal-title">Composer mon parcours</div></div>'
    + '<button class="mat-modal-close" onclick="mpBuilderClose()">×</button></div>'
    + '<p style="font-size:12.5px;color:var(--muted);margin:0 0 14px;line-height:1.6">Cochez les modules à inclure et ordonnez-les. Le parcours vous guidera d\u2019un module à l\u2019autre jusqu\u2019au coût et à la synthèse.</p>'
    + '<div id="mp-builder-list"></div>'
    /* Onze modules dépassent la hauteur de la fenêtre : sans barre collée en
       bas, « Lancer mon parcours » se trouve sous le pli et le compositeur
       paraît sans issue. */
    + '<div class="mp-builder-actions">'
    + '<button class="mat-export-btn" onclick="mpBuilderClose()">Annuler</button>'
    + '<button class="mat-export-btn" style="background:var(--accent);color:var(--ink);font-weight:700" onclick="mpBuilderLaunch()">\ud83e\udded Lancer mon parcours \u2192</button>'
    + '</div></div>';
  modal.classList.add('on');
  mpBuilderRender();
};
window.mpBuilderRender = function(){
  var box=document.getElementById('mp-builder-list'); if(!box) return;
  box.innerHTML = window.__mpBuilder.map(function(row,idx){
    var m=MP_MODULES.filter(function(x){return x.id===row.id;})[0]; if(!m) return '';
    return '<div class="mp-row">'
      + '<label class="mp-check"><input type="checkbox" '+(row.on?'checked':'')+' onchange="mpBuilderToggle('+idx+')"><span></span></label>'
      + '<div class="mp-row-txt"><strong>'+(idx+1)+'. '+m.label+'</strong><span>'+m.desc+'</span></div>'
      + '<div class="mp-row-move"><button onclick="mpBuilderMove('+idx+',-1)" title="Monter" '+(idx===0?'disabled':'')+'>\u2191</button>'
      + '<button onclick="mpBuilderMove('+idx+',1)" title="Descendre" '+(idx===window.__mpBuilder.length-1?'disabled':'')+'>\u2193</button></div>'
      + '</div>';
  }).join('');
};
window.mpBuilderToggle = function(idx){ window.__mpBuilder[idx].on = !window.__mpBuilder[idx].on; };
window.mpBuilderMove = function(idx, dir){
  var a=window.__mpBuilder; var j=idx+dir; if(j<0||j>=a.length) return;
  var t=a[idx]; a[idx]=a[j]; a[j]=t; mpBuilderRender();
};
window.mpBuilderClose = function(){ var m=document.getElementById('mp-builder-modal'); if(m) m.classList.remove('on'); };
window.mpBuilderLaunch = function(){
  var chosen = window.__mpBuilder.filter(function(r){return r.on;});
  if(!chosen.length){ alert('Sélectionnez au moins un module.'); return; }
  var steps = chosen.map(function(r){ var m=MP_MODULES.filter(function(x){return x.id===r.id;})[0]; var s={id:m.id, label:m.label, action:m.action, gain:m.gain, tip:m.tip}; if(m.go) s.go=m.go; return s; });
  window.__monParcours = {id:'mon-parcours', icon:'\ud83e\udded', role:'Mon parcours chiffré', pitch:'Parcours composé sur mesure : '+steps.length+' étape(s).', steps:steps};
  mpBuilderClose();
  guidedStartStep('mon-parcours', 0);
};

window.mpSyntheseClose = function(){ var m=document.getElementById('mp-synthese-modal'); if(m) m.classList.remove('on'); };
window.monParcoursSyntheseShow = function(){
  var list = (typeof cartoSelectedList==='function') ? cartoSelectedList() : [];
  function eur(n){ return (Math.round(n)||0).toLocaleString('fr-FR')+'\u202f\u20ac'; }
  var n=list.length, gain=0, invest=0, net=0;
  list.forEach(function(u){ var r=cartoRoiOf(cartoKey(u),u); var c=cartoRoiCompute(r); gain+=c.gainAnnuel; invest+=(r.setup+r.run); net+=c.netAn1; });
  var roi = invest>0 ? (net/invest*100) : 0;
  var coutAnnuel=0;
  try{
    var nb=parseInt((document.getElementById('pricing-nb-systemes')||{}).value,10)|| n || 1;
    var sector=(document.getElementById('pricing-secteur')||{}).value||'';
    var segment=(document.getElementById('pricing-segment')||{}).value || window.__pricingSegment || 'pme';
    var billing=window.__pricingBilling || 'monthly';
    if(typeof pricingComputeSaaS==='function'){
      var res=pricingComputeSaaS(nb, sector, billing, segment);
      var mensuel=(typeof res==='number')?res:(res&&res.total?res.total:0);
      coutAnnuel=mensuel*12;
    }
  }catch(e){}
  var ratio = coutAnnuel>0 ? (gain/coutAnnuel) : 0;
  function card(t,v,s){ return '<div class="mp-syn-card"><div class="mp-syn-v">'+v+'</div><div class="mp-syn-t">'+t+'</div><div class="mp-syn-s">'+s+'</div></div>'; }
  var modal=document.getElementById('mp-synthese-modal');
  if(!modal){ modal=document.createElement('div'); modal.id='mp-synthese-modal'; modal.className='mat-modal'; document.body.appendChild(modal); }
  modal.innerHTML='<div class="mat-modal-card" style="max-width:600px">'
    + '<div class="mat-modal-head"><div><div class="mat-modal-eyebrow">Mon parcours chiffré</div><div class="mat-modal-title">Synthèse coût &amp; valeur</div></div>'
    + '<button class="mat-modal-close" onclick="mpSyntheseClose()">×</button></div>'
    + '<div class="mp-syn-grid">'
    + card('Cas d\u2019usage', n+'', 'retenus')
    + card('Gain annuel estimé', eur(gain), 'cumulé')
    + card('Coût accompagnement / an', coutAnnuel>0?eur(coutAnnuel):'\u2014', 'estimation SaaS')
    + card('Retour net année 1', eur(net), 'gain − coûts internes')
    + card('ROI année 1', Math.round(roi)+' %', 'sur coûts internes')
    + card('Gain / coût', ratio>0?(ratio.toFixed(1)+'\u00d7'):'\u2014', 'gain vs accompagnement')
    + '</div>'
    + '<div class="mp-syn-note">Estimations de cadrage à valider avec CONSEILPREV et votre direction financière avant tout engagement.</div>'
    + '<div style="text-align:right;margin-top:14px"><button class="mat-export-btn" style="background:var(--ink);color:#fff" onclick="mpSyntheseClose()">Fermer</button></div>'
    + '</div>';
  modal.classList.add('on');
};

window.guidedRenderBanner = function(){
  var b = document.getElementById('guided-banner');
  if(!b){ b = document.createElement('div'); b.id = 'guided-banner'; b.className = 'guided-banner'; document.body.appendChild(b); }
  var g = window.__activeGuided;
  if(!g){ b.style.display = 'none'; return; }
  var path = guidedFindPath(g.pathId);
  if(!path){ b.style.display = 'none'; return; }
  var n = path.steps.length, i = g.i;
  var step = path.steps[i];
  var prev = i > 0 ? path.steps[i-1] : null;
  var next = i < n-1 ? path.steps[i+1] : null;
  function esc(t){ return String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  var dots = '';
  for(var k=0;k<n;k++){ dots += '<span class="gb-dot'+(k===i?' on':(k<i?' done':''))+'"></span>'; }
  var html = '<div class="gb-left">'
    + '<span class="gb-live" title="Parcours en cours"><span class="gb-live-dot"></span><span class="gb-live-txt">Parcours en cours</span></span>'
    + '<button class="gb-role" onclick="guidedReopen(\''+g.pathId+'\')" title="Revenir au parcours complet">'+esc(path.icon)+' '+esc(path.role)+'</button>'
    + '<div class="gb-prog"><span class="gb-step">\u00c9tape '+(i+1)+' / '+n+' \u00b7 '+esc(step.label)+'</span><span class="gb-dots">'+dots+'</span></div>'
    + '</div>'
    + '<div class="gb-actions">';
  if(prev) html += '<button class="gb-btn" onclick="guidedStartStep(\''+g.pathId+'\','+(i-1)+')" title="'+esc(prev.label)+'">\u2190 Pr\u00e9c\u00e9dent</button>';
  if(next) html += '<button class="gb-btn gb-next gb-next-anim" onclick="guidedStartStep(\''+g.pathId+'\','+(i+1)+')">Suivant : '+esc(next.label)+' <span class="gb-arrow">\u2192</span></button>';
  else html += '<button class="gb-btn gb-next" onclick="guidedEndBanner()">Terminer \u2713</button>';
  html += '<button class="gb-close" title="Quitter le parcours" onclick="guidedEndBanner()">\u00d7</button>';
  html += '</div>';
  b.innerHTML = html;
  b.style.display = 'flex';
};

window.guidedEndBanner = function(){
  window.__activeGuided = null;
  var b = document.getElementById('guided-banner');
  if(b) b.style.display = 'none';
};

window.guidedReopen = function(pathId){
  if(pathId === 'mon-parcours'){ guidedStartStep('mon-parcours', 0); return; }
  guidedPathsOpen();
  var sel = document.getElementById('guided-paths-select');
  if(sel){ sel.value = pathId; if(typeof guidedPathsRenderSelected === 'function') guidedPathsRenderSelected(pathId); }
};

/* Le remplissage a lieu au chargement : la barre latérale existe dès le
   balisage, le catalogue seulement une fois ce script exécuté. */
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', function(){ sbRolesRemplir(); });
} else { sbRolesRemplir(); }

window.guidedPathsClose = function(){
  var modal = document.getElementById('guided-paths-modal');
  if(modal) modal.classList.remove('on');
  /* La barre latérale doit redire la VÉRITÉ : le rôle reste affiché s'il est
     réellement en cours, et repart à vide si la fenêtre a été refermée sans
     rien lancer. Sans ce retour à vide, rechoisir le même rôle ne déclenche
     aucun « change » et la liste devient une commande morte au deuxième essai.
     « Mon parcours chiffré » ne figure pas dans la liste : la valeur retombe
     alors à vide, ce qui est exact — aucun rôle du catalogue n'est en cours. */
  var sb = document.getElementById('sb-role');
  if(sb) sb.value = (window.__activeGuided && window.__activeGuided.pathId) || '';
};



