/* ══ CLOCHE DE NOTIFICATIONS — agrege veille + rapports (serveur) + audit (local) ══ */
function bellComputeAuditPending(){
  try{
    var state = JSON.parse(localStorage.getItem('cpAuditState') || '{}');
    var total = 0, pending = 0;
    if(typeof AUDIT_SECTIONS !== 'undefined'){
      AUDIT_SECTIONS.forEach(function(sec){
        sec.items.forEach(function(item){
          total++;
          var st = state[item.id] || 'none';
          if(st === 'none') pending++;
        });
      });
    }
    return pending;
  } catch(e){ return 0; }
}

window.bellRefresh = function(){
  var bellEl = document.getElementById('sb-bell-el');
  if(!bellEl) return;
  var auditPending = bellComputeAuditPending();

  fetch('/api/notifications/summary').then(function(r){ return r.json(); }).then(function(d){
    window.__bellData = {
      veille: d.veille || {count:0, items:[]},
      rapports: d.rapports || {count:0, items:[]},
      audit: {count: auditPending}
    };
    var total = window.__bellData.veille.count + window.__bellData.rapports.count + auditPending;
    bellEl.classList.toggle('has-notif', total > 0);
    var badge = document.getElementById('sb-bell-badge');
    if(badge) badge.textContent = total > 99 ? '99+' : (total || '');
  }).catch(function(){
    window.__bellData = {veille:{count:0,items:[]}, rapports:{count:0,items:[]}, audit:{count: auditPending}};
  }).catch(function(){ /* erreur reseau : ne pas bloquer, plan indetermine */ window.__SENTINEL_PLAN = null; });
};

window.bellToggleMenu = function(){
  var existing = document.getElementById('sb-bell-menu');
  if(existing){ existing.remove(); return; }
  var d = window.__bellData || {veille:{count:0,items:[]}, rapports:{count:0,items:[]}, audit:{count:0}};

  function section(title, count, itemsHtml, emptyMsg){
    return '<div class="sb-bell-section"><div class="sb-bell-section-head">'+title+' <span class="sb-bell-count">'+count+'</span></div>'
      + (count > 0 ? itemsHtml : '<div class="sb-bell-empty">'+emptyMsg+'</div>') + '</div>';
  }

  var veilleHtml = (d.veille.items||[]).map(function(it){
    return '<a class="sb-bell-item" href="'+(it.link||'#')+'" target="_blank" rel="noopener">⚠️ '+it.title+'</a>';
  }).join('');
  var rapportsHtml = (d.rapports.items||[]).map(function(it){
    var date = new Date(it.date).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
    return '<div class="sb-bell-item">📄 '+it.sujet+' <span class="sb-bell-item-date">'+date+'</span></div>';
  }).join('');
  var auditHtml = d.audit.count > 0
    ? '<div class="sb-bell-item sb-bell-item-link" onclick="bellToggleMenu();go(\'audit-ia-act\')">→ Voir les points à traiter</div>'
    : '';

  var menu = document.createElement('div');
  menu.id = 'sb-bell-menu';
  menu.className = 'sb-bell-menu';
  menu.innerHTML =
    section('⚠️ Veille à fort impact', d.veille.count, veilleHtml, 'Aucune alerte à fort impact actuellement.')
    + section('📄 Rapports envoyés (48h)', d.rapports.count, rapportsHtml, 'Aucun rapport automatique récent.')
    + section('📋 Audit IA Act', d.audit.count, auditHtml, 'Tous les points sont traités. 👍');

  document.querySelector('.sb-pager').appendChild(menu);
};

document.addEventListener('click', function(e){
  var menu = document.getElementById('sb-bell-menu');
  if(menu && !menu.contains(e.target) && e.target.id !== 'sb-bell-el' && !e.target.closest('#sb-bell-el')){
    menu.remove();
  }
});

_auDomPret(window.bellRefresh, 400);



