/* ══ NAVIGATION ENTRE SECTIONS DE LA SIDEBAR — fleches precedent/suivant ══ */
function pagerGetSections(){
  /* LES RUBRIQUES MASQUÉES PAR LE FILTRE SONT ÉCARTÉES : repliées, leur
     `offsetTop` vaut zéro, et les flèches précédent/suivant sautaient alors
     toutes au même endroit. */
  return Array.prototype.slice.call(document.querySelectorAll('.sb-nav .sb-section'))
    .filter(function(s){ return s.offsetParent !== null; });
}

function pagerCurrentIndex(){
  var sections = pagerGetSections();
  var sbEl = document.querySelector('.sb');
  if(!sbEl || !sections.length) return 0;
  var scrollTop = sbEl.scrollTop;
  var current = 0;
  for(var i=0; i<sections.length; i++){
    if(sections[i].offsetTop - sbEl.offsetTop <= scrollTop + 40) current = i;
  }
  return current;
}

window.pagerGo = function(direction){
  var sections = pagerGetSections();
  var sbEl = document.querySelector('.sb');
  if(!sbEl || !sections.length) return;
  var idx = pagerCurrentIndex() + direction;
  idx = Math.max(0, Math.min(sections.length - 1, idx));
  sections[idx].scrollIntoView({behavior:'smooth', block:'start'});
};



