window.shadowAiTab = function(tab){
  ['cas','registre','sia'].forEach(function(t){
    document.getElementById('shadow-panel-'+t).style.display = t===tab ? '' : 'none';
    var btn = document.getElementById('shadow-tab-'+t);
    if(btn) btn.className = 'shadow-ai-tab' + (t===tab?' on':'');
  });
  if(tab==='registre') shadowAiRenderRegistre();
  if(tab==='sia') shadowAiRenderSIA();
  if(tab==='cas'){
    var sel = document.getElementById('shadow-risk-filter');
    if(sel && !sel.value) shadowAiFilterByRisk();
  }
};

window.shadowAiRender = function(){
  var sel = document.getElementById('shadow-risk-filter');
  if(sel) sel.options[0].text = '🔍 Tous les niveaux de risque (' + SHADOW_AI_CASES.length + ')';
  shadowAiFilterByRisk();
};

window.shadowAiToggle = function(i){
  var body = document.getElementById('shadow-ai-body-'+i);
  var chev = document.getElementById('shadow-ai-chev-'+i);
  if(!body) return;
  var isOpen = body.classList.contains('open');
  body.classList.toggle('open', !isOpen);
  if(chev) chev.style.transform = isOpen ? '' : 'rotate(180deg)';
};

window.shadowAiRenderRegistre = function(){
  var holder = document.getElementById('shadow-registre-list');
  if(!holder || holder.innerHTML) return;
  holder.innerHTML = SHADOW_AI_REGISTRE_FIELDS.map(function(f){
    return '<div class="shadow-ai-reg-card">'
      + '<h4>📝 '+f.label+'</h4>'
      + '<div>'+f.desc+'</div>'
      + '</div>';
  }).join('');
};

window.shadowAiRenderSIA = function(){
  var holder = document.getElementById('shadow-sia-list');
  if(!holder || holder.innerHTML) return;
  holder.innerHTML = SHADOW_AI_SIA_STEPS.map(function(s){
    return '<div class="shadow-ai-reg-card">'
      + '<h4><span style="background:var(--blue);color:#fff;border-radius:50%;width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;font-size:10px;flex-shrink:0">'+s.step+'</span> '+s.label+'</h4>'
      + '<div>'+s.desc+'</div>'
      + '</div>';
  }).join('');
};

/* ── Filtre par niveau de risque ──
   Mappe chaque valeur de liste déroulante aux tags présents dans SHADOW_AI_CASES.
   Les tags couvrent : Haut risque, Haut risque / Interdit, Fournisseur de fait,
   Déployeur, Déployeur/Fournisseur, Art. 50§1, Art. 50§2, Art. 50§2-4,
   GPAI / Art. 50, Infrastructure critique, À évaluer, Indirect */
/* Navigue vers le Simulateur en pré-remplissant l'étape 1 avec les données du cas Shadow AI */
window.shadowAiGoSimulator = function(c){
  go('simulateur', null, 'CARTOGRAPHIER', 'Simulateur IA Act');
  /* Attendre que la page Simulateur soit rendue dans le DOM avant de remplir */
  setTimeout(function(){
    var nameEl = document.getElementById('sim-name');
    var sectEl = document.getElementById('sim-secteur');
    var typeEl = document.getElementById('sim-type');
    if(nameEl && c.sim_nom){
      nameEl.value = c.sim_nom;
      /* Déclencher un flash visuel pour signaler le pré-remplissage */
      nameEl.style.transition = 'box-shadow .3s';
      nameEl.style.boxShadow = '0 0 0 3px rgba(28,90,138,.35)';
      setTimeout(function(){ nameEl.style.boxShadow = ''; }, 1200);
    }
    if(sectEl && c.sim_secteur) sectEl.value = c.sim_secteur;
    if(typeEl && c.sim_type)    typeEl.value = c.sim_type;
    /* Afficher un bandeau de confirmation discret en haut de l'étape 1 */
    var panel1 = document.getElementById('sim-panel-1');
    if(panel1 && c.sim_nom){
      var existing = document.getElementById('sim-prefill-notice');
      if(existing) existing.remove();
      var notice = document.createElement('div');
      notice.id = 'sim-prefill-notice';
      notice.style.cssText = 'background:rgba(28,90,138,.07);border-left:3px solid var(--blue);padding:8px 14px;font-size:11.5px;color:var(--ink2);margin-bottom:14px;border-radius:4px';
      notice.innerHTML = '✅ Pré-rempli depuis Shadow AI — <strong>' + c.title + '</strong>. Complétez et ajustez si nécessaire.';
      panel1.insertBefore(notice, panel1.firstChild);
    }
  }, 120);
};

window.shadowAiFilterByRisk = function(){
  var sel = document.getElementById('shadow-risk-filter');
  var filter = sel ? sel.value : '';
  var holder = document.getElementById('shadow-ai-list');
  var emptyMsg = document.getElementById('shadow-filter-empty');
  var countEl = document.getElementById('shadow-filter-count');
  if(!holder) return;

  var matchFn = {
    '':       function(){ return true; },
    'haut':   function(c){ return c.tag.indexOf('Haut risque') !== -1 && c.tag.indexOf('Interdit') === -1; },
    'interdit': function(c){ return c.tag.indexOf('Interdit') !== -1; },
    'art50':  function(c){ return c.tag.indexOf('Art. 50') !== -1 && c.tag.indexOf('GPAI') === -1; },
    'infra':  function(c){ return c.tag.indexOf('Infrastructure') !== -1; },
    'gpai':   function(c){ return c.tag.indexOf('GPAI') !== -1; },
    'evaluer':function(c){ return c.tag === 'À évaluer' || c.tag === 'Indirect' ||
                                  c.tag === 'Déployeur' || c.tag === 'Déployeur/Fournisseur' ||
                                  c.tag === 'Fournisseur de fait'; }
  }[filter] || function(){ return true; };

  var filtered = SHADOW_AI_CASES.map(function(c,i){ return {c:c,i:i}; }).filter(function(x){ return matchFn(x.c); });

  if(filtered.length === 0){
    holder.innerHTML = '';
    if(emptyMsg) emptyMsg.style.display = 'block';
  } else {
    if(emptyMsg) emptyMsg.style.display = 'none';
    holder.innerHTML = filtered.map(function(x){
      var c = x.c; var i = x.i;
      return '<div class="shadow-ai-card">'
        + '<div class="shadow-ai-card-head" onclick="shadowAiToggle('+i+')" title="Cliquer pour déplier">'
        + '<div class="shadow-ai-card-title">'+c.icon+' '+c.title+'</div>'
        + '<div style="display:flex;align-items:center;gap:8px">'
        + '<span class="shadow-ai-card-tag" style="background:'+c.tagColor+'22;color:'+c.tagColor+';border:1px solid '+c.tagColor+'44">'+c.tag+'</span>'
        + '<span id="shadow-ai-chev-'+i+'" style="color:var(--muted);font-size:11px;transition:transform .18s">▾</span>'
        + '</div></div>'
        + '<div id="shadow-ai-body-'+i+'" class="shadow-ai-card-body">'
        + '<div style="margin-bottom:7px"><strong>Exemples :</strong> '+c.examples+'</div>'
        + '<div style="margin-bottom:7px"><strong>Applicable ?</strong> '+c.applicable+'</div>'
        + '<div style="margin-bottom:8px"><strong>Obligation :</strong> '+c.obligation+'</div>'
        + '<div style="background:rgba(28,90,138,.06);border-left:3px solid var(--blue);padding:8px 10px;border-radius:4px;margin-bottom:8px"><strong>💡 Conseil :</strong> '+c.conseil+'</div>'
        + '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:4px">'
        + '<button class="histo-btn-sm" onclick="go(\'registre\',null,\'CONFORMITÉ\',\'Systèmes IA\');return false" title="Ajouter ce systeme au Registre IA">📁 Ajouter au Registre</button>'
        + '<button class="histo-btn-sm" onclick="shadowAiGoSimulator(SHADOW_AI_CASES['+i+']);return false" title="Classifier ce systeme dans le Simulateur — champs pré-remplis automatiquement">⚙️ Simulateur ↗</button>'
        + (c.fria ? '<button class="histo-btn-sm" onclick="go(\'fria\',null,\'CONFORMITÉ\',\'Évaluation FRIA\');return false" title="Evaluer l\'impact sur les droits fondamentaux">⚖️ FRIA</button>' : '')
        + '</div></div></div>';
    }).join('');
  }

  /* Compteur de résultats */
  if(countEl){
    var RISK_LABELS = {
      '':'',
      'haut':'Haut risque Annexe III',
      'interdit':'Pratiques potentiellement interdites',
      'art50':'Obligations de transparence Art. 50',
      'infra':'Infrastructure critique',
      'gpai':'Modèles GPAI',
      'evaluer':'À évaluer / Déployeur / Indirect'
    };
    countEl.textContent = filter
      ? filtered.length + ' cas · ' + RISK_LABELS[filter]
      : '';
  }
};

var _shadowAiOrigGo = window.go;
window.go = function(id){
  var r = _shadowAiOrigGo ? _shadowAiOrigGo.apply(this, arguments) : undefined;
  if(id === "shadow-ai") setTimeout(window.shadowAiRender, 50);
  if(id === "simulateur") setTimeout(aiActTimelineRender, 50);
  return r;
};



