function aiActTimelineRender(){
  var tbody = document.getElementById('ai-act-timeline-body');
  if(!tbody) return;
  var today = new Date();
  tbody.innerHTML = AI_ACT_TIMELINE.map(function(row, i){
    var isNext = row.statut === 'prochain';
    var isPast = row.statut === 'passe';
    var rowBg = isNext ? 'background:rgba(28,90,138,.07)' : '';
    var dateBg = isNext
      ? 'background:var(--blue);color:#fff;border-radius:4px;padding:2px 8px'
      : isPast
        ? 'color:var(--muted)'
        : 'color:var(--ink2)';
    var border = isNext ? 'border-left:3px solid var(--blue)' : 'border-left:3px solid transparent';
    return '<tr style="border-bottom:1px solid var(--rule);'+rowBg+';'+border+'">'
      + '<td style="padding:10px 16px;white-space:nowrap;vertical-align:top"><span style="'+dateBg+';font-family:var(--mono);font-size:10.5px;font-weight:700">'
      + (isNext ? '⚡ ' : isPast ? '✅ ' : '⏳ ')
      + row.date+'</span>'
      + '<div style="font-size:9px;color:var(--muted);font-family:var(--mono);margin-top:3px">'+row.ref+'</div></td>'
      + '<td style="padding:10px 16px;vertical-align:top;color:'+(isPast?'var(--muted)':'var(--ink2)')+';line-height:1.5">'+row.quoi+'</td>'
      + '<td style="padding:10px 16px;vertical-align:top;color:'+(isPast?'var(--muted)':'var(--ink)')+';line-height:1.5;font-weight:'+(isNext?'500':'400')+'">'+row.retenir+'</td>'
      + '</tr>';
  }).join('');
}

