/* ══ FILTRER LA BARRE LATÉRALE, ET L'ATTEINDRE AU CLAVIER ══════════════════

   CE QUI EST FILTRÉ EST LU DU DOCUMENT, jamais d'une liste écrite ici : une
   liste recopiée cesserait d'être vraie au premier onglet ajouté, sans que
   rien ne le signale — l'onglet neuf serait simplement introuvable.

   LA COMPARAISON IGNORE LES ACCENTS ET LA CASSE. « evaluer » doit trouver
   « Évaluer », sinon le filtre ne sert qu'à ceux qui savent déjà écrire
   l'intitulé exact.                                                        */

window.sbFiltrer = function(q){
  var nav = document.querySelector('.sb-nav');
  if(!nav) return;
  var pli = function(t){
    t = (t || '').toLowerCase();
    try { t = t.normalize('NFD').replace(/[̀-ͯ]/g, ''); } catch(e){}
    return t.replace(/\s+/g, ' ').trim();
  };
  var m = pli(q);
  var secs = Array.prototype.slice.call(nav.querySelectorAll('.sb-section'));
  var total = 0, vus = 0;
  secs.forEach(function(sec){
    var visibles = 0;
    var n = sec.nextElementSibling;
    while(n && !n.classList.contains('sb-section')){
      if(n.classList.contains('sb-item')){
        total++;
        /* Le nom de la RUBRIQUE compte aussi : qui tape « rgpd » attend les
           neuf onglets du groupe, pas seulement ceux dont l'intitulé le
           répète. */
        var texte = pli(n.textContent) + ' ' + pli(sec.textContent);
        var ok = !m || texte.indexOf(m) !== -1;
        if(ok){ n.removeAttribute('hidden'); visibles++; vus++; }
        else n.setAttribute('hidden', '');
      }
      n = n.nextElementSibling;
    }
    if(visibles) sec.removeAttribute('hidden');
    else sec.setAttribute('hidden', '');
  });
  var cpt = document.getElementById('sb-filtre-cpt');
  if(cpt){
    /* LE COMPTE EST DÉRIVÉ DE CE QUI VIENT D'ÊTRE MASQUÉ, pas d'un total
       écrit à la main : les deux ne peuvent pas diverger. */
    if(!m) cpt.textContent = '';
    else if(vus === 0) cpt.textContent = 'aucun onglet ne correspond';
    else cpt.textContent = vus + ' onglet' + (vus > 1 ? 's' : '') + ' sur ' + total;
    cpt.classList.toggle('vide', !!m && vus === 0);
  }
};

/* ENTRÉE ET ESPACE ACTIVENT L'ONGLET. Sans cela, `tabindex` ne ferait que
   promettre un accès qu'on n'a pas : on atteindrait l'onglet sans pouvoir
   l'ouvrir. L'espace est retenu, sinon il ferait défiler la page sous le
   doigt. */
document.addEventListener('keydown', function(e){
  var el = e.target;
  if(!el || !el.classList || !el.classList.contains('sb-item')) return;
  if(e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar'){
    e.preventDefault();
    el.click();
  }
});

